/* Plainkit a11y layer: loaded LAST, because these rules must beat the component defaults at equal specificity.
   Keyboard focus ring for every interactive control, tap behaviour, and the phone rules
   (16px inputs so iOS does not zoom on focus; 44px touch targets). */

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
    outline: var(--focus-ring);
    outline-offset: 2px;
}

button,
a.btn-primary,
a.btn-ghost,
a.btn-warn,
a.btn-secondary,
.tab,
.tab-close,
select,
summary {
    touch-action: manipulation;
}

@media (max-width: 640px) {
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]),
    select,
    textarea {
        font-size: 16px !important;
    }

    button.btn-primary,
    button.btn-ghost,
    button.btn-warn,
    button.btn-secondary,
    button.btn-mini,
    a.btn-primary,
    a.btn-ghost,
    a.btn-warn,
    a.btn-secondary,
    .tab,
    .tab-close,
    .chip-btn,
    a.btn-mini,
    .snav-link,
    .tnav-link,
    .dropdown-item,
    .page-link,
    .pill,
    .btn-group > *,
    summary,
    select,
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]) {
        min-height: var(--touch-target);
    }
}

/* Plainkit base: reset, typography, form-control and link baselines. Element selectors only, so a component class always wins. */

* {
    box-sizing: border-box;
}

html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    font-family: var(--font-sans);
    background: var(--color-bg);
    color: var(--color-text);
    font-size: 14px;
}

/* Form-control baseline: themed surface and readable text. Element selectors, so a component class still wins. */

:where(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]),
textarea,
select) {
    background: var(--color-input);
    color: var(--color-text);
    border: 1px solid var(--color-input-border);
}

input::placeholder,
textarea::placeholder {
    color: var(--color-muted);
    opacity: 1;   /* Firefox dims placeholders by default; keep them legible */
}

/* Global link baseline, and the same argument as the form controls above: an
   unstyled control inherits the browser's defaults, which were never chosen
   against this palette. A bare <a> rendered in default browser blue — roughly 2.3:1 on the
   dark panel, and the purple :visited variant is worse — which is what the
   "Tools → File importer" links in the order page's cards were doing.

   Scoped with :not([class]) rather than to every anchor on purpose. An anchor
   that carries a class has been dressed deliberately — a.btn-primary, the docs
   nav, the help-flyout footer — and a blanket `a { }` would fight all of them
   over colour and underline. This targets exactly the case that has no answer
   at all. Note it ties on specificity with rules like .docs-body a, so it sits
   here near the top of the file where source order lets those win. */

a:not([class]) {
    color: var(--color-link);
    text-decoration: underline;
    text-underline-offset: 0.15em;
}

a:not([class]):hover {
    color: var(--color-link-hover);
}

.required {
    color: var(--color-required);
}

.form-error {
    color: var(--color-notice-error);
    margin: var(--space-1) 0 var(--space-2) 0;
    font-size: var(--text-md);
}

.muted {
    color: var(--color-muted);
}

[hidden] {
    display: none !important;
}

/* Base rhythm. Every rule is wrapped in :where() so it has ZERO specificity: it gives raw content sensible spacing by default and
   any component or page rule that sets its own margin simply wins. Roles come from tokens.css (--gap-heading, --space-*). */

:where(h1, h2, h3, h4, h5, h6) {
    margin-block: 0 var(--gap-heading);
    line-height: 1.25;
}

:where(p, ul, ol, dl, blockquote, pre, figure, fieldset) {
    margin-block: 0 var(--space-3);
}

:where(p, ul, ol, dl, blockquote, pre, figure, fieldset):last-child {
    margin-block-end: 0;
}

:where(ul, ol) {
    padding-inline-start: var(--space-6);
}

:where(li + li) {
    margin-block-start: var(--space-1);
}

:where(blockquote) {
    padding-inline-start: var(--space-4);
    border-inline-start: 3px solid var(--color-border);
    color: var(--color-muted);
}

:where(pre) {
    padding: var(--space-3);
    background: var(--color-surface-alt);
    border-radius: var(--radius-sm);
    font-size: var(--text-sm);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

:where(hr) {
    margin-block: var(--space-4);
    border: 0;
    border-top: 1px solid var(--color-border);
}

:where(fieldset) {
    padding: var(--pad-form-section);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
}

:where(legend) {
    padding-inline: var(--space-1);
    color: var(--color-muted);
}

/* Spacing: the vertical rhythm and the exception utilities. Every value is a token from the one scale; there are no literals here.
   .flow gives stacked siblings the default rhythm; .stack is the same as a flex column with a gap; .p-* .m-* .gap-* are for the exceptions. */

.flow > * + * { margin-block-start: var(--flow-space); }

.flow-sm { --flow-space: var(--space-2); }

.flow-lg { --flow-space: var(--space-6); }

.stack { display: flex; flex-direction: column; gap: var(--flow-space); min-width: 0; }

.stack-sm { gap: var(--space-2); }

.stack-lg { gap: var(--gap-section); }

/* Page and section spacing. */
.page-gutter { padding: var(--pad-page); }

.section + .section { margin-block-start: var(--gap-section); }

.p-0 { padding: 0; }
.px-0 { padding-inline: 0; }
.py-0 { padding-block: 0; }
.pt-0 { padding-block-start: 0; }
.pb-0 { padding-block-end: 0; }
.m-0 { margin: 0; }
.mx-0 { margin-inline: 0; }
.my-0 { margin-block: 0; }
.mt-0 { margin-block-start: 0; }
.mb-0 { margin-block-end: 0; }
.gap-0 { gap: 0; }
.p-1 { padding: var(--space-1); }
.px-1 { padding-inline: var(--space-1); }
.py-1 { padding-block: var(--space-1); }
.pt-1 { padding-block-start: var(--space-1); }
.pb-1 { padding-block-end: var(--space-1); }
.m-1 { margin: var(--space-1); }
.mx-1 { margin-inline: var(--space-1); }
.my-1 { margin-block: var(--space-1); }
.mt-1 { margin-block-start: var(--space-1); }
.mb-1 { margin-block-end: var(--space-1); }
.gap-1 { gap: var(--space-1); }
.p-2 { padding: var(--space-2); }
.px-2 { padding-inline: var(--space-2); }
.py-2 { padding-block: var(--space-2); }
.pt-2 { padding-block-start: var(--space-2); }
.pb-2 { padding-block-end: var(--space-2); }
.m-2 { margin: var(--space-2); }
.mx-2 { margin-inline: var(--space-2); }
.my-2 { margin-block: var(--space-2); }
.mt-2 { margin-block-start: var(--space-2); }
.mb-2 { margin-block-end: var(--space-2); }
.gap-2 { gap: var(--space-2); }
.p-3 { padding: var(--space-3); }
.px-3 { padding-inline: var(--space-3); }
.py-3 { padding-block: var(--space-3); }
.pt-3 { padding-block-start: var(--space-3); }
.pb-3 { padding-block-end: var(--space-3); }
.m-3 { margin: var(--space-3); }
.mx-3 { margin-inline: var(--space-3); }
.my-3 { margin-block: var(--space-3); }
.mt-3 { margin-block-start: var(--space-3); }
.mb-3 { margin-block-end: var(--space-3); }
.gap-3 { gap: var(--space-3); }
.p-4 { padding: var(--space-4); }
.px-4 { padding-inline: var(--space-4); }
.py-4 { padding-block: var(--space-4); }
.pt-4 { padding-block-start: var(--space-4); }
.pb-4 { padding-block-end: var(--space-4); }
.m-4 { margin: var(--space-4); }
.mx-4 { margin-inline: var(--space-4); }
.my-4 { margin-block: var(--space-4); }
.mt-4 { margin-block-start: var(--space-4); }
.mb-4 { margin-block-end: var(--space-4); }
.gap-4 { gap: var(--space-4); }
.p-5 { padding: var(--space-5); }
.px-5 { padding-inline: var(--space-5); }
.py-5 { padding-block: var(--space-5); }
.pt-5 { padding-block-start: var(--space-5); }
.pb-5 { padding-block-end: var(--space-5); }
.m-5 { margin: var(--space-5); }
.mx-5 { margin-inline: var(--space-5); }
.my-5 { margin-block: var(--space-5); }
.mt-5 { margin-block-start: var(--space-5); }
.mb-5 { margin-block-end: var(--space-5); }
.gap-5 { gap: var(--space-5); }
.p-6 { padding: var(--space-6); }
.px-6 { padding-inline: var(--space-6); }
.py-6 { padding-block: var(--space-6); }
.pt-6 { padding-block-start: var(--space-6); }
.pb-6 { padding-block-end: var(--space-6); }
.m-6 { margin: var(--space-6); }
.mx-6 { margin-inline: var(--space-6); }
.my-6 { margin-block: var(--space-6); }
.mt-6 { margin-block-start: var(--space-6); }
.mb-6 { margin-block-end: var(--space-6); }
.gap-6 { gap: var(--space-6); }
.p-8 { padding: var(--space-8); }
.px-8 { padding-inline: var(--space-8); }
.py-8 { padding-block: var(--space-8); }
.pt-8 { padding-block-start: var(--space-8); }
.pb-8 { padding-block-end: var(--space-8); }
.m-8 { margin: var(--space-8); }
.mx-8 { margin-inline: var(--space-8); }
.my-8 { margin-block: var(--space-8); }
.mt-8 { margin-block-start: var(--space-8); }
.mb-8 { margin-block-end: var(--space-8); }
.gap-8 { gap: var(--space-8); }
.p-12 { padding: var(--space-12); }
.px-12 { padding-inline: var(--space-12); }
.py-12 { padding-block: var(--space-12); }
.pt-12 { padding-block-start: var(--space-12); }
.pb-12 { padding-block-end: var(--space-12); }
.m-12 { margin: var(--space-12); }
.mx-12 { margin-inline: var(--space-12); }
.my-12 { margin-block: var(--space-12); }
.mt-12 { margin-block-start: var(--space-12); }
.mb-12 { margin-block-end: var(--space-12); }
.gap-12 { gap: var(--space-12); }
.mx-auto { margin-inline: auto; }

/* Page-level styling for the raw table slotted into <pk-table> (and the data-table chrome around it). The table is light DOM, so shadow CSS cannot
   reach its cells; these rules are keyed by the tag. The frame, toolbar slot and scrolling are in the element's shadow root. Tokens only. */
pk-table {
    & table { inline-size: 100%; border-collapse: collapse; font-size: var(--text-base); }
    & :is(th, td) { padding: var(--pad-cell); border-block-end: 1px solid var(--color-border); text-align: start; }
    & th { color: var(--color-muted); font-size: var(--text-meta); font-weight: 500; letter-spacing: 0.05em; text-transform: uppercase; }
    & :is(th, td).num { text-align: end; font-variant-numeric: tabular-nums; }
    & td code { padding: 0.1rem 0.4rem; border-radius: var(--radius-xs); background: var(--color-bg); font-size: var(--text-md); }
    & th[aria-sort] { cursor: pointer; user-select: none; }
    & th[aria-sort="ascending"]::after { content: " \2191"; }
    & th[aria-sort="descending"]::after { content: " \2193"; }
    &[striped] tbody tr:nth-child(even), &[hover] tbody tr:hover { background: var(--color-surface-alt); }
    &[density="compact"] :is(th, td) { padding: var(--space-1) var(--space-2); }
    &[sticky-header] thead th { position: sticky; inset-block-start: 0; z-index: var(--z-sticky); background: var(--color-panel); }
    & tr[aria-selected="true"] { background: var(--ft-selected-bg); }
    & tr.dg-clickable { cursor: pointer; &:hover { background: var(--dg-clickable-hover-bg); } }
    & .dg-sortable { cursor: pointer; user-select: none; &:hover { color: var(--dg-sortable-hover-fg); } }
    & .dg-select-cell { inline-size: 2.25rem; text-align: center; padding-inline: var(--space-2); }
    & :is(tfoot th, tfoot td) { font-weight: 600; }
}

/* A data table: tighter cells, a per-column filter row, and the toolbar and pager chrome. */
pk-table.dg-body {
    &::part(toolbar) { display: block; margin: 0; }
    & tbody td { padding: 0.35rem var(--space-2); font-size: var(--text-read); }
    & thead th { padding: 0.4rem var(--space-2); font-size: var(--text-meta); font-weight: 600; letter-spacing: 0.02em; }
    & .dg-filterrow th { padding: 0.15rem 0.3rem; border-block-start: 1px solid var(--color-border); background: var(--color-panel); font-weight: normal; }
    & .dg-filter-input { inline-size: 100%; padding: 0.2rem 0.35rem; border: 1px solid var(--color-border); border-radius: var(--radius-xs); background: var(--color-bg); color: inherit; font-size: var(--text-meta); }
}

@media (max-width: 640px) {

    /* a table grid: rows scroll in a bounded frame, the header and the identity column stay put */
    pk-table.dg-body {
        &:has(table:not(.dg-cards)) { --pk-table-max-height: max(14rem, calc(100dvh - var(--app-header-h) - var(--app-footer-h) - 16rem)); }
        &::part(scroll) { overscroll-behavior: contain; }
        & :is(th, td) { padding: var(--space-2); }
        & table:not(.dg-cards) {
            & :is(th, td):first-child, & .dg-select-cell + :is(th, td) { position: sticky; inset-inline-start: 0; z-index: 2; background: var(--color-panel); box-shadow: inset -1px 0 0 var(--color-border); }
            & .dg-select-cell + :is(th, td) { inset-inline-start: 2.5rem; }
            & thead { position: sticky; inset-block-start: 0; z-index: 5; background: var(--color-panel); }
            & thead th { position: relative; z-index: 3; background: var(--color-panel); }
            & thead > tr:last-child > th { box-shadow: inset 0 -1px 0 var(--color-border); }
            & thead :is(th:first-child, .dg-select-cell + th) { position: sticky; z-index: 4; box-shadow: inset -1px 0 0 var(--color-border), inset 0 -1px 0 var(--color-border); }
            & tfoot :is(th, td) { position: sticky; inset-block-end: 0; z-index: 3; background: var(--color-panel); box-shadow: inset 0 1px 0 var(--color-border); }
            & tbody td { white-space: normal; overflow-wrap: anywhere; &:not(.num) { min-inline-size: 5rem; } &.num { white-space: nowrap; overflow-wrap: normal; } &:first-child, &.dg-select-cell + td { min-inline-size: 7rem; max-inline-size: 11rem; } }
        }
        /* columns a page marks HideOnPhone (the grid adds dg-ph-N for the 1-based position) */
        & table.dg-ph-2 :is(th, td):nth-child(2),
        & table.dg-ph-3 :is(th, td):nth-child(3),
        & table.dg-ph-4 :is(th, td):nth-child(4),
        & table.dg-ph-5 :is(th, td):nth-child(5),
        & table.dg-ph-6 :is(th, td):nth-child(6),
        & table.dg-ph-7 :is(th, td):nth-child(7),
        & table.dg-ph-8 :is(th, td):nth-child(8),
        & table.dg-ph-9 :is(th, td):nth-child(9),
        & table.dg-ph-10 :is(th, td):nth-child(10),
        & table.dg-ph-11 :is(th, td):nth-child(11),
        & table.dg-ph-12 :is(th, td):nth-child(12),
        & table.dg-ph-13 :is(th, td):nth-child(13),
        & table.dg-ph-14 :is(th, td):nth-child(14) { display: none; }
        /* card rows: each row a card, each cell a labelled line (data-label) */
        & table.dg-cards {
            &, & tbody { display: block; }
            & thead { display: none; }
            & tbody tr { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.3rem 0.75rem; margin-block-end: 0.6rem; padding: 0.7rem 0.75rem; border: 1px solid var(--color-border); border-radius: var(--radius-lg); background: var(--color-panel); &:has(td[colspan]) { display: table-row; padding: 0; border: 0; background: none; } }
            & tbody td { display: block; flex: 1 1 100%; min-inline-size: 0; padding: 0; border: 0; text-align: start; white-space: normal; overflow-wrap: anywhere; &:first-child { font-weight: 600; } &:empty, &[data-card-hide] { display: none; } &[data-label] { display: flex; align-items: baseline; gap: 0.4rem; &::before { content: attr(data-label); flex: none; min-inline-size: 5.5rem; color: var(--dg-card-label-fg); font-size: var(--text-meta); letter-spacing: 0.04em; text-transform: uppercase; } } }
        }
    }
}

/* Typography helpers. Global classes on purpose: prose styles arbitrary content, and a shadow root cannot reach the descendants of slotted nodes.
   Every size is a token; reading text stays at or above --text-read and meta at or above --text-meta. */
.lead { font-size: var(--text-lg); line-height: 1.5; color: var(--color-muted); max-inline-size: 65ch; }

.small { font-size: var(--text-meta); }

.display-1 { font-size: clamp(2rem, 1.4rem + 3vw, 3rem); font-weight: 700; line-height: 1.1; letter-spacing: -0.02em; text-wrap: balance; }

.display-2 { font-size: clamp(1.6rem, 1.2rem + 2vw, 2.25rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; text-wrap: balance; }

.eyebrow { font-size: var(--text-meta); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--color-muted); }

.text-balance { text-wrap: balance; }

/* Long-form content: readable measure, a steady rhythm, and sensible defaults for what an editor produces. */
.prose { max-inline-size: 70ch; line-height: 1.6; overflow-wrap: break-word; }

.prose > * + * { margin-block-start: var(--space-4); }

.prose > :is(h2, h3, h4) { margin-block-start: var(--space-8); }

.prose > :is(h2, h3, h4) + * { margin-block-start: var(--gap-heading); }

.prose :is(img, video, figure) { max-inline-size: 100%; block-size: auto; }

.prose ul,
.prose ol { padding-inline-start: var(--space-6); }

.prose li + li { margin-block-start: var(--space-1); }

.prose a:not([class]) { text-decoration: underline; text-underline-offset: 0.15em; }

.prose table { inline-size: 100%; border-collapse: collapse; }

.prose :is(th, td) { padding: var(--pad-cell); border-bottom: 1px solid var(--color-border); text-align: start; }

.prose hr { border: 0; border-block-start: 1px solid var(--color-border); margin-block: var(--space-8); }

/* Quote: the pull-quote look; cite or a figcaption gives the source. */
.quote { margin: 0; padding: var(--space-3) var(--space-5); border-inline-start: 3px solid var(--color-accent); color: var(--color-text); font-size: var(--text-lg); font-style: italic; }

figure > .quote + figcaption,
.quote > footer { margin-block-start: var(--space-2); color: var(--color-muted); font-size: var(--text-meta); font-style: normal; }

/* Inline code, and keys next to each other. */
:where(code):not(pre code) { padding: 0.1em 0.4em; border-radius: var(--radius-xs); background: var(--color-surface-alt); font-family: ui-monospace, Consolas, monospace; font-size: 0.92em; }

kbd + kbd { margin-inline-start: var(--space-1); }

.mono { font-family: ui-monospace, Consolas, monospace; font-variant-numeric: tabular-nums; }

.nowrap { white-space: nowrap; }

.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.clamp-2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* Utility classes: the small scale pages use instead of inline style="".
   Spacing steps are rem: 0=0, 1=.25, 2=.5, 3=.75, 4=1, 6=1.5. Text sizes: xs .72, sm .8, md .85.
   Literal-value classes: property abbreviation + value with '.' as p and rem as r (u-mt-p6r = margin-top .6rem). */
.u-m0 { margin: 0 !important; }
.u-mt-0 { margin-top: 0 !important; }
.u-mt-2 { margin-top: 0.5rem !important; }
.u-mt-3 { margin-top: 0.75rem !important; }
.u-ml-2 { margin-left: 0.5rem !important; }
.u-ml-4 { margin-left: 1rem !important; }
.u-pt-3 { padding-top: 0.75rem !important; }
.u-text-xs { font-size: var(--text-meta) !important; }
.u-text-sm { font-size: var(--text-read) !important; }
.u-text-md { font-size: var(--text-read) !important; }
.u-fw-normal { font-weight: 400 !important; }
.u-nowrap { white-space: nowrap !important; }
.u-w-full { width: 100% !important; }
.u-scroll-x { overflow-x: auto !important; }
.u-mt-4 { margin-top: 1rem !important; }
.u-mt-6 { margin-top: 1.5rem !important; }
.u-mt-neg { margin-top: -0.5rem !important; }
.u-mb-4 { margin-bottom: 1rem !important; }
.u-ml-3 { margin-left: 0.75rem !important; }
.u-ml-auto { margin-left: auto !important; }
.u-pointer { cursor: pointer !important; }
.u-cursor-default { cursor: default !important; }
.u-pre-wrap { white-space: pre-wrap !important; }
.u-c-border { color: var(--color-border) !important; }
.u-flex-1 { flex: 1 !important; }
.u-fs-1p05r { font-size: 1.05rem !important; }
.u-fs-1p1r { font-size: 1.1rem !important; }
.u-fs-p75em { font-size: 0.75em !important; }
.u-fs-p75r { font-size: var(--text-meta) !important; }
.u-fs-p76r { font-size: var(--text-meta) !important; }
.u-fs-p78r { font-size: var(--text-meta) !important; }
.u-fs-p7em { font-size: 0.7em !important; }
.u-fs-p7r { font-size: var(--text-meta) !important; }
.u-fs-p82r { font-size: var(--text-read) !important; }
.u-fs-p85em { font-size: 0.85em !important; }
.u-fs-p88r { font-size: var(--text-read) !important; }
.u-fs-p8em { font-size: 0.8em !important; }
.u-fs-p95r { font-size: var(--text-read) !important; }
.u-fs-p9r { font-size: var(--text-read) !important; }
.u-fw-600 { font-weight: 600 !important; }
