// Plainkit colour maths: parse a CSS colour, blend alpha over a background, WCAG relative luminance and contrast ratio.
// Pure functions; no DOM, no imports.

const HEX = /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
const FUNC = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+%?))?\s*\)$/i;

// { r, g, b, a } with r/g/b 0-255 and a 0-1, or null when the text is not a colour we can read (var(), names, hsl).
export function parseColour(text) {
    const s = String(text ?? '').trim();
    let m = HEX.exec(s);
    if (m) {
        let h = m[1];
        if (h.length <= 4) h = [...h].map(c => c + c).join('');
        const n = i => parseInt(h.slice(i, i + 2), 16);
        return { r: n(0), g: n(2), b: n(4), a: h.length === 8 ? n(6) / 255 : 1 };
    }
    m = FUNC.exec(s);
    if (m) {
        const a = m[4] === undefined ? 1 : m[4].endsWith('%') ? parseFloat(m[4]) / 100 : parseFloat(m[4]);
        return { r: +m[1], g: +m[2], b: +m[3], a };
    }
    return null;
}

// The colour a translucent foreground actually shows when laid over an opaque background.
export function blend(fg, bg) {
    const a = fg.a ?? 1;
    return { r: fg.r * a + bg.r * (1 - a), g: fg.g * a + bg.g * (1 - a), b: fg.b * a + bg.b * (1 - a), a: 1 };
}

export function luminance({ r, g, b }) {
    const lin = v => { const c = v / 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}

// WCAG contrast ratio between two colours (foreground alpha is blended over the background first); null if either is unreadable.
export function contrast(fgText, bgText) {
    const fg = typeof fgText === 'string' ? parseColour(fgText) : fgText;
    const bg = typeof bgText === 'string' ? parseColour(bgText) : bgText;
    if (!fg || !bg) return null;
    const a = luminance(blend(fg, bg));
    const b = luminance(bg);
    const [hi, lo] = a >= b ? [a, b] : [b, a];
    return (hi + 0.05) / (lo + 0.05);
}

// "4.63:1 AA" style label: AAA at 7, AA at 4.5, "below AA" under it.
export function grade(ratio, thresholds = { aaa: 7, aa: 4.5 }) {
    if (ratio === null || ratio === undefined) return 'n/a';
    return ratio >= thresholds.aaa ? 'AAA' : ratio >= thresholds.aa ? 'AA' : 'below AA';
}

// Pure logic behind the dev console (modules/console): turning any value into a short readable string, the entry list with its cap,
// level and text filters, and describing an element. No browser API is required, so node tests cover it.

export const LEVELS = Object.freeze(['debug', 'log', 'info', 'warn', 'error']);
const RANK = Object.fromEntries(LEVELS.map((l, i) => [l, i]));

// Turns a console argument into text: strings as they are, errors as name and message, objects as compact JSON with cycles and depth cut.
export function formatArg(value, depth = 2, seen = new WeakSet()) {
    if (typeof value === 'string') return value;
    if (value === null || value === undefined || typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') return String(value);
    if (typeof value === 'symbol') return value.toString();
    if (typeof value === 'function') return `[function ${value.name || 'anonymous'}]`;
    if (value instanceof Error) return `${value.name}: ${value.message}`;
    if (typeof Node !== 'undefined' && value instanceof Node) return describeNode(value);
    if (seen.has(value)) return '[circular]';
    seen.add(value);
    if (depth < 0) return Array.isArray(value) ? `[Array(${value.length})]` : '[object]';
    if (Array.isArray(value)) return `[${value.slice(0, 20).map(v => formatArg(v, depth - 1, seen)).join(', ')}${value.length > 20 ? `, ... ${value.length - 20} more` : ''}]`;
    const keys = Object.keys(value);
    return `{${keys.slice(0, 20).map(k => `${k}: ${formatArg(value[k], depth - 1, seen)}`).join(', ')}${keys.length > 20 ? `, ... ${keys.length - 20} more` : ''}}`;
}

// Console.log-style formatting: a leading %s/%d/%i/%f/%o/%O/%j string consumes arguments, the rest are appended.
export function formatArgs(args) {
    if (!args.length) return '';
    const [first, ...rest] = args;
    if (typeof first !== 'string' || !/%[sdifoOj%]/.test(first)) return args.map(a => formatArg(a)).join(' ');
    let i = 0;
    const text = first.replace(/%([sdifoOj%])/g, (m, t) => {
        if (t === '%') return '%';
        if (i >= rest.length) return m;
        const v = rest[i++];
        return t === 'd' || t === 'i' ? String(Math.trunc(Number(v))) : t === 'f' ? String(Number(v)) : formatArg(v);
    });
    return [text, ...rest.slice(i).map(a => formatArg(a))].join(' ');
}

const describeNode = n => (n.nodeType === 1 ? `<${n.localName}${n.id ? `#${n.id}` : ''}${typeof n.className === 'string' && n.className ? `.${n.className.trim().split(/\s+/).join('.')}` : ''}>` : `[${n.nodeName}]`);

// { tag, id, classes, text } for something that looks like an element (works on the DOM and on plain test doubles).
export function describeElement(el) {
    const classes = typeof el.className === 'string' ? el.className.trim().split(/\s+/).filter(Boolean) : [];
    return { tag: el.localName ?? String(el.tagName ?? '').toLowerCase(), id: el.id || '', classes, text: (el.textContent ?? '').trim().replace(/\s+/g, ' ').slice(0, 60) };
}

// A console entry. source: 'console' | 'error' | 'rejection' | 'event'.
export function makeEntry(level, text, { source = 'console', at = Date.now(), detail } = {}) {
    return { level: LEVELS.includes(level) ? level : 'log', text, source, at, ...(detail === undefined ? {} : { detail }) };
}

// Appends keeping the newest `max`. Returns a new array.
export const pushEntry = (entries, entry, max = 500) => [...entries, entry].slice(-max);

// Entries at or above `minLevel`, from the given sources (all when empty), whose text contains `text` (case-insensitive).
export function filterEntries(entries, { minLevel = 'debug', text = '', sources } = {}) {
    const needle = text.trim().toLowerCase();
    const floor = RANK[minLevel] ?? 0;
    return entries.filter(e => RANK[e.level] >= floor && (!sources?.length || sources.includes(e.source)) && (!needle || e.text.toLowerCase().includes(needle)));
}

// Counts per level, for the toolbar badges.
export function countByLevel(entries) {
    const out = Object.fromEntries(LEVELS.map(l => [l, 0]));
    for (const e of entries) out[e.level]++;
    return out;
}

// The entries as JSON text, for copying or saving.
export const exportEntries = entries => JSON.stringify(entries.map(e => ({ ...e, at: new Date(e.at).toISOString() })), null, 2);

// pk-* tags with how many of each are in the page: [{ tag, count, defined }] sorted by tag. tags: local names found in the document;
// isDefined(tag) says whether the custom element is registered.
export function elementInventory(tags, isDefined) {
    const counts = new Map();
    for (const t of tags) if (t.startsWith('pk-')) counts.set(t, (counts.get(t) ?? 0) + 1);
    return [...counts].sort(([a], [b]) => a.localeCompare(b)).map(([tag, count]) => ({ tag, count, defined: Boolean(isDefined(tag)) }));
}

// Dynamic values go through the CSSOM, never a style attribute: applyDynamic
// applies data-dyn="prop:value; --token:value" (never used in copy-paste snippets).

export function applyDynamic(root = document) {
    for (const el of root.querySelectorAll('[data-dyn]')) for (const d of el.dataset.dyn.split(';')) { const i = d.indexOf(':'); if (i > 0) el.style.setProperty(d.slice(0, i).trim(), d.slice(i + 1).trim()); }
}

// The pure parts of PkElement (no DOM): attribute/property naming, prop coercion and template bindings. Node-testable.

export const kebab = n => n.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`);
export const camel = n => n.replace(/-([a-z])/g, (_, c) => c.toUpperCase());

// Property value from a raw attribute string (fromAttr) or an assigned value. A value that cannot be used (an enum outside its values, a
// number that is NaN, json that does not parse) falls back to the default; report(problem, fallback), when given, is told so the caller can log it.
// A missing value (null, undefined) and an empty number are not mistakes: the prop is just unset.
export function coerce(def, raw, fromAttr = false, report = null) {
    switch (def.type) {
        case 'boolean': return fromAttr ? raw !== null && raw !== 'false' : Boolean(raw);
        case 'number': {
            const n = Number(raw);
            if (raw === null || raw === '' || raw === undefined) return def.default;
            if (Number.isNaN(n)) { report?.('is not a number', def.default); return def.default; }
            return n;
        }
        case 'enum':
            if (def.values.includes(raw)) return raw;
            if (raw !== null && raw !== undefined) report?.(`is not one of ${def.values}`, def.default);
            return def.default;
        case 'json': {
            if (!fromAttr) return raw === undefined ? def.default : raw;
            try { return raw === null ? def.default : JSON.parse(raw); } catch { report?.('is not valid JSON', def.default); return def.default; }
        }
        default: return raw === null || raw === undefined ? def.default : String(raw);
    }
}

// "Hello {{name}}, {{n|str}}" -> ['Hello ', {key:'name'}, ', ', {key:'n', str:true}]. |str keeps false/empty as text.
export function parseBindings(text) {
    const parts = []; let last = 0;
    for (const m of text.matchAll(/\{\{\s*([\w.]+)(\|str)?\s*\}\}/g)) {
        if (m.index > last) parts.push(text.slice(last, m.index));
        parts.push({ key: m[1], str: Boolean(m[2]) }); last = m.index + m[0].length;
    }
    if (last < text.length) parts.push(text.slice(last));
    return parts;
}

// The value of a bound text or attribute: a lone binding on an attribute removes it for false/null/undefined and sets '' for true.
export function bindValue(parts, values, isAttr = false) {
    const lone = parts.length === 1 && typeof parts[0] === 'object' && !parts[0].str;
    if (isAttr && lone) { const v = values[parts[0].key]; return v === false || v === null || v === undefined || v === '' ? null : v === true ? '' : String(v); }
    return parts.map(p => (typeof p === 'string' ? p : String(values[p.key] ?? ''))).join('');
}

// Pure logic behind the element inspector (js/element-inspector.js): turning an element's API metadata into display rows. No DOM, so node
// tests cover it.

export const kebab = s => String(s).replace(/[A-Z]/g, c => '-' + c.toLowerCase());
const show = v => (v === '' ? '""' : v === null || v === undefined ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v));
const list = a => (Array.isArray(a) ? a : []);

// The markup of a live element as an author would write it: the data-* attributes the SDK adds and an empty hidden are left out.
export const cleanMarkup = html => String(html ?? '').replace(/\s(data-[\w-]+="[^"]*")/g, '').replace(/\shidden(="")?(?=[\s>])/g, '');

// True when the metadata can be inspected: an object with a tag.
export const isElementMeta = meta => Boolean(meta && typeof meta === 'object' && typeof meta.tag === 'string' && meta.tag);

// The reference tables of an element: everything the meta declares, as rows of display strings.
export function describeElement(meta) {
    if (!isElementMeta(meta)) return null;
    return {
        tag: meta.tag,
        title: meta.title ?? meta.tag,
        group: meta.group ?? '',
        summary: meta.summary ?? '',
        props: list(meta.props).map(p => ({ name: p.name, attribute: kebab(p.name), type: p.type === 'enum' ? list(p.values).join(' | ') : String(p.type ?? ''), default: show(p.default), description: p.description ?? '' })),
        slots: list(meta.slots).map(s => ({ name: s.name || '(default)', description: s.description ?? '' })),
        events: list(meta.events).map(e => ({ name: e.name, detail: show(e.detail), description: e.description ?? '' })),
        parts: list(meta.parts).map(p => ({ selector: `${meta.tag}::part(${p.name})`, description: p.description ?? '' })),
        cssProperties: list(meta.cssProperties).map(c => ({ name: c.name, default: show(c.default), description: c.description ?? '' })),
        methods: list(meta.methods).map(m => ({ name: m.name, description: m.description ?? '' })),
    };
}

// The element inspector: shows what an element is, from its API metadata, and what it looks like right now. It draws the element's tag and
// summary, its live markup (with a copy button), then the properties, slots, events, CSS parts and properties and methods. The gallery's
// docked Details drawer uses it; a layout builder can use it for the selected element. A host adds its own sections with extraSections.
// Built only from SDK components (pk-stack, pk-accordion, pk-accordion-item, pk-code-block, pk-table, pk-empty-state); it makes no markup
// strings and loads nothing: the host has already started the elements (initPlainkit) and passes the API data.
//
//   const inspector = createElementInspector(container);
//   inspector.show({ meta, element, extraSections });   // meta: the element's API entry; element: the live element (optional)
//   inspector.refresh();                                // the live element changed: redraw the markup and the extra sections
//   inspector.show(null);                               // nothing selected: an empty state that says what the inspector shows
//   inspector.destroy();
//
// show({ meta, element, markup, extraSections }): element is the live element (its markup follows it); markup replaces the live markup with
// fixed text when there is no element. extraSections is an array of { title, render(container, { meta, element }), open? }: each becomes a
// pk-accordion-item after the built-in ones, and render fills its container with SDK components (it runs on show() and on every refresh()).
// A render that throws is logged (scope element-inspector) and its section shows a short note; the others still draw.
// Pure logic is js/element-inspector-logic.js.

import { createLogger } from './log.js';
import { describeElement, cleanMarkup } from './element-inspector-logic.js';

const log = createLogger('element-inspector');

const h = (tag, attrs = {}, ...kids) => {
    const el = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) { if (v === false || v === null || v === undefined) continue; el.setAttribute(k, v === true ? '' : v); }
    el.append(...kids.filter(k => k !== null && k !== undefined && k !== false));
    return el;
};
const code = text => h('code', {}, text);

function table(label, cols, rows) {
    return h('pk-table', { label }, h('table', {},
        h('thead', {}, h('tr', {}, ...cols.map(c => h('th', {}, c)))),
        h('tbody', {}, ...rows.map(r => h('tr', {}, ...r.map(c => h('td', {}, c)))))));
}

const EMPTY_TEXT = 'Open an element page to see its tag, properties, slots, events, styling hooks and its live markup with a copy button.';

export function createElementInspector(container, options = {}) {
    if (!container) { log.error('createElementInspector needs a container element'); throw new TypeError('createElementInspector: container is required'); }
    const state = { meta: null, element: null, markup: null, extra: [] };
    let markupBlock = null;
    let extraBodies = [];
    let destroyed = false;

    const currentMarkup = () => (state.element ? cleanMarkup(state.element.outerHTML) : state.markup ?? '');

    const empty = () => h('pk-empty-state', { heading: options.emptyHeading ?? 'Nothing selected', description: options.emptyText ?? EMPTY_TEXT });
    const fold = (heading, open, ...body) => h('pk-accordion-item', { heading, open }, ...body);
    const none = text => h('p', { class: 'muted' }, text);

    // Fills one extra section; a host's render that throws must not take the inspector down.
    function fill(section, body) {
        const box = h('div', {});
        try { section.render(box, { meta: state.meta, element: state.element }); body.replaceChildren(box); }
        catch (error) { log.error(`extra section "${section.title}" failed to render`, { tag: state.meta?.tag, error }); body.replaceChildren(none(`The "${section.title}" section could not be drawn.`)); }
    }

    function draw() {
        markupBlock = null; extraBodies = [];
        const d = describeElement(state.meta);
        if (!d) { container.replaceChildren(empty()); return; }
        const stack = h('pk-stack', { gap: 'sm' });
        stack.append(h('h2', {}, code(`<${d.tag}>`)), h('p', { class: 'muted' }, [d.title, d.group].filter(Boolean).join(' - ')), h('p', {}, d.summary));
        const acc = h('pk-accordion', {});
        markupBlock = h('pk-code-block', { label: 'Markup', wrap: true });
        acc.append(
            fold(state.element ? 'Live markup' : 'Markup', true, markupBlock),
            fold(`Properties (${d.props.length})`, true, d.props.length ? table('Properties', ['Name', 'Type', 'Default', 'Description'], d.props.map(p => [code(p.name), p.type, code(p.default), p.description])) : none('None.')),
            fold(`Slots (${d.slots.length})`, false, d.slots.length ? table('Slots', ['Name', 'Description'], d.slots.map(s => [code(s.name), s.description])) : none('None.')),
            fold(`Events (${d.events.length})`, false, d.events.length ? table('Events', ['Name', 'Detail', 'Description'], d.events.map(e => [code(e.name), code(e.detail), e.description])) : none('None beyond the native ones.')),
            fold(`Parts (${d.parts.length})`, false, d.parts.length ? table('Parts', ['Selector', 'Description'], d.parts.map(p => [code(p.selector), p.description])) : none('None.')),
            fold(`Custom properties (${d.cssProperties.length})`, false, d.cssProperties.length ? table('Custom properties', ['Name', 'Default', 'Description'], d.cssProperties.map(c => [code(c.name), code(c.default), c.description])) : none('None. Design tokens inherit into the element.')),
        );
        if (d.methods.length) acc.append(fold(`Methods (${d.methods.length})`, false, table('Methods', ['Name', 'Description'], d.methods.map(m => [code(m.name), m.description]))));
        for (const section of state.extra) {
            const body = h('div', {});
            extraBodies.push([section, body]);
            acc.append(fold(section.title, section.open === true, body));
        }
        container.replaceChildren(h('pk-stack', { gap: 'md' }, stack, acc));
        refresh();
    }

    function refresh() {
        if (destroyed) return;
        if (markupBlock) markupBlock.textContent = currentMarkup();
        for (const [section, body] of extraBodies) fill(section, body);
    }

    // Only sections that are { title, render } are kept; anything else is reported once and skipped.
    function sectionsFrom(list) {
        if (list === undefined || list === null) return [];
        if (!Array.isArray(list)) { log.warn('extraSections must be an array of { title, render }: ignored', { got: typeof list }); return []; }
        return list.filter(s => {
            const ok = s && typeof s.title === 'string' && s.title && typeof s.render === 'function';
            if (!ok) log.warn('an extra section needs a title and a render function: skipped', { section: s?.title });
            return ok;
        });
    }

    function show(next) {
        if (destroyed) return;
        if (next && !next.meta) log.warn('show() was given no meta: showing the empty state instead', { keys: Object.keys(next) });
        state.meta = next?.meta ?? null; state.element = next?.element ?? null; state.markup = next?.markup ?? null;
        state.extra = state.meta ? sectionsFrom(next.extraSections) : [];
        if (state.meta) log.debug('showing', { tag: state.meta.tag, extraSections: state.extra.length });
        draw();
    }

    function destroy() { destroyed = true; container.replaceChildren(); }

    show(options.meta ? options : null);
    return { show, refresh, destroy, get tag() { return state.meta?.tag ?? null; } };
}

// PkElement: the base class of every SDK custom element (Shadow DOM, declared props, slots, events, parts). Dependency-free.
//
//   class extends PkElement { static tag = 'pk-x'; static props = { size: { type: 'enum', values: ['md', 'lg'], default: 'md', reflect: true } };
//                              static template = '<div part="box"><slot></slot></div>'; static css = ':host{display:block}' }
//   define(cls)
//
// Props: type string | boolean | number | enum. Attributes are kebab-case; a property and its attribute stay in step when reflect is set.
// Rendering: the template is cloned once into the shadow root; {{prop}} in text or attribute values, data-if="prop" and data-if-not="prop"
// are bound and re-applied in one microtask after any change. Anything richer overrides render(). Styles are adopted constructable
// sheets (shared and cached), never a style element or attribute, so a strict style-src holds. Design tokens are custom properties and
// inherit into the shadow root from :root / [data-theme]. Ids do not cross shadow boundaries: relate light-DOM siblings with aria-* on
// the light DOM, and use the internals (aria()) for the host's own role and state.

const sheets = new Map();
export const sheetFor = css => { let s = sheets.get(css); if (!s) { s = new CSSStyleSheet(); s.replaceSync(css); sheets.set(css, s); } return s; };
export const RESET = ':host{display:inline-block}:host([hidden]){display:none}*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}';

import { kebab, camel, coerce, parseBindings, bindValue } from './element-core.js';
import { createLogger, isLogEnabled } from './log.js';
export { kebab, camel, coerce, parseBindings, bindValue };

// One logger per tag (scope = the tag name), so a warning says which element spoke.
const loggers = new Map();
const loggerFor = tag => loggers.get(tag) ?? loggers.set(tag, createLogger(tag)).get(tag);

export class PkElement extends HTMLElement {
    static props = {};
    static template = '';
    static css = '';
    static delegatesFocus = false;
    static get observedAttributes() { return Object.keys(this.props).map(kebab); }

    constructor() {
        super();
        const c = this.constructor;
        this.$ = {};
        this.internals = this.attachInternals?.();
        for (const [n, d] of Object.entries(c.props)) {
            this.$[n] = d.default;
            if (Object.hasOwn(this, n)) { const v = this[n]; delete this[n]; this.$[n] = this.coerceProp(n, d, v); }
        }
        const root = this.shadowRoot ?? this.attachShadow({ mode: 'open', delegatesFocus: c.delegatesFocus });
        root.adoptedStyleSheets = [sheetFor(RESET), sheetFor(c.css)];
        if (!Object.hasOwn(c, '$tpl')) { c.$tpl = document.createElement('template'); c.$tpl.innerHTML = c.template; }
        root.replaceChildren(c.$tpl.content.cloneNode(true));
        this.$b = [];
        const walk = document.createTreeWalker(root, 5);
        for (let n = walk.nextNode(); n; n = walk.nextNode()) {
            if (n.nodeType === 3) { if (n.nodeValue.includes('{{')) this.$b.push({ n, parts: parseBindings(n.nodeValue) }); continue; }
            for (const a of n.attributes) {
                if (a.value.includes('{{')) this.$b.push({ n, a: a.name, parts: parseBindings(a.value) });
                else if (a.name === 'data-if' || a.name === 'data-if-not') this.$b.push({ n, key: a.value, not: a.name === 'data-if-not' });
            }
        }
    }

    // The element's logger (scope: its tag), and a warning that is said once per element and key, so a loop or a re-render does not flood.
    get log() { return loggerFor(this.constructor.tag); }
    warnOnce(key, message, detail) {
        const seen = this.$warned ??= new Set();
        if (!seen.has(key)) { seen.add(key); this.log.warn(message, detail); }
    }
    // A lifecycle line at debug; the level check keeps it (and its formatting) free at the default level.
    debug(message, detail) { if (isLogEnabled('debug', this.constructor.tag)) this.log.debug(message, detail); }
    // coerce() for one prop: an unusable value falls back to the default and says so (once per prop).
    coerceProp(name, def, raw, fromAttr = false) {
        return coerce(def, raw, fromAttr, (problem, fallback) => this.warnOnce(`prop:${name}`, `${name}=${JSON.stringify(raw)} ${problem}: using ${JSON.stringify(fallback)}`, { prop: name, value: raw, fallback }));
    }

    connectedCallback() {
        this.debug('connected');
        this.update(); this.connected?.();
    }
    disconnectedCallback() { this.disconnected?.(); }

    attributeChangedCallback(attr, _old, val) {
        const name = camel(attr); const d = this.constructor.props[name];
        if (!d || this.$r === name) return;
        this.$[name] = this.coerceProp(name, d, val, true);
        this.debug(`${name} changed`, this.$[name]);
        this.changed?.(name, this.$[name]); this.requestUpdate();
    }

    requestUpdate() {
        if (this.$q) return;
        this.$q = true;
        queueMicrotask(() => { this.$q = false; this.update(); });
    }

    update() { this.render(); this.updated?.(); }

    render() {
        for (const b of this.$b) {
            if (b.parts) { const v = bindValue(b.parts, this.$, Boolean(b.a)); if (!b.a) b.n.nodeValue = v; else if (v === null) b.n.removeAttribute(b.a); else b.n.setAttribute(b.a, v); }
            else b.n.hidden = b.not ? Boolean(this.$[b.key]) : !this.$[b.key];
        }
    }

    // A bubbling, composed CustomEvent; false when a listener cancelled it.
    emit(name, detail, init = {}) { return this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true, cancelable: true, ...init })); }

    slotted(name = '') { return this.shadowRoot.querySelector(name ? `slot[name="${name}"]` : 'slot:not([name])')?.assignedElements({ flatten: true }) ?? []; }
    watchSlot(name, fn) { const s = this.shadowRoot.querySelector(name ? `slot[name="${name}"]` : 'slot:not([name])'), w = this.$ws ??= new Set(); if (s && !w.has(name)) { w.add(name); s.addEventListener('slotchange', fn); } return s; }
    part(name) { return this.shadowRoot.querySelector(`[part~="${name}"]`); }
    aria(map) { if (this.internals) Object.assign(this.internals, map); }

    // Form association (static formAssociated = true): value, validity and the reset / disabled / restore callbacks.
    get form() { return this.internals?.form ?? null; }
    get validity() { return this.internals?.validity; }
    get validationMessage() { return this.internals?.validationMessage ?? ''; }
    setFormValue(v, state) { this.internals?.setFormValue(v, state); }
    setValidity(flags, message, anchor) { this.internals?.setValidity(flags, message, anchor); }
    checkValidity() { return this.internals?.checkValidity() ?? true; }
    formResetCallback() { this.onReset?.(); }
    formDisabledCallback(disabled) { if ('disabled' in this.constructor.props) this.disabled = disabled; }
    formStateRestoreCallback(state) { this.onRestore?.(state); }
}

// Register a class: one accessor per declared prop (assignment reflects to the attribute when reflect is set).
export function define(cls) {
    for (const [name, def] of Object.entries(cls.props)) {
        if (Object.hasOwn(cls.prototype, name)) continue;
        Object.defineProperty(cls.prototype, name, {
            get() { return this.$[name]; },
            set(v) {
                const n = this.coerceProp(name, def, v);
                if (n === this.$[name]) return;
                this.$[name] = n;
                if (def.reflect) { this.$r = name; if (def.type === 'boolean') this.toggleAttribute(kebab(name), n); else this.setAttribute(kebab(name), String(n)); this.$r = null; }
                this.debug(`${name} changed`, n); this.changed?.(name, n); this.requestUpdate();
            },
        });
    }
    if (!customElements.get(cls.tag)) { customElements.define(cls.tag, cls); if (isLogEnabled('debug', cls.tag)) loggerFor(cls.tag).debug('defined'); }
    return cls;
}

// The pure logic behind the scorecard's framework sections (modules/scorecard): budget checks, the API-surface diff, the security and
// size-sweep summaries, metric and history rows. Data in, plain rows out: no DOM, no fetch, no fs, so it runs the same in a page and
// under Node. Framework-free; no imports.

// The colour word of a 0-100 score, the same bands the ranked table uses: 80 and up good, 55 and up warning.
export const band = s => (s === null || s === undefined ? '' : s >= 80 ? 'ok' : s >= 55 ? 'warn' : 'danger');

const SEVERITIES = ['critical', 'high', 'medium', 'low'];
const SEVERITY_VARIANT = { critical: 'danger', high: 'danger', medium: 'warn', low: 'muted' };
export const severityVariant = s => SEVERITY_VARIANT[s] ?? 'muted';

// KB with one decimal, or a dash when there is no number.
export const kb = n => (typeof n === 'number' && Number.isFinite(n) ? (Math.round(n * 10) / 10).toString() : '-');

// Comments and blank runs removed, the way the base-runtime budget counts a script (tests/budgets.test.mjs).
export const stripComments = t => t.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '').replace(/\n\s+/g, '\n').replace(/\n+/g, '\n');

// Is `value` (a URL string) on the same origin as `base`? Data files a module loads must be the host's own; a relative URL always is.
export function sameOrigin(value, base) {
    try { return new URL(value, base).origin === new URL(base).origin; } catch { return false; }
}

// ---- scored categories ----------------------------------------------------------------------------------------------------

// One category's metric table rows from scoreAll's output and the definitions: { metric, value, good, poor, score, tone }.
export function metricRows(scoring, key, category) {
    return category.metrics.map(m => {
        const def = scoring.categories[key].metrics[m.key];
        return { metric: m.label, value: m.value ?? 'n/a', good: def.good, poor: def.poor, score: m.score ?? 'n/a', tone: band(m.score) };
    });
}

// ---- size and budgets -----------------------------------------------------------------------------------------------------

// sizes: [{ name, budget, gzKb, rawKb }]; budgets: { key: { limit, target?, note? } } (scoring.data.js BUDGETS).
// Rows carry the headroom under the limit and a status: ok, over (past the limit) or none (no budget names this file). Worst first.
export function budgetRows(budgets, sizes) {
    const rows = sizes.map(s => {
        const b = budgets?.[s.budget];
        const limit = b?.limit ?? null;
        const headroom = limit === null || s.gzKb === null ? null : Math.round((limit - s.gzKb) * 100) / 100;
        return { name: s.name, budget: s.budget ?? '', rawKb: s.rawKb, gzKb: s.gzKb, target: b?.target ?? null, limit, headroom, status: limit === null || headroom === null ? 'none' : headroom >= 0 ? 'ok' : 'over' };
    });
    return rows.sort((a, b) => (a.headroom ?? Infinity) - (b.headroom ?? Infinity) || a.name.localeCompare(b.name));
}

export const budgetSummary = rows => ({ total: rows.length, over: rows.filter(r => r.status === 'over').length, unbudgeted: rows.filter(r => r.status === 'none').length });

// ---- API surface ----------------------------------------------------------------------------------------------------------

export const SURFACE_KINDS = ['classes', 'tokens', 'exports'];

// What the baseline holds that the current surface lost (a break) and what it gained. current may be missing: then only counts of the baseline.
export function apiDiff(baseline, current) {
    const counts = {}; const removed = []; const added = [];
    for (const k of SURFACE_KINDS) {
        const before = baseline?.[k] ?? [];
        const after = current?.[k] ?? null;
        const gone = after ? before.filter(x => !after.includes(x)) : [];
        const fresh = after ? after.filter(x => !before.includes(x)) : [];
        counts[k] = { baseline: before.length, current: after ? after.length : null, removed: gone.length, added: fresh.length };
        removed.push(...gone.map(name => ({ kind: k, name })));
        added.push(...fresh.map(name => ({ kind: k, name })));
    }
    return { available: Boolean(current), counts, removed, added };
}

// ---- security -------------------------------------------------------------------------------------------------------------

// The report tools/security.mjs writes: counts per severity (worst first) and the first `limit` findings with a "where" label.
export function securitySummary(report, { limit = 60 } = {}) {
    const findings = report?.findings ?? [];
    const counts = SEVERITIES.filter(k => k in (report?.counts ?? {})).map(k => ({ severity: k, count: report.counts[k] }));
    const rows = findings.slice(0, limit).map((f, i) => ({ id: i + 1, severity: f.severity, rule: f.rule, file: f.file, line: f.line, where: `${f.file}:${f.line}`, message: f.message }));
    return { counts, rows, total: findings.length, shown: rows.length, clean: findings.length === 0 };
}

// ---- size sweep -----------------------------------------------------------------------------------------------------------

// The last full size sweep (site/scorecard/sweep-report.json): the headline numbers, the failing cells and any re-measure notes.
export function sweepSummary(report, { limit = 40 } = {}) {
    const failures = report?.failures ?? [];
    const rows = failures.slice(0, limit).map((f, i) => ({ id: i + 1, item: f.item, width: f.width, theme: f.theme, overflow: f.overflow ?? 0, targets: f.smallTargets ?? 0, reading: f.readingSmall ?? 0, meta: f.metaTooSmall ?? 0, nested: f.nestedScrollers ?? 0 }));
    return {
        failing: failures.length, checked: report?.checked ?? 0, widths: report?.widths ?? [], themes: report?.themes ?? [], partial: Boolean(report?.partial),
        rows, total: failures.length, notes: (report?.remeasured ?? []).map(x => ({ item: x.item, note: x.note })),
    };
}

// ---- history --------------------------------------------------------------------------------------------------------------

// Category keys present in a history (the definitions' order when given, then any others the runs carry).
export function historyCategories(history, scoring) {
    const keys = Object.keys(scoring?.categories ?? {});
    for (const r of history) for (const k of Object.keys(r.categories ?? {})) if (!keys.includes(k)) keys.push(k);
    return keys;
}

// Newest first; each row has its change against the run before it. `when` formats the timestamp.
export function historyRows(history, keys, when = at => new Date(at).toLocaleString()) {
    return [...history].reverse().map((r, i, all) => {
        const before = all[i + 1];
        const row = { id: history.length - i, when: when(r.at), overall: r.overall ?? 'n/a', change: before && typeof r.overall === 'number' && typeof before.overall === 'number' ? r.overall - before.overall : null };
        for (const k of keys) row[k] = r.categories?.[k] ?? 'n/a';
        return row;
    });
}

// A signed change for display: "+3", "-2", "±0", "" when unknown.
export const signed = d => (d === null || d === undefined ? '' : d === 0 ? '±0' : `${d > 0 ? '+' : ''}${d}`);

// The gallery's embedding options and the pure logic around them: parsing them from a query string, writing them back, and cutting the
// content tree down to what an embedder asked for. No DOM, no fetch; the gallery module and the <pk-gallery> element share it.

// 'controls' is the old name of the elements section (the class-based controls are gone): still accepted, and it means elements.
export const KINDS = ['foundations', 'controls', 'elements', 'layouts', 'templates'];
export const THEMES = ['dark', 'light'];
export const WIDTHS = ['desktop', 'phone'];
export const CHROMES = ['full', 'none'];

// The page <pk-gallery> frames (the build points the dist copy of this module at dist/gallery/embed.html).
export const EMBED_URL = new URL('../site/gallery/embed.html', import.meta.url).href;

const slug = s => String(s).replace(/\W+/g, '-').replace(/^-|-$/g, '').toLowerCase();
const words = v => String(v ?? '').split(',').map(s => s.trim()).filter(Boolean);
const pick = (v, allowed) => (allowed.includes(v) ? v : undefined);

// Anything unknown is dropped rather than guessed at, so a typo shows the whole gallery instead of a blank one.
export function normalizeOptions(raw = {}) {
    const o = {};
    const kind = pick(String(raw.kind ?? '').toLowerCase(), KINDS); if (kind) o.kind = kind;
    const group = slug(raw.group ?? ''); if (group) o.group = group;
    const control = [...new Set((Array.isArray(raw.control) ? raw.control : words(raw.control)).map(s => String(s).trim().toLowerCase()).filter(Boolean))]; if (control.length) o.control = control;
    const theme = pick(raw.theme, THEMES); if (theme) o.theme = theme;
    const width = pick(raw.width, WIDTHS); if (width) o.width = width;
    const filter = String(raw.filter ?? '').trim(); if (filter) o.filter = filter;
    const chrome = pick(raw.chrome, CHROMES); if (chrome) o.chrome = chrome;
    const height = Number(raw.height); if (Number.isFinite(height) && height > 0) o.height = Math.round(height);
    return o;
}

export function parseQuery(search) {
    const q = new URLSearchParams(search);
    return normalizeOptions(Object.fromEntries(['kind', 'group', 'control', 'theme', 'width', 'filter', 'chrome', 'height'].map(k => [k, q.get(k)])));
}

export function toQuery(options) {
    const o = normalizeOptions(options);
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(o)) q.set(k, Array.isArray(v) ? v.join(',') : String(v));
    return q.toString();
}

// True when the options narrow the content (kind, group or control); theme, width, filter and chrome only change how it looks.
export const isScoped = o => Boolean(o.kind || o.group || o.control?.length);

// The tree is [{ id, title, items | groups: [{ id, title, items }] }], the shape the gallery builds. Kind picks a section (layouts and
// templates are groups of the samples section; no kind, or the old 'controls', means elements), group picks a group by id or title, control picks
// items by id (an element by tag, with or without the pk- prefix).
export function restrictTree(tree, options) {
    if (!isScoped(options)) return tree;
    const kind = !options.kind || options.kind === 'controls' ? 'elements' : options.kind;
    const wanted = options.control ?? [];
    const takes = it => { const id = String(it.id).toLowerCase(); return !wanted.length || wanted.includes(id) || wanted.includes(id.replace(/^pk-/, '')); };
    const inGroup = g => !options.group || options.group === g.id || options.group === slug(g.title);
    const real = it => it.id !== 'overview';
    const sectionId = kind === 'layouts' || kind === 'templates' ? 'samples' : kind;
    const out = [];
    for (const sec of tree) {
        if (sec.id !== sectionId) continue;
        if (sec.items) {
            const items = sec.items.filter(it => real(it) && takes(it));
            if (items.length) out.push({ ...sec, items });
            continue;
        }
        const groups = sec.groups
            .filter(g => (sectionId !== 'samples' || g.id === kind) && inGroup(g))
            .map(g => ({ ...g, items: g.items.filter(it => real(it) && takes(it)) }))
            .filter(g => g.items.length);
        if (groups.length) out.push({ ...sec, groups });
    }
    return out;
}

// The same match as filterLeaves, applied to the tree itself (a group whose title matches keeps all its items; empty groups and sections drop),
// so an overview page can list only what the filter leaves.
export function filterTree(tree, filter) {
    const f = String(filter ?? '').trim().toLowerCase();
    if (!f) return tree;
    const has = t => String(t).toLowerCase().includes(f);
    return tree
        .map(sec => (sec.items
            ? { ...sec, items: sec.items.filter(it => has(it.title)) }
            : { ...sec, groups: sec.groups.map(g => ({ ...g, items: has(g.title) ? g.items : g.items.filter(it => has(it.title)) })).filter(g => g.items.length) }))
        .filter(sec => (sec.items ?? sec.groups).length);
}

// Every leaf of a tree, with the group it sits in.
export function leaves(tree) {
    return tree.flatMap(sec => (sec.items ?? sec.groups.flatMap(g => g.items.map(it => ({ ...it, group: g })))).map(it => ({ ...it, section: sec })));
}

// Leaves whose title (or group title) contains the filter text, case-insensitively; no filter keeps everything.
export function filterLeaves(list, filter) {
    const f = String(filter ?? '').trim().toLowerCase();
    return f ? list.filter(it => it.title.toLowerCase().includes(f) || it.group?.title.toLowerCase().includes(f)) : list;
}

// Where the gallery opens: the one element, the one group, or the section the options name; empty when nothing narrows the view.
export function initialHash(tree) {
    if (!tree.length) return '';
    const all = leaves(tree);
    if (all.length === 1) return all[0].hash;
    const groups = new Set(all.map(l => l.group?.id));
    if (tree.length === 1 && groups.size === 1 && all[0].group) return all[0].group.hash;
    return tree.length === 1 ? `#/${tree[0].id}` : '';
}

// Pure logic behind the dev tools' Quality and Inspector panels: turning findings into a score and table rows, and describing an
// element for the inspector. No DOM beyond the small element interface (localName, attributes, getBoundingClientRect), so node tests cover it.

export const PENALTY = Object.freeze({ error: 25, warn: 8 });

// 0-100: 100 minus a penalty per distinct finding (the same check on the same selector counts once), floor 0.
export function pageScore(findings, penalty = PENALTY) {
    const seen = new Set();
    let total = 0;
    for (const f of findings) {
        const key = `${f.check}|${f.selector}`;
        if (seen.has(key)) continue;
        seen.add(key);
        total += penalty[f.severity] ?? 0;
    }
    return Math.max(0, 100 - total);
}

// 'positive' | 'warning' | 'critical' for pk-stat, from a score.
export const scoreTone = s => (s >= 80 ? 'positive' : s >= 55 ? 'warning' : 'critical');

// Findings as table rows, errors first then by check, each with the number of times it was found.
export function findingRows(findings) {
    const map = new Map();
    for (const f of findings) {
        const key = `${f.check}|${f.selector}`;
        const row = map.get(key) ?? { check: f.check, severity: f.severity, category: f.category, selector: f.selector, message: f.message, count: 0 };
        row.count++;
        map.set(key, row);
    }
    const rank = { error: 0, warn: 1 };
    return [...map.values()]
        .sort((a, b) => (rank[a.severity] ?? 2) - (rank[b.severity] ?? 2) || a.check.localeCompare(b.check) || a.selector.localeCompare(b.selector))
        .map((r, id) => ({ id, ...r }));
}

const SKIP_ATTRS = new Set(['class', 'style', 'slot', 'id']);

// What an inspector row shows for an element: its tag, domId (its own id attribute), the attributes that set it up (not class/style/slot) and its size.
export function describeForInspector(el) {
    const r = el.getBoundingClientRect();
    const props = [...el.attributes].filter(a => !SKIP_ATTRS.has(a.name)).map(a => (a.value === '' ? a.name : `${a.name}=${a.value}`)).join(' ');
    return { tag: el.localName, domId: el.id || '', props: props.length > 90 ? `${props.slice(0, 89)}…` : props, size: `${Math.round(r.width)} x ${Math.round(r.height)}`, visible: r.width > 0 && r.height > 0 };
}

// Declarative openers for the overlay elements, so a page needs no script to open a dialog:
//
//   <pk-button data-open="#confirm">Delete</pk-button>
//   <pk-dialog id="confirm" heading="Delete this item?"> ... <pk-button data-close>Cancel</pk-button> </pk-dialog>
//
// data-open="<selector>" calls show() on the first element the selector matches (pk-dialog, pk-drawer, pk-popover); data-toggle="<selector>"
// calls toggle() (pk-popover) and data-close hides the dialog, drawer or popover the control sits in. One delegated listener per root,
// installed by initPlainkit() and, on demand, the first time a pk-dialog, pk-drawer or pk-popover connects (so a page that only
// uses the elements gets the openers too); initInvokers is idempotent per root. The pure resolution is exported for tests.

import { createLogger } from './log.js';

const log = createLogger('invokers');
const OVERLAYS = 'pk-dialog, pk-drawer, pk-popover';

// What a click on `target` asks for: { type: 'open' | 'toggle' | 'close', element } or null. `root` resolves selectors (a Document or Element).
export function resolveInvoker(target, root) {
    const opener = target?.closest?.('[data-open]');
    if (opener) { const element = safeQuery(root, opener.getAttribute('data-open'), 'data-open'); return element ? { type: 'open', element } : null; }
    const toggler = target?.closest?.('[data-toggle]');
    if (toggler) { const element = safeQuery(root, toggler.getAttribute('data-toggle'), 'data-toggle'); return element ? { type: 'toggle', element } : null; }
    const closer = target?.closest?.('[data-close]');
    if (closer) {
        const element = closer.closest(OVERLAYS);
        if (!element) log.warn('data-close is not inside a pk-dialog, pk-drawer or pk-popover, so it closes nothing', { control: closer.localName });
        return element ? { type: 'close', element } : null;
    }
    return null;
}

// A selector from markup can be invalid or match nothing; that is a page mistake, so it is logged (warn) and the click does nothing.
function safeQuery(root, selector, attribute) {
    if (!selector) { log.warn(`${attribute} is empty: it needs a selector such as "#dialog-id"`); return null; }
    let element = null;
    try { element = root.querySelector(selector); } catch (error) { log.warn(`${attribute}="${selector}" is not a valid selector`, error); return null; }
    if (!element) log.warn(`${attribute}="${selector}" matched no element on the page`);
    return element;
}

export function runInvoker(action) {
    if (!action) return false;
    const { type, element } = action;
    if (type === 'open') element.show?.();
    else if (type === 'toggle') element.toggle?.();
    else element.hide?.();
    return true;
}

const installed = new WeakSet();

// Installs the delegated click listener once per root (idempotent, like the other initX functions).
export function initInvokers(root = document) {
    if (installed.has(root)) return;
    installed.add(root);
    root.addEventListener('click', event => { runInvoker(resolveInvoker(event.target, root)); });
}

// The on-demand element loader: finds pk-* tags that are not defined yet, imports only the modules they need (each cacheable on its own)
// and, with observe, does the same for elements added later. The registry maps a tag to its module, relative to the registry file:
//   elements/registry.js  { "pk-button": "./button/button.element.js", ... }   (generated by tools/build.mjs; dist/ has its own)

import { createLogger, isLogEnabled } from './log.js';

const log = createLogger('loader');
const loaded = new Map();
const reported = new Set();
const observed = new WeakSet();

// Which modules to import: the pk-* tags in `tags` that the registry knows and `have` does not hold yet. Pure.
export function planLoad(tags, registry, have = new Set()) {
    const out = [];
    for (const tag of new Set(tags)) if (tag.startsWith('pk-') && registry[tag] && !have.has(tag)) out.push({ tag, path: registry[tag] });
    return out;
}

const tagsIn = root => [...(root.matches?.(':not(:defined)') ? [root] : []), ...root.querySelectorAll(':not(:defined)')].map(e => e.localName).filter(t => t.startsWith('pk-'));

async function registryOf(url) { return (await import(url)).default; }

export async function loadElements(root = document, { registry = new URL('../elements/registry.js', import.meta.url).href } = {}) {
    const tags = (() => { try { return tagsIn(root); } catch (error) { log.debug('could not scan for pk-* tags', error); return []; } })();
    if (!tags.length) return [];
    let reg;
    try { reg = await registryOf(registry); } catch (error) { log.error(`could not load the element registry from ${registry}`, error); return []; }
    // A pk-* tag the registry does not know is usually a typo: say so once instead of leaving an inert element on the page.
    for (const tag of new Set(tags)) if (tag.startsWith('pk-') && !reg[tag] && !reported.has(tag)) { reported.add(tag); log.warn(`<${tag}> is not a Plainkit element (no such tag in the registry): check the spelling`, { tag }); }
    const plan = planLoad(tags, reg, new Set(loaded.keys()));
    await Promise.all(plan.map(({ tag, path }) => {
        const started = globalThis.performance?.now?.() ?? Date.now();
        const p = import(new URL(path, registry).href);
        loaded.set(tag, p);
        // Both outcomes are logged here, so the promise handed back never rejects.
        return p.then(() => { if (isLogEnabled('debug', 'loader')) log.debug(`loaded <${tag}> in ${Math.round((globalThis.performance?.now?.() ?? Date.now()) - started)} ms`, { tag, path }); }, error => { loaded.delete(tag); log.error(`could not load <${tag}> from ${path}`, error); });
    }));
    return plan.map(p => p.tag);
}

export function observeElements(root = document, options) {
    if (typeof MutationObserver === 'undefined' || observed.has(root)) return null;
    observed.add(root);
    const seen = new WeakSet();
    const mo = new MutationObserver(records => {
        for (const r of records) for (const n of r.addedNodes) if (n.nodeType === 1 && !seen.has(n)) { seen.add(n); loadElements(n, options); }
    });
    mo.observe(root.documentElement ?? root, { childList: true, subtree: true });
    return mo;
}

// The built-in log outputs that show something on the page: toast (a pk-toast) and alert (a pk-alert notice at the top of the page).
// They register themselves with js/log.js when this module is imported, and log.js imports it the first time a route names one of them:
//
//   configureLogging({ routes: { error: ['console', 'toast'], warn: ['console', 'alert'] } });
//
// Both are built only from SDK elements (pk-toast-stack, pk-alert), loaded through the SDK's loader. Repeated messages are folded into
// one (a count in the heading) so a failing loop does not flood the page. Pure helpers are exported for tests.

import { registerLogOutput } from './log.js';

// pk-toast and pk-alert both take kind: info, success, warning, danger.
export const KIND = Object.freeze({ debug: 'info', info: 'info', warn: 'warning', error: 'danger' });
export const kindFor = level => KIND[level] ?? 'info';

// Folds an entry into a list of shown notices: an entry with the same level, scope and message as one already shown bumps its count
// instead of adding another. Returns { list, entry, isNew } without mutating the input. Pure.
export function foldEntry(list, entry, max = 5) {
    const key = `${entry.level}|${entry.scope}|${entry.message}`;
    const i = list.findIndex(x => x.key === key);
    if (i >= 0) { const next = list.slice(); next[i] = { ...next[i], count: next[i].count + 1 }; return { list: next, entry: next[i], isNew: false }; }
    const item = { key, level: entry.level, scope: entry.scope, message: entry.message, count: 1 };
    return { list: [...list, item].slice(-max), entry: item, isNew: true };
}

export const headingFor = item => `${item.scope}${item.count > 1 ? ` (x${item.count})` : ''}`;

// ---- toast -------------------------------------------------------------------------------------------------------------------
let toastReady = null;
async function ensureToast() {
    if (globalThis.PkToast) return globalThis.PkToast;
    toastReady ??= (async () => {
        const registry = new URL('../elements/registry.js', import.meta.url).href;
        const map = (await import(registry)).default;
        const mod = await import(new URL(map['pk-toast-stack'], registry).href);
        // The stack only publishes PkToast when an instance connects, and a log toast may be the first: take the class from the module.
        globalThis.PkToast ??= mod.default;
        return globalThis.PkToast;
    })();
    return toastReady;
}
let shownToasts = [];
const toastOutput = async entry => {
    const folded = foldEntry(shownToasts, entry, 20);
    shownToasts = folded.list;
    if (!folded.isNew) return; // the same message is already on screen: it counts, it does not stack
    const PkToast = await ensureToast();
    PkToast?.show(entry.message, { kind: kindFor(entry.level), heading: entry.scope, duration: entry.level === 'error' ? 0 : 6000 });
    setTimeout(() => { shownToasts = shownToasts.filter(x => x.key !== folded.entry.key); }, 6000);
};

// ---- alert -------------------------------------------------------------------------------------------------------------------
let alertList = [];
let alertRegion = null;
const alertNodes = new Map();

async function ensureAlerts() {
    const doc = globalThis.document;
    if (!doc?.body) return null;
    if (!alertRegion?.isConnected) {
        alertRegion = doc.createElement('div');
        alertRegion.setAttribute('role', 'region');
        alertRegion.setAttribute('aria-label', 'Notices');
        alertRegion.setAttribute('data-pk-log-alerts', '');
        doc.body.prepend(alertRegion);
        alertNodes.clear();
        const { loadElements } = await import('./loader.js');
        loadElements(alertRegion);
    }
    return alertRegion;
}

const alertOutput = async entry => {
    const region = await ensureAlerts();
    if (!region) return;
    const folded = foldEntry(alertList, entry, 5);
    alertList = folded.list;
    const item = folded.entry;
    let node = alertNodes.get(item.key);
    if (!node) {
        node = globalThis.document.createElement('pk-alert');
        node.setAttribute('dismissible', '');
        node.setAttribute('compact', '');
        node.setAttribute('kind', kindFor(item.level));
        node.textContent = item.message;
        node.addEventListener('pk-dismiss', () => { alertNodes.delete(item.key); alertList = alertList.filter(x => x.key !== item.key); });
        region.append(node);
        alertNodes.set(item.key, node);
    }
    node.setAttribute('heading', headingFor(item));
    // Keep at most five notices on the page: drop the oldest nodes that folded out of the list.
    for (const [key, n] of alertNodes) if (!alertList.some(x => x.key === key)) { n.remove(); alertNodes.delete(key); }
};

registerLogOutput('toast', toastOutput);
registerLogOutput('alert', alertOutput);

// Pure logic behind the logging settings (modules/log-settings): turning the logging configuration into an editable draft (a global
// level, a level per scope, an output grid per level) and back into a configuration that js/log.js accepts, checking a scope name,
// and telling whether the URL or the page attribute is setting the level. No browser API is required, so node tests cover it.

import { LEVELS, DEFAULT_ROUTES, normalizeConfig } from './log.js';

export const EMITTING_LEVELS = Object.freeze(['debug', 'info', 'warn', 'error']);
export const BUILT_IN_OUTPUTS = Object.freeze(['console', 'toast', 'alert']);
// A scope row that sets no level of its own: it follows the global level.
export const INHERIT = 'inherit';

// The outputs a route can name: the built-in ones, then registered ones (getLogOutputs() also lists console) and any a saved route
// already names, each once.
export const outputsFor = (registered = [], routes = {}) => [...new Set([...BUILT_IN_OUTPUTS, ...registered, ...Object.values(routes).flat()])];

// The editable form of a configuration: { level, scopes: { scope: level | 'inherit' }, routes: { level: [output] } }. `seen` are scopes
// that have logged (they get a row even with no level of their own).
export function draftFrom(config, seen = []) {
    const scopes = {};
    for (const s of seen) scopes[s] = INHERIT;
    for (const [s, l] of Object.entries(config?.scopes ?? {})) scopes[s] = l;
    const routes = {};
    for (const l of EMITTING_LEVELS) routes[l] = [...(config?.routes?.[l] ?? DEFAULT_ROUTES[l])];
    return { level: LEVELS.includes(config?.level) ? config.level : 'warn', scopes, routes };
}

// The configuration a draft stands for, validated by normalizeConfig: 'inherit' rows are dropped, so only real overrides are saved.
export function configFrom(draft) {
    const scopes = {};
    for (const [s, l] of Object.entries(draft?.scopes ?? {})) if (l !== INHERIT) scopes[s] = l;
    return normalizeConfig({ level: draft?.level, scopes, routes: draft?.routes });
}

// Rows for the scope table, sorted, each { id, scope, level } (level 'inherit' when it follows the global level).
export const scopeRows = draft => Object.keys(draft.scopes).sort((a, b) => a.localeCompare(b)).map(scope => ({ id: scope, scope, level: draft.scopes[scope] }));

// Adds a scope by name. Returns { draft, error?, scope? }; the name is trimmed and checked the way js/log.js checks it.
export function addScope(draft, name) {
    const scope = String(name ?? '').trim();
    if (!scope) return { draft, error: 'Type a scope name, such as checkout.' };
    if (!normalizeConfig({ scopes: { [scope]: 'warn' } }).scopes?.[scope]) return { draft, error: 'A scope name is letters, digits, and : . _ - only (up to 60).' };
    if (scope in draft.scopes) return { draft, error: `${scope} is already listed.`, scope };
    return { draft: { ...draft, scopes: { ...draft.scopes, [scope]: INHERIT } }, scope };
}

export function removeScope(draft, scope) {
    const scopes = { ...draft.scopes };
    delete scopes[scope];
    return { ...draft, scopes };
}

export const setScopeLevel = (draft, scope, level) => (scope in draft.scopes && (level === INHERIT || LEVELS.includes(level)) ? { ...draft, scopes: { ...draft.scopes, [scope]: level } } : draft);
export const setGlobalLevel = (draft, level) => (LEVELS.includes(level) ? { ...draft, level } : draft);

// Sends `level` to `output` (on) or stops sending it there (off).
export function setRoute(draft, level, output, on) {
    if (!EMITTING_LEVELS.includes(level)) return draft;
    const now = draft.routes[level] ?? [];
    const next = on ? (now.includes(output) ? now : [...now, output]) : now.filter(o => o !== output);
    return { ...draft, routes: { ...draft.routes, [level]: next } };
}

// Rows for the routing grid: { id: level, level, <output>: boolean }.
export const routeRows = (draft, outputs) => EMITTING_LEVELS.map(level => ({ id: level, level, ...Object.fromEntries(outputs.map(o => [o, (draft.routes[level] ?? []).includes(o)])) }));

// Do two drafts stand for the same configuration?
export const sameDraft = (a, b) => JSON.stringify(configFrom(a)) === JSON.stringify(configFrom(b));

// Is something other than the saved settings choosing the level? ?pk-log= in the URL wins over <html data-pk-log>, which wins over the
// saved settings (js/log.js levelFrom). Returns { source: 'url' | 'attribute', level } or null.
export function levelOverride({ search = '', attr = null } = {}) {
    let fromUrl = null;
    try { fromUrl = new URLSearchParams(search).get('pk-log'); } catch { /* not a query string */ }
    const valid = v => (v && LEVELS.includes(String(v).toLowerCase()) ? String(v).toLowerCase() : null);
    if (valid(fromUrl)) return { source: 'url', level: valid(fromUrl) };
    if (valid(attr)) return { source: 'attribute', level: valid(attr) };
    return null;
}

export const describeOverride = o => (o ? (o.source === 'url' ? `?pk-log=${o.level} in the address` : `data-pk-log="${o.level}" on the page`) : '');

// The entries "Send a test" logs, one per level, under one scope.
export const TEST_SCOPE = 'settings-test';
export const testMessages = () => EMITTING_LEVELS.map(level => [level, `Test message at the ${level} level, from the logging settings`]);

// Pure logic behind the logs viewer (modules/logs): filtering the entries of js/log.js by level, scope and text, the list of scopes seen,
// counts per level, a row for the table, a readable form of an entry's detail (objects as JSON, errors with their stack), and the JSON
// export/import format. No browser API is required, so node tests cover it.

export const VIEW_LEVELS = Object.freeze(['debug', 'info', 'warn', 'error']);
const RANK = Object.fromEntries([...VIEW_LEVELS, 'silent'].map((l, i) => [l, i]));
export const MAX_IMPORT = 2000;
export const EXPORT_FORMAT = 'plainkit-log';

const pad = (n, w = 2) => String(n).padStart(w, '0');

// 14:03:09.042 in the viewer's time zone.
export function formatTime(at) {
    const d = new Date(at);
    if (Number.isNaN(d.getTime())) return '';
    return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}.${pad(d.getMilliseconds(), 3)}`;
}

// Entries at or above `minLevel`, in one of `scopes` (any scope when the list is empty), whose scope or message contains `text`
// (case-insensitive). Returns a new array in the same order.
export function filterLogEntries(entries, { minLevel = 'debug', scopes = [], text = '' } = {}) {
    const floor = RANK[minLevel] ?? 0;
    const wanted = new Set(scopes);
    const needle = String(text ?? '').trim().toLowerCase();
    return entries.filter(e => (RANK[e.level] ?? 0) >= floor
        && (!wanted.size || wanted.has(e.scope))
        && (!needle || e.message.toLowerCase().includes(needle) || e.scope.toLowerCase().includes(needle)));
}

// The distinct scopes of the entries (plus any extra ones), sorted.
export const scopesOf = (entries, extra = []) => [...new Set([...entries.map(e => e.scope), ...extra])].sort((a, b) => a.localeCompare(b));

// { debug, info, warn, error } counts.
export function countLevels(entries) {
    const counts = { debug: 0, info: 0, warn: 0, error: 0 };
    for (const e of entries) if (e.level in counts) counts[e.level]++;
    return counts;
}

// Where an entry went: the level it needed to reach an output (the scope's level, else the global one) and the outputs its level is
// routed to. `config` is getLoggingConfig(). An entry below the level was only buffered: seen here, in no output.
export function routeOf(entry, config) {
    const needed = config?.scopes?.[entry.scope] ?? config?.level ?? 'warn';
    const outputs = config?.routes?.[entry.level] ?? [];
    const below = (RANK[entry.level] ?? 0) < (RANK[needed] ?? 0);
    return { below, needed, outputs: below ? [] : outputs };
}

// Words for the Output column: 'buffered only' for a muted entry, else the outputs it was sent to.
export function outputLabel(entry, config) {
    const r = routeOf(entry, config);
    if (r.below) return 'buffered only';
    return r.outputs.length ? r.outputs.join(', ') : 'no output';
}

const isNode = v => typeof Node !== 'undefined' && v instanceof Node;

// A JSON-safe copy of any value: errors become { name, message, stack, cause }, cycles and depth are cut, functions and elements are named.
export function toPlain(value, depth = 6, seen = new WeakSet()) {
    if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return value;
    if (value === undefined) return null;
    if (typeof value === 'bigint') return String(value);
    if (typeof value === 'symbol') return value.toString();
    if (typeof value === 'function') return `[function ${value.name || 'anonymous'}]`;
    if (isNode(value)) return `[${value.nodeType === 1 ? `<${value.localName}${value.id ? `#${value.id}` : ''}>` : value.nodeName}]`;
    if (seen.has(value)) return '[circular]';
    if (depth < 0) return Array.isArray(value) ? `[Array(${value.length})]` : '[object]';
    seen.add(value);
    try {
        if (value instanceof Error) {
            const out = { name: value.name, message: value.message, stack: value.stack };
            if (value.cause !== undefined) out.cause = toPlain(value.cause, depth - 1, seen);
            return out;
        }
        if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value.toISOString();
        if (Array.isArray(value)) return value.slice(0, 200).map(v => toPlain(v, depth - 1, seen));
        const out = {};
        for (const k of Object.keys(value).slice(0, 100)) out[k] = toPlain(value[k], depth - 1, seen);
        return out;
    } catch { return '[unreadable]'; }
    finally { seen.delete(value); }
}

// How to show an entry's detail: { kind: 'none' | 'error' | 'text' | 'json', text }. An Error is its stack; a string is itself; anything
// else is pretty JSON (capped, so a huge object does not freeze the page).
export function describeDetail(detail, limit = 20000) {
    if (detail === undefined) return { kind: 'none', text: '' };
    if (detail instanceof Error) return { kind: 'error', text: detail.stack || `${detail.name}: ${detail.message}` };
    if (typeof detail === 'string') return { kind: 'text', text: detail };
    let text;
    try { text = JSON.stringify(toPlain(detail), null, 2) ?? String(detail); } catch { text = String(detail); }
    return { kind: 'json', text: text.length > limit ? `${text.slice(0, limit)}\n... ${text.length - limit} more characters` : text };
}

// One table row: { id, time, level, scope, message, output }. The message keeps to one line (the full text is in the detail).
export function rowFor(entry, config) {
    return {
        id: entry.id, time: formatTime(entry.at), level: entry.level, scope: entry.scope,
        message: entry.message.replace(/\s+/g, ' ').slice(0, 300), output: outputLabel(entry, config),
    };
}

// Appends an entry, keeping the newest `max`. Returns a new array.
export const pushLog = (entries, entry, max = 1000) => [...entries, entry].slice(-max);

// Text of the export file: { format, version, exported, entries: [{ at (ISO), level, scope, message, detail? }] }.
export function serializeEntries(entries, now = Date.now()) {
    return JSON.stringify({
        format: EXPORT_FORMAT, version: 1, exported: new Date(now).toISOString(),
        entries: entries.map(e => ({ at: new Date(e.at).toISOString(), level: e.level, scope: e.scope, message: e.message, ...(e.detail === undefined ? {} : { detail: toPlain(e.detail) }) })),
    }, null, 2);
}

// Reads an export file (or a bare array of entries). Entries that are not valid are skipped and counted; nothing throws.
// Returns { entries: [{ at, level, scope, message, detail? }], skipped, error? }.
export function parseImport(text) {
    let data;
    try { data = JSON.parse(text); } catch { return { entries: [], skipped: 0, error: 'That is not a JSON file.' }; }
    const list = Array.isArray(data) ? data : data?.entries;
    if (!Array.isArray(list)) return { entries: [], skipped: 0, error: 'No entries found in that file.' };
    const entries = [];
    let skipped = 0;
    for (const raw of list.slice(0, MAX_IMPORT)) {
        const at = typeof raw?.at === 'number' ? raw.at : Date.parse(raw?.at);
        const ok = raw && typeof raw === 'object' && VIEW_LEVELS.includes(raw.level) && typeof raw.scope === 'string' && raw.scope && raw.scope.length <= 60
            && typeof raw.message === 'string' && Number.isFinite(at);
        if (!ok) { skipped++; continue; }
        entries.push({ at, level: raw.level, scope: raw.scope, message: raw.message.slice(0, 5000), ...(raw.detail === undefined ? {} : { detail: raw.detail }) });
    }
    skipped += Math.max(0, list.length - MAX_IMPORT);
    return { entries, skipped, ...(entries.length ? {} : { error: 'No valid entries in that file.' }) };
}

// Merges imported entries into the list by time, keeping the newest `max`. Every entry gets an id from `nextId` upward.
export function mergeEntries(entries, incoming, nextId, max = 1000) {
    const added = incoming.map((e, i) => ({ ...e, id: nextId + i, imported: true }));
    return { entries: [...entries, ...added].sort((a, b) => a.at - b.at || a.id - b.id).slice(-max), nextId: nextId + added.length };
}

// SDK logging: one small logger every part of the SDK uses, so a page mistake or a failure is never silent, and the same logger is there
// for an app's own messages (createLogger('checkout')).
//
//   import { createLogger } from './log.js';
//   const log = createLogger('invokers');
//   log.warn('data-open="#nope" matched no element', { control });
//
// Levels, lowest first: debug, info, warn, error, silent. An entry is emitted when its level is at or above the level for its scope
// (a per-scope level wins over the global one). Emitted entries go to the OUTPUTS the routing names for that level:
//   console   the browser console (built in)
//   toast     a pk-toast (loaded on first use)          alert   a pk-alert notice at the top of the page (loaded on first use)
//   your own  registerLogOutput('telemetry', entry => ...)
// The default routing sends every level to the console only and the default level is 'warn', so a production page stays quiet.
// Configure in code:
//   configureLogging({ level: 'info', scopes: { loader: 'debug' }, routes: { error: ['console', 'toast'], warn: ['console'] } });
// or without touching code, in this order of precedence: ?pk-log=debug in the URL, <html data-pk-log="debug">, the saved settings
// (configureLogging(..., { persist: true }), which the Settings page and the dev tools write) and localStorage['pk-log'].
// Whatever the level, the last few hundred entries are kept in a ring buffer (getLogBuffer()) and every entry goes to the sinks
// (addLogSink(fn)), which is how the logs viewer and PlainKit.Blazor's ILogger bridge see everything. Framework-free; never throws.
// From the browser console: PkLog.setLogLevel('debug').

export const LEVELS = Object.freeze(['debug', 'info', 'warn', 'error', 'silent']);
const RANK = Object.fromEntries(LEVELS.map((l, i) => [l, i]));
export const DEFAULT_LEVEL = 'warn';
export const BUFFER_SIZE = 300;
export const CONFIG_KEY = 'pk-log-config';
const EMITTING = ['debug', 'info', 'warn', 'error'];
export const DEFAULT_ROUTES = Object.freeze({ debug: ['console'], info: ['console'], warn: ['console'], error: ['console'] });
// Outputs that live in js/log-outputs.js and are imported the first time a route names them.
const LAZY_OUTPUTS = new Set(['toast', 'alert']);

// The level a page asks for, from its sources in precedence order (each may be missing or invalid). Pure.
export function levelFrom({ search = '', attr = null, stored = null } = {}) {
    let fromUrl = null;
    try { fromUrl = new URLSearchParams(search).get('pk-log'); } catch { /* not a query string */ }
    for (const candidate of [fromUrl, attr, stored]) if (candidate && LEVELS.includes(String(candidate).toLowerCase())) return String(candidate).toLowerCase();
    return DEFAULT_LEVEL;
}

const isLevel = v => typeof v === 'string' && LEVELS.includes(v);
const isName = v => typeof v === 'string' && /^[\w-]{1,40}$/.test(v);
const isScope = v => typeof v === 'string' && /^[\w:.-]{1,60}$/.test(v);

// Validates a settings object (from storage, an import or a form): only known levels, output names and scope names survive. Pure.
export function normalizeConfig(input) {
    const out = {};
    if (!input || typeof input !== 'object') return out;
    if (isLevel(input.level)) out.level = input.level;
    if (input.scopes && typeof input.scopes === 'object') {
        out.scopes = {};
        for (const [scope, level] of Object.entries(input.scopes)) if (isScope(scope) && isLevel(level) && scope !== '__proto__') out.scopes[scope] = level;
    }
    if (input.routes && typeof input.routes === 'object') {
        out.routes = {};
        for (const level of EMITTING) if (Array.isArray(input.routes[level])) out.routes[level] = [...new Set(input.routes[level].filter(isName))];
    }
    return out;
}

// Parses saved settings text (JSON); anything unreadable is "no settings". Pure.
export function parseConfig(text) {
    try { return normalizeConfig(JSON.parse(text)); } catch { return {}; }
}

function readSources() {
    const g = globalThis;
    let stored = null, saved = {};
    try { stored = g.localStorage?.getItem('pk-log') ?? null; } catch { /* storage blocked */ }
    try { saved = parseConfig(g.localStorage?.getItem(CONFIG_KEY) ?? ''); } catch { /* storage blocked */ }
    const level = levelFrom({ search: g.location?.search ?? '', attr: g.document?.documentElement?.getAttribute?.('data-pk-log') ?? null, stored: saved.level ?? stored });
    return { level, scopes: saved.scopes ?? {}, routes: { ...DEFAULT_ROUTES, ...(saved.routes ?? {}) } };
}

let config = readSources();
let buffer = [];
const sinks = new Set();
const outputs = new Map();
const pending = new Map(); // lazy output name -> entries waiting for its module

export const getLogLevel = () => config.level;
export function setLogLevel(level) {
    if (!isLevel(level)) return false;
    config = { ...config, level };
    return true;
}

// A copy of the current settings: { level, scopes: { scope: level }, routes: { level: [output names] } }.
export const getLoggingConfig = () => ({ level: config.level, scopes: { ...config.scopes }, routes: Object.fromEntries(Object.entries(config.routes).map(([k, v]) => [k, [...v]])) });

// Merges settings (invalid parts are ignored). With { persist: true } the result is saved in localStorage so it survives a reload.
// { replace: true } replaces scopes and routes instead of merging them. Returns the resulting settings.
export function configureLogging(partial, { persist = false, replace = false } = {}) {
    const n = normalizeConfig(partial);
    config = {
        level: n.level ?? config.level,
        scopes: n.scopes ? (replace ? n.scopes : { ...config.scopes, ...n.scopes }) : config.scopes,
        routes: n.routes ? { ...(replace ? DEFAULT_ROUTES : config.routes), ...n.routes } : config.routes,
    };
    if (persist) {
        try { globalThis.localStorage?.setItem(CONFIG_KEY, JSON.stringify({ level: config.level, scopes: config.scopes, routes: config.routes })); } catch { /* storage blocked */ }
    }
    for (const route of Object.values(config.routes)) for (const name of route) requireOutput(name);
    return getLoggingConfig();
}

// Forgets the saved settings and goes back to the defaults (the URL and page attribute still win for the level).
export function resetLogging() {
    try { globalThis.localStorage?.removeItem(CONFIG_KEY); } catch { /* storage blocked */ }
    config = { level: levelFrom({ search: globalThis.location?.search ?? '', attr: globalThis.document?.documentElement?.getAttribute?.('data-pk-log') ?? null }), scopes: {}, routes: { ...DEFAULT_ROUTES } };
    return getLoggingConfig();
}

export const getLogBuffer = () => buffer.slice();
export const clearLogBuffer = () => { buffer = []; };

// Receives every entry (regardless of the level): { at, level, scope, message, detail }. Returns a function that removes it.
export function addLogSink(fn) {
    sinks.add(fn);
    return () => sinks.delete(fn);
}

// Registers a named output that routes can name: fn(entry) is called for each emitted entry routed to it. Entries that were waiting for
// this output (a route named it before it existed) are delivered now. Returns a function that removes it.
export function registerLogOutput(name, fn) {
    if (!isName(name) || typeof fn !== 'function') return () => {};
    outputs.set(name, fn);
    for (const entry of pending.get(name) ?? []) deliver(name, fn, entry);
    pending.delete(name);
    return () => { if (outputs.get(name) === fn) outputs.delete(name); };
}

export const getLogOutputs = () => [...outputs.keys()];

function deliver(name, fn, entry) {
    try { fn(entry); } catch { /* a broken output must not break the SDK */ }
}

// Built-in outputs that live in another file are imported when a route first names them.
function requireOutput(name) {
    if (outputs.has(name) || !LAZY_OUTPUTS.has(name) || pending.has(name)) return;
    pending.set(name, []);
    import('./log-outputs.js').catch(() => { pending.delete(name); });
}

const consoleOutput = entry => {
    const c = globalThis.console?.[entry.level];
    if (!c) return;
    const text = `[pk:${entry.scope}] ${entry.message}`;
    if (entry.detail === undefined) c.call(globalThis.console, text); else c.call(globalThis.console, text, entry.detail);
};
outputs.set('console', consoleOutput);

const levelFor = scope => RANK[config.scopes[scope] ?? config.level];

// Whether an entry at this level for this scope would be emitted (not merely buffered): guards debug lines whose message is costly to build.
export const isLogEnabled = (level, scope) => RANK[level] >= levelFor(scope);

// Records an entry, hands it to the sinks and, when its level is at or above the one for its scope, sends it to its routed outputs.
export function log(level, scope, message, detail) {
    if (!EMITTING.includes(level)) return null;
    const entry = { at: Date.now(), level, scope, message: String(message), ...(detail === undefined ? {} : { detail }) };
    buffer.push(entry);
    if (buffer.length > BUFFER_SIZE) buffer.shift();
    for (const sink of sinks) deliver('sink', sink, entry);
    if (RANK[level] >= levelFor(scope)) {
        for (const name of config.routes[level] ?? []) {
            const fn = outputs.get(name);
            if (fn) { deliver(name, fn, entry); continue; }
            requireOutput(name); // a built-in output that is not loaded yet: queue the entry until it registers
            pending.get(name)?.push(entry);
        }
    }
    return entry;
}

// A logger bound to a scope (the part of the SDK, or the app, that is speaking: 'loader', 'invokers', 'pk-dialog', 'checkout'...).
export function createLogger(scope) {
    return {
        scope,
        debug: (message, detail) => log('debug', scope, message, detail),
        info: (message, detail) => log('info', scope, message, detail),
        warn: (message, detail) => log('warn', scope, message, detail),
        error: (message, detail) => log('error', scope, message, detail),
    };
}

// A handle for the browser console, so a developer can turn the logs up on a live page: PkLog.setLogLevel('debug').
try {
    globalThis.PkLog ??= { createLogger, setLogLevel, getLogLevel, configureLogging, getLoggingConfig, resetLogging, getLogBuffer, clearLogBuffer, addLogSink, registerLogOutput, getLogOutputs };
} catch { /* a frozen global */ }

// Plainkit menu logic: the keyboard decisions shared by <pk-dropdown>, <pk-context-menu> and <pk-select>. Pure, so they can be
// tested without a DOM. Items are the enabled rows in order; `current` is the focused index (-1 when none).
//
// Keys: ArrowDown/Up (wrap), Home/End, typeahead (a letter jumps to the next label starting with it; typing more narrows), ArrowRight
// opens a submenu and ArrowLeft closes it, Escape closes and returns focus to the trigger, Tab closes, Enter/Space choose.

export const TYPEAHEAD_RESET = 600;

// Whether an element can take part in keyboard navigation.
export const isEnabled = el => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true' && !el.hidden;

// Next index for a movement key over `count` enabled items, or null for any other key.
export function nextIndex(current, count, key) {
    if (count <= 0) return null;
    switch (key) {
        case 'ArrowDown': return current < 0 ? 0 : (current + 1) % count;
        case 'ArrowUp': return current < 0 ? count - 1 : (current - 1 + count) % count;
        case 'Home': return 0;
        case 'End': return count - 1;
        default: return null;
    }
}

// Index of the label a typed buffer selects, or -1. A repeated single letter cycles through matches; a longer buffer matches a prefix,
// starting at the current item so the selection does not jump while you keep typing.
export function typeaheadIndex(labels, current, buffer) {
    const b = buffer.toLowerCase();
    if (!b || labels.length === 0) return -1;
    const repeated = [...b].every(c => c === b[0]);
    const needle = repeated ? b[0] : b;
    const start = repeated ? current + 1 : Math.max(current, 0);
    for (let i = 0; i < labels.length; i++) {
        const at = (((start + i) % labels.length) + labels.length) % labels.length;
        if (labels[at].trim().toLowerCase().startsWith(needle)) return at;
    }
    return -1;
}

// The typeahead buffer after a key: it restarts once TYPEAHEAD_RESET ms have passed since the last one.
export const typeaheadBuffer = (buffer, key, sinceLastMs) => (sinceLastMs > TYPEAHEAD_RESET ? key : buffer + key);

// The state an item takes when chosen: a checkbox flips, a radio becomes checked, others are unchanged.
export function checkedAfter(role, checked) {
    if (role === 'menuitemcheckbox') return !checked;
    if (role === 'menuitemradio') return true;
    return checked;
}

// What a key does inside a menu: 'move', 'open-sub', 'close-sub', 'close' (Escape, refocus the trigger), 'tab-close', 'choose', 'type', or null.
export function keyAction(key, { hasSubmenu = false, inSubmenu = false, modified = false } = {}) {
    if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(key)) return 'move';
    if (key === 'ArrowRight' && hasSubmenu) return 'open-sub';
    if (key === 'ArrowLeft' && inSubmenu) return 'close-sub';
    if (key === 'Escape') return inSubmenu ? 'close-sub' : 'close';
    if (key === 'Tab') return 'tab-close';
    if (key === 'Enter' || key === ' ') return 'choose';
    if (key.length === 1 && !modified) return 'type';
    return null;
}

// DOM side of the keyboard model, shared by the dropdown, the context menu, submenus and the select list. `items` are the enabled elements
// in order; `label(el)` gives the text typeahead matches. Returns true when the key was a movement or typeahead key (and was handled).
// `state` is a { buffer, at } object kept by the caller between keys.
export function moveFocus(event, items, state, label = el => el.textContent, focus = el => el.focus({ preventScroll: true })) {
    const at = items.indexOf(event.target.closest?.('pk-menu-item, [role="option"]') ?? event.target);
    const to = nextIndex(at, items.length, event.key);
    if (to !== null) { event.preventDefault(); focus(items[to]); return true; }
    if (keyAction(event.key, { modified: event.ctrlKey || event.metaKey || event.altKey }) !== 'type' || event.key === ' ') return false;
    const now = Date.now();
    state.buffer = typeaheadBuffer(state.buffer ?? '', event.key, now - (state.at ?? 0));
    state.at = now;
    const hit = typeaheadIndex(items.map(label), at, state.buffer);
    if (hit >= 0) { event.preventDefault(); focus(items[hit]); }
    return true;
}

// Only a same-site path or an http(s) link may be navigated to from a menu row or a command.
export const safeLink = href => (typeof href === 'string' && href && !(/^[\w+.-]+:/.test(href) && !/^https?:/i.test(href)) ? href : null);

// Shared by the elements that host a native <dialog> (dialog, drawer, command palette, lightbox): keep the dialog in step with the `open`
// prop, ask before closing (a cancelable pk-close the Blazor side may veto), and clean up the top layer when the element leaves the page.
export function syncDialog(el, dlg) {
    if (el.open && !dlg.open && el.isConnected) { if (el.docked) dlg.show(); else dlg.showModal(); el.emit('pk-open', {}); }
    else if (!el.open && dlg.open) { dlg.$sync = true; dlg.close(); el.dispatchEvent(new Event('close')); }
}

// A close request: the host hears a cancelable pk-close first; a controlled element (Blazor owns `open`) never closes itself, it waits for open to change.
export const requestClose = (el, reason) => el.emit('pk-close', { reason }) && !el.controlled;

export function wireDialog(el, dlg, { backdrop = false } = {}) {
    dlg.addEventListener('cancel', e => { if (!requestClose(el, 'escape')) e.preventDefault(); });
    dlg.addEventListener('close', () => { if (dlg.$sync) { dlg.$sync = false; return; } if (el.open) el.open = false; el.dispatchEvent(new Event('close')); });
    if (backdrop) dlg.addEventListener('click', e => { if (e.target === dlg && backdrop() && requestClose(el, 'backdrop')) el.open = false; });
    if (el.docked !== undefined) dlg.addEventListener('keydown', e => { if (e.key === 'Escape' && el.docked && requestClose(el, 'escape')) el.open = false; });
    el.shadowRoot.addEventListener('click', e => { if (e.target.closest?.('[data-action="close"]') && requestClose(el, 'close')) el.open = false; });
}

// Shared by the mountX(container, options) modules (gallery tools shipped in dist): making sure the SDK stylesheets are in the
// document the module mounts into, and telling apart a URL from a ready object in an option. No DOM beyond the one document passed in.

// Add a <link rel="stylesheet"> for each absolute href the document does not already load; resolves when all have loaded (or failed:
// the mount goes ahead unstyled rather than never).
export function ensureStyles(hrefs, doc = document) {
    const have = new Set([...doc.querySelectorAll('link[rel="stylesheet"]')].map(l => l.href));
    return Promise.all(hrefs.filter(h => !have.has(h)).map(href => new Promise(resolve => {
        const link = doc.createElement('link');
        link.rel = 'stylesheet'; link.href = href;
        link.addEventListener('load', resolve, { once: true });
        link.addEventListener('error', resolve, { once: true });
        doc.head.append(link);
    })));
}

// Resolve stylesheet paths written relative to a module against that module's own address.
export const styleUrls = (paths, base) => paths.map(p => new URL(p, base).href);

// A string option is a URL to fetch JSON from; anything else is the value itself.
export async function loadJson(value, fetchFn = globalThis.fetch) {
    if (typeof value !== 'string') return value;
    const res = await fetchFn(value);
    if (!res.ok) throw new Error(`${value}: ${res.status}`);
    return res.json();
}

// Plainkit side-nav logic: the filter box, arrow-key tree navigation, the icon-rail flyout and persisted state. Pure, so it can be
// tested without a DOM. The elements (<pk-side-nav>, <pk-nav-item>) call these.
//
// A nav is a flat list of entries { id, label, parent }, parent being the id of the branch it sits under (or null).

// Entries that stay visible for a filter query, and the branches to open so a match is not hidden inside a folded one. A branch stays
// visible when it or any descendant matches. An empty query shows everything and opens nothing.
export function filterNav(entries, query) {
    const q = query.trim().toLowerCase();
    const all = new Set(entries.map(e => e.id));
    if (!q) return { visible: all, open: new Set(), matches: new Set(all) };
    const byId = new Map(entries.map(e => [e.id, e]));
    const matches = new Set(entries.filter(e => e.label.toLowerCase().includes(q)).map(e => e.id));
    const visible = new Set(matches);
    const open = new Set();
    for (const id of matches) {
        for (let p = byId.get(id)?.parent; p; p = byId.get(p)?.parent) { visible.add(p); open.add(p); }
    }
    return { visible, open, matches };
}

// Wraps the matched text of a label for highlighting: [{ text, match }].
export function splitMatch(label, query) {
    const q = query.trim().toLowerCase();
    const at = q ? label.toLowerCase().indexOf(q) : -1;
    if (at < 0) return [{ text: label, match: false }];
    return [{ text: label.slice(0, at), match: false }, { text: label.slice(at, at + q.length), match: true }, { text: label.slice(at + q.length), match: false }].filter(r => r.text);
}

// What an arrow key does on a nav row. ctx: { expanded, hasChildren, isChild }. Returns 'next' | 'prev' | 'first' | 'last' | 'expand' |
// 'collapse' | 'focus-child' | 'focus-parent' | null. Right opens a folded branch, then steps into it; Left folds an open branch, or
// steps up from a child to its branch.
export function treeKey(key, { expanded = false, hasChildren = false, isChild = false } = {}) {
    switch (key) {
        case 'ArrowDown': return 'next';
        case 'ArrowUp': return 'prev';
        case 'Home': return 'first';
        case 'End': return 'last';
        case 'ArrowRight': return hasChildren ? (expanded ? 'focus-child' : 'expand') : null;
        case 'ArrowLeft': return hasChildren && expanded ? 'collapse' : isChild ? 'focus-parent' : null;
        default: return null;
    }
}

// Persisted state: the ids of open branches and whether the rail is collapsed, as a small JSON string that survives a bad read.
export const serializeNav = (openIds, collapsed) => JSON.stringify({ o: [...openIds].sort(), c: !!collapsed });

export function parseNav(text) {
    try {
        const v = JSON.parse(text);
        const open = Array.isArray(v?.o) ? v.o.filter(x => typeof x === 'string').slice(0, 200) : [];
        return { open, collapsed: v?.c === true };
    } catch {
        return { open: [], collapsed: false };
    }
}

// In the collapsed rail a branch opens as a flyout beside it (labels are hidden, so the rail row also needs a tooltip).
export const railFlyoutPlacement = 'right-start';
export const railRowTooltip = label => (label ?? '').trim();

// Below this width the nav is an off-canvas drawer instead of a column or a rail.
export const DRAWER_BREAKPOINT = 1024;
export const navMode = (width, collapsed) => (width <= DRAWER_BREAKPOINT ? 'drawer' : collapsed ? 'rail' : 'full');

// Plainkit command palette logic: fuzzy matching, ranking, grouping and recents. Pure, so it can be tested without a DOM.
// The element (<pk-command-palette>) opens on Ctrl/Cmd+K, filters its items as you type and fires "pk-select".
//
// Item: { id, label, group?, hint?, keywords?: string, href?, shortcut? }. Ranking prefers a match at the start of a word,
// consecutive letters, and an earlier match; a label match beats a keywords-only match.

export const MAX_RECENTS = 5;
export const RECENTS_GROUP = 'Recent';

// Subsequence match of `query` in `text`. Returns { score, indexes } (indexes are the matched character positions, for highlighting)
// or null when the letters do not appear in order. Case-insensitive; whitespace in the query is ignored.
export function fuzzyMatch(query, text) {
    const q = query.toLowerCase().replace(/\s+/g, '');
    const t = text.toLowerCase();
    if (!q) return { score: 0, indexes: [] };
    const indexes = [];
    const run = { score: t.startsWith(q) ? 10 : 0, from: 0, prev: -2 };
    for (const ch of q) {
        const at = t.indexOf(ch, run.from);
        if (at === -1) return null;
        const wordStart = at === 0 || /[\s\-_/.:]/.test(t[at - 1]);
        run.score += 1 + (wordStart ? 6 : 0) + (at === run.prev + 1 ? 5 : 0) - Math.min(at * 0.05, 2);
        indexes.push(at); run.prev = at; run.from = at + 1;
    }
    return { score: run.score, indexes };
}

const labelOf = item => item.label ?? '';

// Items that match, best first (ties keep their original order). Each result: { item, score, indexes } with indexes into the label.
export function rank(items, query) {
    const q = query.trim();
    if (!q) return items.map(item => ({ item, score: 0, indexes: [] }));
    const out = [];
    items.forEach((item, order) => {
        const m = fuzzyMatch(q, labelOf(item));
        if (m) { out.push({ item, score: m.score + 4, indexes: m.indexes, order }); return; }
        const k = item.keywords ? fuzzyMatch(q, item.keywords) : null;
        const g = item.group?.toLowerCase().includes(q.toLowerCase()) ? { score: 1 } : null;
        const alt = k ?? g;
        if (alt) out.push({ item, score: alt.score, indexes: [], order });
    });
    return out.sort((a, b) => b.score - a.score || a.order - b.order).map(({ order, ...r }) => r);
}

// Adds an id to the front of the recents, once, capped.
export function pushRecent(recents, id, max = MAX_RECENTS) {
    return [id, ...recents.filter(r => r !== id)].slice(0, max);
}

// The sections to show. With no query: recents first (when known items exist for them), then every group in the order it first appears.
// With a query: one flat ranked section with no heading, so the best match is on top whatever its group.
export function sections(items, query, recents = []) {
    if (query.trim()) return [{ title: null, results: rank(items, query) }];
    const byId = new Map(items.map(i => [i.id, i]));
    const out = [];
    const recent = recents.map(id => byId.get(id)).filter(Boolean);
    if (recent.length) out.push({ title: RECENTS_GROUP, results: recent.map(item => ({ item, score: 0, indexes: [] })) });
    const order = []; const groups = new Map();
    for (const item of items) {
        const g = item.group ?? '';
        if (!groups.has(g)) { groups.set(g, []); order.push(g); }
        groups.get(g).push({ item, score: 0, indexes: [] });
    }
    for (const g of order) out.push({ title: g || null, results: groups.get(g) });
    return out;
}

// Splits a label into runs of { text, match } for highlighting, from the matched indexes.
export function highlight(label, indexes) {
    const marked = new Set(indexes);
    const runs = [];
    [...label].forEach((ch, i) => {
        const match = marked.has(i);
        if (runs.length && runs[runs.length - 1].match === match) runs[runs.length - 1].text += ch; else runs.push({ text: ch, match });
    });
    return runs;
}

// Only a same-site path or an http(s) URL may be navigated to; any other scheme is ignored.
export function safeHref(href) {
    if (typeof href !== 'string' || !href) return null;
    if (/^[\w+.-]+:/.test(href) && !/^https?:/i.test(href)) return null;
    return href;
}

// Whether a key event is the palette shortcut: Ctrl+K or Cmd+K, no other modifier.
export const isPaletteShortcut = e => !!((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && (e.key === 'k' || e.key === 'K'));

// Pure logic behind the performance monitor (modules/performance): ratings against the Core Web Vitals thresholds, frame-rate maths,
// rolling series, resource summaries and number formatting. No DOM and no browser API, so node tests cover all of it.

// [good, poor] upper bounds: at or below the first is good, above the second is poor, between is "needs work".
export const THRESHOLDS = Object.freeze({
    lcp: [2500, 4000], fcp: [1800, 3000], ttfb: [800, 1800], inp: [200, 500], cls: [0.1, 0.25],
    fps: [30, 55], // higher is better; see rateFps
    longTask: [50, 200],
});

// 'good' | 'warn' | 'poor' for a lower-is-better metric; '' when there is no value yet.
export function rate(metric, value) {
    const t = THRESHOLDS[metric];
    if (!t || value === null || value === undefined || Number.isNaN(value)) return '';
    return value <= t[0] ? 'good' : value <= t[1] ? 'warn' : 'poor';
}

// Frames per second: 55 and up is good, 30 and up needs work, below is poor.
export function rateFps(fps) {
    if (fps === null || fps === undefined || Number.isNaN(fps)) return '';
    return fps >= THRESHOLDS.fps[1] ? 'good' : fps >= THRESHOLDS.fps[0] ? 'warn' : 'poor';
}

// Frames per second from frame timestamps (ms, ascending) inside the last `windowMs`. null when fewer than two frames are in the window.
export function fpsFrom(timestamps, now = timestamps.at(-1) ?? 0, windowMs = 1000) {
    const recent = timestamps.filter(t => t >= now - windowMs && t <= now);
    if (recent.length < 2) return null;
    const span = recent.at(-1) - recent[0];
    return span > 0 ? Math.round(((recent.length - 1) * 1000) / span) : null;
}

// Appends to a rolling series, keeping the newest `max`. Returns a new array.
export const pushSample = (series, value, max = 60) => [...series, value].slice(-max);

// Cumulative layout shift: shifts within 1 s of each other and 5 s of the window's start form a session; the value is the worst session.
// entries: [{ startTime, value, hadRecentInput }].
export function clsFrom(entries) {
    let worst = 0, session = 0, first = 0, last = 0;
    for (const e of entries) {
        if (e.hadRecentInput) continue;
        if (session && e.startTime - last < 1000 && e.startTime - first < 5000) session += e.value;
        else { session = e.value; first = e.startTime; }
        last = e.startTime;
        worst = Math.max(worst, session);
    }
    return worst;
}

// Interaction to next paint, approximated as the slowest interaction (event entries with an interactionId, one per interaction).
export function inpFrom(events) {
    const byInteraction = new Map();
    for (const e of events) if (e.interactionId) byInteraction.set(e.interactionId, Math.max(byInteraction.get(e.interactionId) ?? 0, e.duration));
    const all = [...byInteraction.values()].sort((a, b) => b - a);
    if (!all.length) return null;
    // With 50 or more interactions the 98th percentile is reported (one outlier is forgiven per 50), like the web-vitals library.
    return all[Math.min(all.length - 1, Math.floor(all.length / 50))];
}

// Long tasks (main thread blocked for 50 ms or more): the count, and the total time beyond the 50 ms budget (blocking time).
export function longTaskStats(tasks) {
    return { count: tasks.length, blocking: Math.round(tasks.reduce((n, t) => n + Math.max(0, t.duration - 50), 0)), worst: Math.round(Math.max(0, ...tasks.map(t => t.duration))) };
}

const TYPES = { script: 'script', link: 'style', css: 'style', img: 'image', image: 'image', fetch: 'fetch', xmlhttprequest: 'fetch', font: 'font' };

// Resource timing entries grouped by kind, with totals and the slowest few. entries: [{ name, duration, transferSize, initiatorType }].
export function summarizeResources(entries, top = 5) {
    const byType = {};
    let bytes = 0;
    for (const e of entries) {
        const type = TYPES[e.initiatorType] ?? 'other';
        const b = byType[type] ??= { count: 0, bytes: 0 };
        b.count++; b.bytes += e.transferSize || 0; bytes += e.transferSize || 0;
    }
    const slowest = [...entries].sort((a, b) => b.duration - a.duration).slice(0, top).map(e => ({ name: e.name, duration: Math.round(e.duration), bytes: e.transferSize || 0 }));
    return { count: entries.length, bytes, byType, slowest };
}

export function formatBytes(n) {
    if (n === null || n === undefined || Number.isNaN(n)) return '-';
    if (n < 1024) return `${Math.round(n)} B`;
    if (n < 1024 * 1024) return `${(n / 1024).toFixed(n < 10240 ? 1 : 0)} KB`;
    return `${(n / 1048576).toFixed(1)} MB`;
}

export function formatMs(n) {
    if (n === null || n === undefined || Number.isNaN(n)) return '-';
    return n < 1000 ? `${Math.round(n)} ms` : `${(n / 1000).toFixed(2)} s`;
}

// The last path segment of a URL, for a compact resource name; the whole string when it is not a URL.
export function shortName(url) {
    try { const u = new URL(url); return u.pathname.split('/').filter(Boolean).at(-1) ?? u.host; } catch { return String(url); }
}

// Points for an SVG polyline: values scaled into a width x height box, oldest at the left. max fixes the top of the scale (else the data's).
export function sparkPoints(values, width = 120, height = 32, max) {
    if (values.length < 2) return '';
    const top = max ?? Math.max(...values, 1);
    const step = width / (values.length - 1);
    return values.map((v, i) => `${(i * step).toFixed(1)},${(height - Math.min(1, Math.max(0, v / top)) * height).toFixed(1)}`).join(' ');
}

// Plainkit entry module: one import wires the page. Components are custom elements (pk-*) that load on demand, so this only starts the
// element loader and the declarative invokers; a page may also import just the modules it needs.
//
//   <script type="module">import { initPlainkit } from './plainkit/js/plainkit.js'; initPlainkit();</script>

import { initInvokers } from './invokers.js';
import { createLogger } from './log.js';
import { loadElements, observeElements } from './loader.js';
import { PK_VERSION } from './version.js';

export * from './version.js';
export * from './dynamic.js';
export * from './invokers.js';
export * from './log.js';
export * from './loader.js';
export * from './theme.js';
export * from './colour.js';

const log = createLogger('plainkit');

export function initPlainkit(root = document) {
    log.debug(`Plainkit ${PK_VERSION} starting`);
    initInvokers(root);
    loadElements(root).catch(error => log.error('the element loader failed', error));
    if (root === document) observeElements(document);
}

// Plainkit positioning: the one small module that places a floating layer (tooltip, popover, menu, palette flyout) next to an
// anchor, flips it to the opposite side when it would leave the viewport, and shifts it along the other axis to stay inside.
// Framework-free; no imports. The layer is position:fixed, so no overflow ancestor can clip it.
//
//   place(anchor, floating, { placement: 'bottom-start', offset: 4, padding: 8 })
//     anchor    an element, or a point/rect { x, y, width?, height? } (a context menu passes the pointer)
//     placement top | bottom | left | right, each optionally -start or -end (default centred)
//   Sets left/top from the CSSOM and data-placement (the side actually used) on the floating element.
//   autoUpdate(anchor, floating, options) re-places on scroll and resize and returns a stop function.
//   onOutside(elements, close) closes on a pointerdown outside all of them or on Escape; returns a stop function.

const OPPOSITE = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };

// Pure geometry. anchor: { left, top, right, bottom }, size: { width, height }, viewport: { width, height }.
// Returns { x, y, side } in viewport coordinates.
export function computePosition(anchor, size, viewport, options = {}) {
    const { placement = 'bottom', offset = 4, padding = 8, flip = true, shift = true } = options;
    const [wanted, align = 'center'] = placement.split('-');
    const aw = anchor.right - anchor.left;
    const ah = anchor.bottom - anchor.top;
    const at = side => {
        if (side === 'top' || side === 'bottom') {
            const x = align === 'start' ? anchor.left : align === 'end' ? anchor.right - size.width : anchor.left + aw / 2 - size.width / 2;
            return { x, y: side === 'top' ? anchor.top - size.height - offset : anchor.bottom + offset };
        }
        const y = align === 'start' ? anchor.top : align === 'end' ? anchor.bottom - size.height : anchor.top + ah / 2 - size.height / 2;
        return { x: side === 'left' ? anchor.left - size.width - offset : anchor.right + offset, y };
    };
    const over = (side, p) => (side === 'top' || side === 'bottom'
        ? Math.max(0, padding - p.y) + Math.max(0, p.y + size.height - (viewport.height - padding))
        : Math.max(0, padding - p.x) + Math.max(0, p.x + size.width - (viewport.width - padding)));
    const first = at(wanted);
    const alt = at(OPPOSITE[wanted]);
    const flipped = flip && over(wanted, first) > 0 && over(OPPOSITE[wanted], alt) < over(wanted, first);
    const side = flipped ? OPPOSITE[wanted] : wanted;
    const placed = flipped ? alt : first;
    if (shift) {
        const clamp = (v, lo, hi) => Math.max(lo, Math.min(v, Math.max(lo, hi)));
        const across = side === 'top' || side === 'bottom';
        return { x: across ? clamp(placed.x, padding, viewport.width - size.width - padding) : placed.x, y: across ? placed.y : clamp(placed.y, padding, viewport.height - size.height - padding), side };
    }
    return { x: placed.x, y: placed.y, side };
}

const rectOf = anchor => {
    if (typeof anchor.getBoundingClientRect === 'function') { const r = anchor.getBoundingClientRect(); return { left: r.left, top: r.top, right: r.right, bottom: r.bottom }; }
    return { left: anchor.x, top: anchor.y, right: anchor.x + (anchor.width ?? 0), bottom: anchor.y + (anchor.height ?? 0) };
};

export function place(anchor, floating, options = {}) {
    const style = floating.style;
    style.position = 'fixed'; style.left = '0px'; style.top = '0px';
    const box = floating.getBoundingClientRect();
    const view = { width: document.documentElement.clientWidth, height: document.documentElement.clientHeight };
    const r = computePosition(rectOf(anchor), { width: box.width, height: box.height }, view, options);
    style.left = `${Math.round(r.x)}px`; style.top = `${Math.round(r.y)}px`;
    floating.setAttribute('data-placement', r.side);
    return r;
}

export function autoUpdate(anchor, floating, options = {}) {
    const st = { frame: 0 };
    const run = () => { st.frame = 0; place(anchor, floating, options); };
    const queue = () => { if (!st.frame) st.frame = requestAnimationFrame(run); };
    window.addEventListener('scroll', queue, true);
    window.addEventListener('resize', queue);
    return () => { window.removeEventListener('scroll', queue, true); window.removeEventListener('resize', queue); if (st.frame) cancelAnimationFrame(st.frame); };
}

// Whether a target lies inside any of the layers.
export function isInside(target, elements) { return elements.some(el => el && el.contains(target)); }

export function onOutside(elements, close) {
    const down = e => { if (!isInside(e.target, elements)) close(e); };
    const key = e => { if (e.key === 'Escape') close(e); };
    document.addEventListener('pointerdown', down, true);
    document.addEventListener('keydown', key);
    return () => { document.removeEventListener('pointerdown', down, true); document.removeEventListener('keydown', key); };
}

// Clears what place() set, so a layer that a stylesheet positions (a static menu inside a folded navbar) is not left fixed.
export function unplace(floating) {
    const s = floating.style;
    s.position = ''; s.left = ''; s.top = '';
    floating.removeAttribute('data-placement');
}

// Plainkit quality checks, plain JS. Two halves: collect() reads a document into plain measures, evaluate() turns measures
// into findings. evaluate() and the text scanners are pure, so Node tests them without a browser.
// Thresholds live in one object (DEFAULTS) that a caller overrides; the scorecard keeps its own copy in scoring.data.js.
// Framework-free; no imports.

export const DEFAULTS = Object.freeze({
    touchTargetPx: 44,          // interactive controls smaller than this (either side) fail on a phone
    maxNestedScrollers: 0,      // a scroll container inside another scroll container
    literalColour: /#[0-9a-fA-F]{3,8}\b|\brgba?\(/,
    interactive: 'a[href], button, input:not([type="hidden"]), select, textarea, summary, [role="button"], [role="tab"], [tabindex]:not([tabindex="-1"])',
    maxFocusProbe: 40,
    minGapPx: 4,                // controls in a row or stack closer than this fail (the --gap-min token)
    minPaddingPx: 4,            // text closer than this to the edge of a bordered or filled box fails
    gapTolerancepx: 6,          // gaps within one stack may differ by at most this
    flush: '.cv-scroll, .cv-row, .input-group, .btn-group, .ft-list, .co, .csr-group, .tabs, .pagination, .list-group, .gal-item, .dg-body, .flyout-panel--docked, .stat-card-value-row, .workspace, .workspace-main, .ft-row, .combo-popup, .tag-input',
});

const cssPath = el => {
    const parts = [];
    for (let n = el; n && n.nodeType === 1 && parts.length < 4; n = n.parentElement) {
        const cls = [...n.classList].slice(0, 2).map(c => '.' + c).join('');
        parts.unshift(n.tagName.toLowerCase() + (n.id ? '#' + n.id : '') + cls);
    }
    return parts.join(' > ');
};

// Accessible name of a control, the way the checks need it: aria-label, aria-labelledby, label, alt, title, placeholder, text.
export function accessibleName(el) {
    const doc = el.ownerDocument;
    const attr = n => (el.getAttribute(n) ?? '').trim();
    if (attr('aria-label')) return attr('aria-label');
    const by = attr('aria-labelledby');
    if (by) { const t = by.split(/\s+/).map(id => doc.getElementById(id)?.textContent ?? '').join(' ').trim(); if (t) return t; }
    if (el.labels?.length) { const t = [...el.labels].map(l => l.textContent).join(' ').trim(); if (t) return t; }
    if (attr('alt')) return attr('alt');
    const text = (el.textContent ?? '').trim();
    if (text) return text;
    if (el.tagName === 'INPUT' && ['button', 'submit', 'reset'].includes(el.type) && el.value) return el.value;
    return attr('title') || attr('placeholder');
}

const INLINE = /^(SPAN|A|CODE|STRONG|EM|B|I|SMALL|LABEL|SUP|SUB|MARK|BR|SVG|USE|IMG|KBD|TIME|ABBR)$/;
const CONTROL = /^(BUTTON|INPUT|SELECT|TEXTAREA|A)$/;

// Spacing measures: consecutive block siblings with no gap, controls sitting closer than the minimum gap, text touching the
// edge of a box that has its own border or fill, and containers whose gaps disagree. Containers marked data-flush, or matching
// cfg.flush (rows that are flush by design: code lines, tree rows, joined groups), are skipped.
export function spacingMeasures(scope, win, cfg) {
    const out = [];
    const skip = el => el.closest?.(cfg.flush) || el.closest?.('[data-flush]');
    const visible = el => { const s = win.getComputedStyle(el); if (s.position === 'absolute' || s.position === 'fixed' || s.display === 'none') return null; const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0 ? r : null; };
    for (const el of scope.querySelectorAll('*')) {
        if (/^(TR|THEAD|TBODY|TFOOT|TABLE|SELECT|SVG|PRE|HEAD|SCRIPT|STYLE|UL|OL|DL)$/.test(el.tagName) || skip(el)) continue;
        const cs = win.getComputedStyle(el);
        // Text (or an inline control) sitting hard against the edge of a box that has its own border or fill.
        const hasText = [...el.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
        if (hasText && !INLINE.test(el.tagName) && !/^(TD|TH|LI|BUTTON|SUMMARY|OPTION|CODE)$/.test(el.tagName)) {
            const boxed = parseFloat(cs.borderLeftWidth) > 0 || !/rgba\(0, 0, 0, 0\)|transparent/.test(cs.backgroundColor);
            const left = parseFloat(cs.paddingLeft);
            if (boxed && left < cfg.minPaddingPx) out.push({ kind: 'text-at-edge', selector: cssPath(el), value: left, min: cfg.minPaddingPx });
        }
        const kids = [...el.children].map(k => [k, visible(k)]).filter(([, r]) => r);
        if (kids.length < 2 || !/(block|flex|grid|flow-root)/.test(cs.display)) continue;
        const gaps = [];
        for (let i = 1; i < kids.length; i++) {
            const [a, ra] = kids[i - 1]; const [b, rb] = kids[i];
            const vertical = rb.top >= ra.bottom - 1; const horizontal = !vertical && rb.left >= ra.right - 1 && rb.top < ra.bottom && ra.top < rb.bottom;
            const gap = vertical ? rb.top - ra.bottom : horizontal ? rb.left - ra.right : null;
            if (gap === null) continue;
            const bothControls = CONTROL.test(a.tagName) && CONTROL.test(b.tagName);
            if (bothControls && gap < cfg.minGapPx) out.push({ kind: gap < 0.5 ? 'zero-gap' : 'tight-controls', selector: cssPath(b), value: Math.round(gap * 10) / 10, min: cfg.minGapPx });
            else if (vertical && gap < 0.5 && !INLINE.test(a.tagName) && !INLINE.test(b.tagName) && !(a.tagName === 'INPUT' || b.tagName === 'INPUT')) out.push({ kind: 'zero-gap', selector: cssPath(b), value: 0, min: cfg.minGapPx });
            if (vertical) gaps.push(gap);
        }
        if (gaps.length >= 3 && Math.max(...gaps) - Math.min(...gaps) > cfg.gapTolerancepx) out.push({ kind: 'inconsistent-gaps', selector: cssPath(el), value: Math.round((Math.max(...gaps) - Math.min(...gaps)) * 10) / 10, min: cfg.gapTolerancepx });
    }
    return out;
}

export function collect(root, options = {}) {
    const cfg = { ...DEFAULTS, ...options };
    const doc = root.ownerDocument ?? root;
    const win = doc.defaultView;
    const scope = root.querySelectorAll ? root : doc;
    const controls = [];
    for (const el of scope.querySelectorAll(cfg.interactive)) {
        if (el.disabled || el.hidden || el.closest('[hidden]')) continue;
        // A checkbox or radio is tapped through its label, so the label is the target that counts.
        const r = (el.type === 'checkbox' || el.type === 'radio') && el.labels?.length ? el.labels[0].getBoundingClientRect() : el.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) continue;
        controls.push({ selector: cssPath(el), tag: el.tagName.toLowerCase(), role: el.getAttribute('role'), name: accessibleName(el), width: r.width, height: r.height, tabindex: el.hasAttribute('tabindex') ? Number(el.getAttribute('tabindex')) : null });
    }
    const images = [...scope.querySelectorAll('img')].map(el => ({ selector: cssPath(el), alt: el.getAttribute('alt') }));
    const scrollers = [];
    for (const el of scope.querySelectorAll('*')) {
        const s = win.getComputedStyle(el);
        const scrolls = /(auto|scroll)/.test(s.overflowX + s.overflowY) && (el.scrollHeight > el.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1);
        if (!scrolls) continue;
        let depth = 0;
        for (let p = el.parentElement; p; p = p.parentElement) {
            const ps = win.getComputedStyle(p);
            if (/(auto|scroll)/.test(ps.overflowX + ps.overflowY) && p !== doc.body && p !== doc.documentElement && (p.scrollHeight > p.clientHeight + 1 || p.scrollWidth > p.clientWidth + 1)) depth++;
        }
        scrollers.push({ selector: cssPath(el), depth });
    }
    const literals = [];
    for (const el of scope.querySelectorAll('[style]')) {
        const v = el.getAttribute('style');
        if (cfg.literalColour.test(v)) literals.push({ selector: cssPath(el), value: v });
    }
    const de = doc.documentElement;
    const visibleChildren = [...(scope.children ?? [])].filter(el => !/^(SCRIPT|STYLE)$/.test(el.tagName) && el.getBoundingClientRect().width > 0 && el.getBoundingClientRect().height > 0).length;
    const spacing = spacingMeasures(scope, win, cfg);
    return { controls, images, scrollers, literals, spacing, visibleChildren, overflowX: de.scrollWidth - de.clientWidth, width: win.innerWidth, nodes: scope.querySelectorAll('*').length };
}

// Findings from measures: { check, category, severity: 'error' | 'warn', selector, message }.
export function evaluate(m, options = {}) {
    const cfg = { ...DEFAULTS, ...options };
    const out = [];
    const add = (check, category, severity, selector, message) => out.push({ check, category, severity, selector, message });
    for (const c of m.controls) {
        if (!c.name) add('unnamed-input', 'accessibility', 'error', c.selector, `${c.tag} has no accessible name`);
        if (c.tabindex !== null && c.tabindex > 0) add('positive-tabindex', 'accessibility', 'warn', c.selector, 'positive tabindex overrides the natural tab order');
        if (cfg.phone && (c.width < cfg.touchTargetPx - 0.5 || c.height < cfg.touchTargetPx - 0.5)) add('touch-target', 'look', 'warn', c.selector, `${Math.round(c.width)}x${Math.round(c.height)}px is under ${cfg.touchTargetPx}px on a phone`);
    }
    for (const i of m.images) if (i.alt === null) add('image-alt', 'accessibility', 'error', i.selector, 'image has no alt attribute');
    for (const s of m.scrollers) if (s.depth > cfg.maxNestedScrollers) add('nested-scroll', 'look', 'error', s.selector, `scroll container nested ${s.depth} deep inside another`);
    for (const l of m.literals) add('literal-colour', 'look', 'warn', l.selector, `inline literal colour: ${l.value}`);
    for (const s of m.spacing ?? []) add(s.kind, 'look', s.kind === 'zero-gap' ? 'error' : 'warn', s.selector, s.kind === 'text-at-edge' ? `text is ${s.value}px from the edge of its box (minimum ${s.min}px)` : s.kind === 'inconsistent-gaps' ? `gaps in this stack differ by ${s.value}px (tolerance ${s.min}px)` : `${s.kind === 'zero-gap' ? 'no gap' : s.value + 'px gap'} between adjacent siblings (minimum ${s.min}px)`);
    if (m.visibleChildren === 0) add('empty-preview', 'look', 'error', 'body', 'the preview stage has no visible content');
    if (m.overflowX > 0) add('horizontal-overflow', 'look', 'error', 'document', `page is ${m.overflowX}px wider than the ${m.width}px viewport`);
    return out;
}

// Literal colours in stylesheet text (tokens.css is where they belong, so callers skip it): [{ line, text }].
export function literalColours(cssText, literal = DEFAULTS.literalColour) {
    const clean = cssText.replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '));
    const found = [];
    clean.split('\n').forEach((line, i) => { const m = literal.exec(line); if (m) found.push({ line: i + 1, text: line.trim() }); });
    return found;
}

// Literal lengths (px or rem/em) declared in stylesheet text that are not a token: a rough adherence measure. [{ line, text }].
export function literalSizes(cssText) {
    const clean = cssText.replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '));
    const found = [];
    clean.split('\n').forEach((line, i) => {
        if (/^\s*--/.test(line) || /@media|@container/.test(line)) return;
        if (/(padding|margin|gap|font-size|border-radius|width|height)[a-z-]*\s*:[^;]*\b\d*\.?\d+(px|rem|em)\b/.test(line) && !/var\(--/.test(line)) found.push({ line: i + 1, text: line.trim() });
    });
    return found;
}

// Stylesheet statistics from its text: bytes, rule count, selector count, declaration count.
export function cssStats(cssText) {
    const clean = cssText.replace(/\/\*[\s\S]*?\*\//g, '');
    const rules = (clean.match(/\{/g) ?? []).length;
    const selectors = [...clean.matchAll(/([^{}]+)\{/g)].filter(m => !m[1].trim().startsWith('@')).reduce((n, m) => n + m[1].split(',').length, 0);
    return { bytes: cssText.length, rules, selectors, declarations: (clean.match(/;/g) ?? []).length };
}

// Selectors in stylesheet text that match nothing in `documents` (browser) - an estimate: pseudo-states and media are skipped.
export function unusedSelectors(cssText, documents) {
    const clean = cssText.replace(/\/\*[\s\S]*?\*\//g, '');
    const unused = []; let total = 0;
    for (const m of clean.matchAll(/([^{}]+)\{/g)) {
        if (m[1].trim().startsWith('@')) continue;
        for (const raw of m[1].split(',')) {
            const sel = raw.trim().replace(/::?[a-z-]+(\([^)]*\))?/gi, '').trim();
            if (!sel || /^(\*|html|body|:root)/.test(sel)) continue;
            total++;
            let hit = false;
            for (const d of documents) { try { if (d.querySelector(sel)) { hit = true; break; } } catch { hit = true; } }
            if (!hit) unused.push(raw.trim());
        }
    }
    return { total, unused };
}

// Selectors of every rule in the document's stylesheets that draws a focus ring (a :focus-visible or :focus rule with an outline
// or box-shadow), with the pseudo-class removed so they can be tested with matches(). Programmatic focus() does not reliably
// trigger :focus-visible, so the rules are read instead of the computed style.
export function focusRingSelectors(doc) {
    const out = [];
    const walk = sheet => {
        let rules; try { rules = sheet.cssRules; } catch { return; }
        for (const r of rules) {
            if (r.styleSheet) walk(r.styleSheet);
            else if (r.cssRules && !r.selectorText) { for (const inner of r.cssRules) visit(inner); }
            else visit(r);
        }
    };
    const visit = r => {
        if (!r.selectorText || !/:focus/.test(r.selectorText)) return;
        const s = r.style; const ring = (s.outlineStyle && s.outlineStyle !== 'none') || (s.outline && !/none|^0/.test(s.outline)) || (s.boxShadow && s.boxShadow !== 'none');
        if (!ring) return;
        for (const sel of r.selectorText.split(',')) out.push(sel.replace(/:focus-visible|:focus-within|:focus/g, '').trim() || '*');
    };
    for (const sheet of doc.styleSheets) walk(sheet);
    return out;
}

// Controls with no rule that would draw a focus ring for them.
export function focusProblems(root, options = {}) {
    const cfg = { ...DEFAULTS, ...options };
    const doc = root.ownerDocument ?? root;
    const rings = focusRingSelectors(doc);
    const problems = [];
    const els = [...(root.querySelectorAll ?? doc.querySelectorAll).call(root, cfg.interactive)].filter(e => !e.disabled && e.getClientRects().length).slice(0, cfg.maxFocusProbe);
    for (const el of els) {
        const covered = rings.some(sel => { try { return el.matches(sel); } catch { return false; } });
        if (!covered) problems.push({ check: 'focus-visible', category: 'accessibility', severity: 'error', selector: cssPath(el), message: 'no stylesheet rule draws a focus indicator for it' });
    }
    return problems;
}

// Plainkit scoring: turn measurements into 0-100 scores, rank the worst first, and keep a history so a regression
// shows as a delta. Pure functions over a definitions object (scorecard/scoring.data.js); storage is passed in.
// Framework-free; no imports.

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));

// 100 at or better than good, 0 at or worse than poor, linear between; null when there is no measurement.
export function scoreMetric(value, { good, poor, lowerIsBetter = true }) {
    if (value === null || value === undefined || Number.isNaN(value)) return null;
    const t = lowerIsBetter ? (poor - value) / (poor - good) : (value - poor) / (good - poor);
    return Math.round(clamp(t, 0, 1) * 100);
}

// Weighted mean of the scored metrics of one category. Metrics with no measurement are left out. Returns { score, metrics }.
export function scoreCategory(def, measured) {
    const rows = []; let sum = 0; let weights = 0;
    for (const [key, m] of Object.entries(def.metrics)) {
        const value = measured[key];
        const score = scoreMetric(value, m);
        rows.push({ key, label: m.label, value: value ?? null, score, weight: m.weight ?? 1 });
        if (score !== null) { sum += score * (m.weight ?? 1); weights += m.weight ?? 1; }
    }
    return { score: weights ? Math.round(sum / weights) : null, metrics: rows };
}

// { overall, categories: { key: { label, score, metrics } } } from a flat map of measurements.
export function scoreAll(scoring, measured) {
    const categories = {}; let sum = 0; let weights = 0;
    for (const [key, def] of Object.entries(scoring.categories)) {
        const c = scoreCategory(def, measured);
        categories[key] = { label: def.label, weight: def.weight, ...c };
        if (c.score !== null) { sum += c.score * def.weight; weights += def.weight; }
    }
    return { overall: weights ? Math.round(sum / weights) : null, categories };
}

// A control's score: 100 minus a penalty per finding, floor 0. Findings are { severity }.
export function scoreFindings(findings, penalty) {
    return Math.max(0, 100 - findings.reduce((n, f) => n + (penalty[f.severity] ?? 0), 0));
}

// Rank items { name, score, findings } worst first (lowest score, then most findings, then name).
export function rankWorstFirst(items) {
    return [...items].sort((a, b) => (a.score - b.score) || ((b.findings?.length ?? 0) - (a.findings?.length ?? 0)) || String(a.name).localeCompare(b.name));
}

// Collapse repeated findings (same check + selector across widths and themes) into one row with a count.
export function groupFindings(findings) {
    const map = new Map();
    for (const f of findings) {
        const key = `${f.check}|${f.selector}`;
        const row = map.get(key) ?? { ...f, count: 0, contexts: [] };
        row.count++;
        if (f.context && !row.contexts.includes(f.context)) row.contexts.push(f.context);
        map.set(key, row);
    }
    return [...map.values()];
}

export function readHistory(storage, key) {
    try { const v = JSON.parse(storage.getItem(key) ?? '[]'); return Array.isArray(v) ? v : []; } catch { return []; }
}

// Append a run { at, overall, categories: { key: score }, items: { name: score } } and keep the newest `max`.
export function pushRun(storage, key, run, max = 40) {
    const history = [...readHistory(storage, key), run].slice(-max);
    try { storage.setItem(key, JSON.stringify(history)); } catch { /* storage full or blocked: the run is still returned */ }
    return history;
}

// Differences between two runs: overall and category deltas, and items whose score changed (regressions first).
export function deltas(previous, current) {
    if (!previous) return { overall: null, categories: {}, items: [] };
    const categories = {};
    for (const [k, v] of Object.entries(current.categories ?? {})) categories[k] = previous.categories?.[k] === undefined || v === null || previous.categories[k] === null ? null : v - previous.categories[k];
    const items = [];
    for (const [name, score] of Object.entries(current.items ?? {})) {
        const before = previous.items?.[name];
        if (before !== undefined && before !== score) items.push({ name, before, after: score, delta: score - before });
    }
    items.sort((a, b) => a.delta - b.delta);
    return { overall: current.overall === null || previous.overall === null ? null : current.overall - previous.overall, categories, items };
}

export const exportHistory = history => JSON.stringify({ version: 1, history }, null, 2);

export function importHistory(text) {
    const o = JSON.parse(text);
    const history = Array.isArray(o) ? o : o.history;
    if (!Array.isArray(history) || history.some(r => typeof r !== 'object' || r === null || !('at' in r))) throw new Error('not a scorecard history file');
    return history;
}

// Plainkit scroll aids: the arithmetic behind <pk-scroll-progress>, <pk-back-to-top> and the skip link. Pure, so it can be tested
// without a DOM. Each element listens to one scroller (the window, or the element named by `for`, e.g. the shell body).

export const TOP_THRESHOLD = 400;

// Scrolled fraction 0..1 of what can scroll; 0 when nothing scrolls.
export function scrollProgress(scrollTop, scrollHeight, clientHeight) {
    const room = scrollHeight - clientHeight;
    return room <= 0 ? 0 : Math.min(1, Math.max(0, scrollTop / room));
}

// Show the back-to-top button once the reader is past `threshold` px (default: a screen or so) and there is somewhere to go back to.
export const showBackToTop = (scrollTop, threshold = TOP_THRESHOLD) => scrollTop > threshold;

// Smooth unless the reader asked for less motion.
export const scrollBehavior = reducedMotion => (reducedMotion ? 'auto' : 'smooth');

// Overflowing strips (tabs, chips): which edges have content hidden beyond them, so the strip can show a fade and a scroll button there.
// scrollLeft is negative in right-to-left layouts in current browsers; its magnitude is what matters.
export function edgeState(scrollLeft, scrollWidth, clientWidth, eps = 1) {
    const at = Math.abs(scrollLeft);
    return { start: at > eps, end: at + clientWidth < scrollWidth - eps };
}

// How far a scroll button moves a strip: most of a screen of it, so the last visible item stays in view as context.
export const scrollStepPx = (clientWidth, fraction = 0.8) => Math.max(1, Math.round(clientWidth * fraction));

// The scrollLeft that brings a child fully into view with `margin` px around it; unchanged when it is already visible.
export function revealLeft(itemLeft, itemWidth, viewWidth, current, margin = 8) {
    if (itemLeft - margin < current) return Math.max(0, itemLeft - margin);
    const right = itemLeft + itemWidth + margin;
    return right > current + viewWidth ? right - viewWidth : current;
}

// A skip link may only point at a same-page fragment; anything else is ignored so it cannot become a redirect.
export const skipTarget = href => (typeof href === 'string' && /^#[\w-]+$/.test(href) ? href.slice(1) : null);

// The pure data logic of <pk-table>: sorting and filtering rows. It sits in js/ so node tests and other code can import it without a DOM.

// A comparable value: numbers ignore currency and grouping, dates parse, text folds case.
export function sortKey(value, type = 'text') {
    if (type === 'text') return String(value ?? '').toLowerCase();
    const n = type === 'number' ? (typeof value === 'number' ? value : parseFloat(String(value).replace(/[^0-9.+-]/g, ''))) : Date.parse(value);
    return Number.isNaN(n) ? -Infinity : n;
}

// Rows sorted by a column ({ key, type }), stable, text with numeric collation; a new array.
export function sortRows(rows, column, direction = 'ascending') {
    if (!column) return rows.slice();
    const s = direction === 'descending' ? -1 : 1, k = rows.map(r => sortKey(r[column.key], column.type));
    return rows.map((_, i) => i).sort((a, b) => s * (typeof k[a] === 'string' ? k[a].localeCompare(k[b], undefined, { numeric: true }) : k[a] - k[b]) || a - b).map(i => rows[i]);
}

// Rows whose text contains every non-empty filter ({ key: text }), case-insensitive.
export function filterRows(rows, filters) {
    const active = Object.entries(filters ?? {}).filter(([, v]) => String(v ?? '').trim() !== '');
    return rows.filter(r => active.every(([k, v]) => String(r[k] ?? '').toLowerCase().includes(String(v).trim().toLowerCase())));
}

// Expandable rows for <pk-table>: the toggle column and the detail rows. The table imports this on demand, only when `expandable` is set, so
// its own module stays inside the per-element budget. The table owns everything drawn here (shadow tree); the detail content is host-provided
// light DOM in a `detail-<rowId>` slot, and expanding only renders that slot, it never moves or edits the host's nodes.

import { sheetFor } from './element.js';

// The styles of what this module draws, adopted by the table's shadow root the first time a row is drawn (the table's own css knows nothing of them).
const STYLES = ('[data-expand]{inline-size:var(--space-8);text-align:center}[data-expand] button{all:unset;display:inline-block;padding:var(--space-1) var(--space-2);cursor:pointer}[data-expand] button:focus-visible{outline:var(--focus-ring)}@media (max-width:640px){[data-expand] button{display:inline-flex;align-items:center;min-block-size:var(--touch-target);min-inline-size:var(--touch-target)}:host([cards]) tr[data-detail] td{display:block;text-align:start}:host([cards]) td[data-expand]:empty{display:none}}');
let sheet;

// The expanded ids after one row opens or closes (ids are strings; the host may have given numbers).
export const toggled = (ids, id, open) => [...ids.map(String).filter(x => x !== id), ...(open ? [id] : [])];

// A row can expand when the host gave it detail content.
export const hasDetail = (table, id) => [...table.children].some(c => c.slot === `detail-${id}`);

// The header cell over the toggle column: empty, named for assistive technology.
export const head = h => h('th', { 'data-expand': true, scope: 'col' }, h('span', { class: 'sr' }, 'Details'));

// The row's toggle cell goes in after the checkbox cell; an expandable row is followed by its detail row (hidden while collapsed, so
// aria-controls always points at a real element). `span` is the column count the detail cell covers.
export function rows(table, tr, id, i, span, h) {
    const has = hasDetail(table, id), open = has && table.expanded.map(String).includes(id);
    const button = has && h('button', { type: 'button', 'data-expand-id': id, 'aria-expanded': String(open), 'aria-controls': `pk-d${i}`, 'aria-label': `Details for row ${id}` }, open ? '▾' : '▸');
    tr.insertBefore(h('td', { 'data-expand': true }, button || ''), tr.children[Number(table.selectable)] ?? null);
    return has ? [tr, h('tr', { id: `pk-d${i}`, 'data-detail': true, hidden: !open }, h('td', { colspan: span }, h('slot', { name: `detail-${id}` })))] : [tr];
}

// A click on a toggle: the element owns the change until the event, then the host owns it (STANDARDS: two-way values).
export function click(table, e) {
    const b = e.target.closest?.('button[data-expand-id]');
    if (!b) return false;
    const id = b.dataset.expandId, open = b.getAttribute('aria-expanded') !== 'true';
    table.expanded = toggled(table.expanded, id, open);
    table.$f = id;
    table.emit('pk-row-expand', { id, index: table.ids().indexOf(id), expanded: open });
    return true;
}

// After each render: adopt the styles, and put the keyboard focus back on the toggle that was used (the render replaced it).
export function after(table) {
    const sheets = table.shadowRoot.adoptedStyleSheets;
    sheet ??= sheetFor(STYLES);
    if (!sheets.includes(sheet)) table.shadowRoot.adoptedStyleSheets = [...sheets, sheet];
    if (table.$f === undefined) return;
    table.part('body').querySelector(`button[data-expand-id="${CSS.escape(table.$f)}"]`)?.focus();
    table.$f = undefined;
}

// The theme editor's pure logic (modules/theme-editor): which tokens to list, how an edit lands in the override dictionaries, which
// contrast pairs fail, what an element target gets as inline properties. No DOM; imports only the SDK's theme and colour maths.

import { tokenKind, nameProblem, valueProblem, parseOverrides } from './theme.js';
import { contrast, grade } from './colour.js';

export const KINDS = Object.freeze(['all', 'colour', 'font', 'size', 'shadow', 'layer', 'other']);
export const MIN_CONTRAST = 4.5;

// Text on background pairs the editor grades by default: body and muted text, links and accent, on the page and panel surfaces.
export const DEFAULT_PAIRS = Object.freeze([
    ['--color-text', '--color-bg'], ['--color-text', '--color-panel'], ['--color-muted', '--color-bg'],
    ['--color-muted', '--color-panel'], ['--color-link', '--color-panel'], ['--color-accent', '--color-panel'],
].map(p => Object.freeze(p)));

export const emptyOverrides = () => ({ shared: {}, dark: {}, light: {} });

// Every token name the stylesheet declares, sorted.
export const allTokenNames = tokens => [...new Set([...Object.keys(tokens.dark), ...Object.keys(tokens.light), ...Object.keys(tokens.root)])].sort();

// The value the stylesheet gives a token in a theme (that theme's block, else the theme-independent one, else the dark block).
export const baseValue = (tokens, theme, name) => tokens[theme]?.[name] ?? tokens.root[name] ?? tokens.dark[name] ?? '';

export const isChanged = (overrides, theme, name) => name in overrides[theme] || name in overrides.shared;

// The value in force: this theme's override, else the shared one, else the stylesheet's.
export const effectiveValue = (overrides, tokens, theme, name) => overrides[theme][name] ?? overrides.shared[name] ?? baseValue(tokens, theme, name);

// The tokens to list for a kind and a name filter (substring, any case).
export function visibleTokens(tokens, theme, { kind = 'all', filter = '' } = {}) {
    const f = String(filter).trim().toLowerCase();
    return allTokenNames(tokens).filter(n => (kind === 'all' || tokenKind(n, baseValue(tokens, theme, n)) === kind) && n.includes(f));
}

// A copy of the overrides with one edit applied. scope 'both' writes the shared dictionary (and clears the theme's own entry so the
// shared value shows); 'theme' writes the current theme's. An empty value, or the stylesheet's own value, removes the entry.
export function withEdit(overrides, { theme, scope = 'theme', name, value, base }) {
    const next = { shared: { ...overrides.shared }, dark: { ...overrides.dark }, light: { ...overrides.light } };
    const dict = scope === 'both' ? next.shared : next[theme];
    if (value === '' || value === base) delete dict[name]; else dict[name] = value;
    if (scope === 'both') delete next[theme][name];
    return next;
}

// A copy with one token cleared everywhere.
export function withoutToken(overrides, name) {
    const next = { shared: { ...overrides.shared }, dark: { ...overrides.dark }, light: { ...overrides.light } };
    delete next.shared[name]; delete next.dark[name]; delete next.light[name];
    return next;
}

export const overrideCount = o => Object.keys(o.shared).length + Object.keys(o.dark).length + Object.keys(o.light).length;

// Contrast of each pair. read(name) gives the token's computed value; a value that is not a literal colour (var(), color-mix()) has ratio null.
export function evaluatePairs(pairs, read, min = MIN_CONTRAST) {
    return pairs.map(([fg, bg]) => {
        const ratio = contrast(read(fg), read(bg));
        return { fg, bg, ratio, bad: ratio !== null && ratio < min, grade: grade(ratio, { aaa: 7, aa: min }) };
    });
}

// What an element target receives for a theme: the shared overrides under the theme's own, only names and values the SDK's rules accept.
export function inlineEntries(overrides, theme) {
    const out = {};
    for (const [name, value] of Object.entries({ ...overrides.shared, ...overrides[theme] })) if (!nameProblem(name) && !valueProblem(value)) out[name] = String(value).trim();
    return out;
}

// Reads text the user pasted into the import box. Returns { overrides } when it is a JSON { shared, dark, light } or an override CSS block that
// holds at least one usable token, or { error } (a sentence for the status line) otherwise, so the caller keeps the current overrides. JSON
// with a section key and nothing in it ({"shared":{}}) is a valid way to clear; text that is neither JSON nor CSS, or whose tokens the SDK's
// rules all reject, is an error and never clears anything.
export function readImport(text) {
    const t = String(text ?? '').trim();
    if (!t) return { error: 'Nothing to import: paste JSON or an override CSS block first.' };
    const json = t.startsWith('{') && !t.includes('[data-theme') && !t.includes(':root');
    const parsed = parseOverrides(t);
    if (!parsed) return { error: 'Not JSON and not an override CSS block.' };
    const count = overrideCount(parsed);
    if (json) {
        const raw = JSON.parse(t);
        const sections = ['shared', 'dark', 'light'].filter(k => raw !== null && typeof raw === 'object' && k in raw);
        if (!sections.length) return { error: 'The JSON has none of "shared", "dark" or "light".' };
        const given = sections.reduce((n, k) => n + (raw[k] !== null && typeof raw[k] === 'object' ? Object.keys(raw[k]).length : 0), 0);
        if (given > 0 && count === 0) return { error: 'None of the tokens in the JSON are allowed (a name must start with -- and a value must be safe).' };
        return { overrides: parsed };
    }
    if (count === 0) return { error: 'Not JSON and not an override CSS block: no token declarations were found.' };
    return { overrides: parsed };
}

import { parseColour } from './colour.js';

// Plainkit theme: switch light/dark, read the tokens a stylesheet declares, and build or parse the override block.
// The override rules mirror the server-side PkThemeOverrides helper exactly: same name pattern, same value whitelist, same output.
// Framework-free; its only import is the SDK's colour maths.

export const MAX_VALUE_LENGTH = 200;
const NAME = /^--[a-z][a-z0-9]*(-[a-z0-9]+)*$/;
const VALUE = /^[A-Za-z0-9#%.,\s()\-+/]+$/;

export function setTheme(element, name) {
    element.setAttribute('data-theme', name === 'light' ? 'light' : 'dark');
    return element.getAttribute('data-theme');
}

export const currentTheme = element => (element.getAttribute('data-theme') === 'light' ? 'light' : 'dark');

export function toggleTheme(element) {
    return setTheme(element, currentTheme(element) === 'dark' ? 'light' : 'dark');
}

// Why a token name is unusable, or null.
export function nameProblem(name) {
    return name.length < 3 || name.length > 64 || !NAME.test(name) ? 'not a lowercase custom property name (--like-this)' : null;
}

// Why a value is unusable, or null.
export function valueProblem(value) {
    const v = String(value ?? '').trim();
    if (v.length === 0) return 'empty';
    if (v.length > MAX_VALUE_LENGTH) return `longer than ${MAX_VALUE_LENGTH} characters`;
    if (!VALUE.test(v)) return 'contains a character outside letters, digits, # % . , ( ) - + / and spaces';
    if (v.includes('/*') || v.includes('*/')) return 'contains a comment marker';
    const lower = v.toLowerCase();
    if (lower.includes('url(') || lower.includes('expression') || lower.includes('import')) return 'url(), expression and import are not allowed';
    let depth = 0;
    for (const c of v) {
        if (c === '(') depth++;
        else if (c === ')' && --depth < 0) return 'unbalanced parentheses';
    }
    return depth === 0 ? null : 'unbalanced parentheses';
}

function clean(source, rejected) {
    const ok = {};
    for (const [name, value] of Object.entries(source ?? {}).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
        const problem = nameProblem(name) ?? valueProblem(value);
        if (problem) rejected.push(`${name}: ${problem}`);
        else ok[name] = String(value).trim();
    }
    return ok;
}

function block(selector, entries) {
    const names = Object.keys(entries).sort();
    if (names.length === 0) return '';
    return `${selector} {\n${names.map(n => `    ${n}: ${entries[n]};`).join('\n')}\n}\n`;
}

// { css, rejected } from { shared, dark, light } dictionaries of token -> value; a theme entry beats a shared one.
export function buildOverrides({ shared = {}, dark = {}, light = {} } = {}) {
    const rejected = [];
    const s = clean(shared, rejected);
    const d = { ...s, ...clean(dark, rejected) };
    const l = { ...s, ...clean(light, rejected) };
    return { css: block(':root,\n[data-theme="dark"]', d) + block('[data-theme="light"]', l), rejected };
}

export const MAX_OVERRIDES = 500;

// Copies only well-formed token overrides out of untrusted input (JSON import, localStorage): own string values under valid
// "--token" names, at most MAX_OVERRIDES. Keys such as __proto__, constructor and prototype can never pass the name check (a token
// name starts with "--"), so no merge of the result can pollute a prototype. Anything else is dropped, not repaired.
export function sanitizeDict(source) {
    const out = {};
    if (source === null || typeof source !== 'object' || Array.isArray(source)) return out;
    let n = 0;
    for (const name of Object.keys(source)) {
        if (n >= MAX_OVERRIDES) break;
        const value = source[name];
        if (typeof value !== 'string' || nameProblem(name) !== null || valueProblem(value) !== null) continue;
        out[name] = value.trim();
        n++;
    }
    return out;
}

export function sanitizeOverrides(input) {
    const o = input !== null && typeof input === 'object' ? input : {};
    return { shared: sanitizeDict(o.shared), dark: sanitizeDict(o.dark), light: sanitizeDict(o.light) };
}

// Reads back what buildOverrides emits, or the JSON form { shared, dark, light }. Returns { shared, dark, light } or null.
export function parseOverrides(text) {
    const t = String(text ?? '').trim();
    if (t.startsWith('{') && !t.includes('[data-theme') && !t.includes(':root')) {
        try {
            const o = JSON.parse(t);
            return sanitizeOverrides(o);
        } catch { return null; }
    }
    const result = { shared: {}, dark: {}, light: {} };
    for (const m of t.matchAll(/([^{}]+)\{([^}]*)\}/g)) {
        const target = m[1].includes('light') ? result.light : m[1].includes('dark') || m[1].includes(':root') ? result.dark : null;
        if (!target) continue;
        for (const d of m[2].matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) target[d[1]] = d[2].trim();
    }
    return sanitizeOverrides(result);
}

// Tokens a stylesheet declares, grouped by the block that declares them: { dark, light, root } of name -> value.
// ":root, [data-theme=dark]" is the dark block, "[data-theme=light]" the light one, a bare ":root" is theme-independent.
export function parseTokenBlocks(cssText) {
    const css = String(cssText).replace(/\/\*[\s\S]*?\*\//g, '');
    const out = { dark: {}, light: {}, root: {} };
    for (const m of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
        const sel = m[1].trim().replace(/\s+/g, ' ');
        const which = /^\[data-theme="light"\]$/.test(sel) ? 'light'
            : /^:root, \[data-theme="dark"\]$/.test(sel) ? 'dark'
            : sel === ':root' ? 'root' : null;
        if (!which) continue;
        for (const d of m[2].matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) out[which][d[1]] = d[2].trim();
    }
    return out;
}

// Which editor a token belongs in: colour, font, size, shadow, layer or other.
export function tokenKind(name, value) {
    if (/^--z-/.test(name)) return 'layer';
    if (/shadow/.test(name)) return 'shadow';
    if (/^--font-/.test(name)) return 'font';
    if (/^--(space|text|radius|touch|app)-|-(size|width|height|gap)$/.test(name)) return 'size';
    if (/^#|^rgba?\(|^hsla?\(/i.test(String(value).trim()) || /^--color-/.test(name) || /-(bg|fg|border|hover|accent)(-\d+)?$/.test(name)) return 'colour';
    return 'other';
}

// "1.5rem" -> { number: 1.5, unit: "rem" } for a plain length; null for anything else (calc(), var(), lists).
export function splitLength(value) {
    const m = /^\s*(-?\d*\.?\d+)(px|rem|em|%|vh|vw|ms|s)?\s*$/.exec(String(value));
    return m ? { number: parseFloat(m[1]), unit: m[2] ?? '' } : null;
}

// A solid colour as #rrggbb for <input type="color">, or null when it has alpha or is not a literal colour.
export function colourToHex(value) {
    const c = parseColour(value);
    if (!c || c.a < 1) return null;
    const h = n => Math.round(n).toString(16).padStart(2, '0');
    return '#' + h(c.r) + h(c.g) + h(c.b);
}

/* The code explorer's own styles: loaded by element.js next to the page layer (tokens, base), tokens only. The panes, tabs, tree, inputs,
   buttons and badges are pk-* elements; what is left here is the host, the code viewer (cv-*, tk-*), the outline (co-*) and the search
   results (csr-*), none of which an element covers, plus the small ce-* layout classes around the elements. */

/* The <pk-code-explorer> element: a flex column of a set height so the workspace inside can fill it and scroll its panes. */
pk-code-explorer {
    --ce-mono: ui-monospace, "Cascadia Code", Consolas, monospace;
    display: flex;
    flex-direction: column;
    height: var(--pk-code-explorer-height, 32rem);
    min-height: 0;
    min-inline-size: 0;
    background: var(--color-bg);
    color: var(--color-text);
}
pk-code-explorer [hidden] { display: none !important; }
pk-code-explorer pk-workspace { --pk-workspace-pad: 0; }

/* Nav pane: two search boxes, their buttons and the file tree. */
.ce-nav { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-3); min-inline-size: 0; }
.ce-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.ce-name { min-inline-size: 0; overflow-wrap: anywhere; }
.ce-row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); min-inline-size: 0; }
.ce-folder { font-weight: 600; }
pk-code-explorer pk-tree-item::part(label) { flex: 1 1 auto; min-inline-size: 0; }
.ce-muted { color: var(--color-muted); }
.ce-error { margin: var(--space-1); color: var(--field-error); }

/* Main pane: the tab strip of open files over the viewer. */
.ce-main { display: flex; flex-direction: column; block-size: 100%; min-block-size: 0; min-inline-size: 0; }
.ce-main pk-tabs { flex: none; padding-inline: var(--space-2); border-bottom: 1px solid var(--color-border); }
.ce-main pk-tabs::part(list) { margin-bottom: 0; border-bottom: 0; }
.ce-pane { display: flex; flex-direction: column; flex: 1 1 auto; min-block-size: 0; min-inline-size: 0; padding: var(--space-3); }
.ce-pane pk-empty-state { margin: auto; }

/* Aside pane: the outline or the usages of a word. */
.ce-aside { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-3); min-inline-size: 0; }
.ce-aside-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
.ce-aside-head h2 { margin: 0; font-size: var(--text-read); }

/* Outline. */
.co { list-style: none; margin: 0; padding: 0; }
.co-item {
    display: flex; align-items: baseline; gap: var(--space-2); width: 100%; padding: var(--space-1) var(--space-2); border: 0; background: none;
    color: inherit; font: inherit; font-size: var(--text-read); text-align: left; cursor: pointer; border-radius: var(--radius-sm);
}
.co-item:hover { background: var(--color-surface-alt); }
.co-item:focus-visible { outline: var(--focus-ring); outline-offset: -2px; }
.co-kind { flex: none; min-width: 4.5em; font-size: var(--text-meta); text-transform: uppercase; letter-spacing: 0.03em; color: var(--color-accent); }
.co-name { font-family: var(--ce-mono); overflow-wrap: anywhere; }
.co-line { margin-left: auto; font-size: var(--text-meta); color: var(--color-muted); }
.co-d1 { padding-left: var(--space-5); }
.co-d2 { padding-left: var(--space-8); }
.co-d3 { padding-left: var(--space-12); }

/* Search results, also used for usages. */
.csr { min-width: 0; }
.csr-group { border: 1px solid var(--color-border); border-radius: var(--radius-md); margin-bottom: var(--space-2); overflow: hidden; }
.csr-title { padding: var(--space-1) var(--space-2); font-family: var(--ce-mono); font-size: var(--text-read); background: var(--color-surface-alt); overflow-wrap: anywhere; }
.csr-hit {
    display: flex; gap: var(--space-2); width: 100%; text-align: left; cursor: pointer;
    background: none; border: 0; border-top: 1px solid var(--color-border);
    padding: var(--space-1) var(--space-2); color: inherit; font: inherit;
}
.csr-hit:hover { background: var(--color-surface-alt); }
.csr-hit:focus-visible { outline: var(--focus-ring); outline-offset: -2px; }
.csr-no { flex: none; min-width: 3em; text-align: right; color: var(--color-muted); font-family: var(--ce-mono); font-size: var(--text-meta); }
.csr-text { font-family: var(--ce-mono); font-size: var(--text-meta); white-space: pre-wrap; overflow-wrap: anywhere; min-width: 0; }
.csr-text mark { background: var(--csr-mark-bg); color: inherit; padding: 0; }

/* Code viewer: a code-editor pane. The palette is local to the viewer (dark by default, like the app; light when data-theme="light")
   so token colours keep their contrast on the editor background rather than on whatever surface the page uses. */
.cv {
    border: 1px solid var(--cv-border); border-radius: var(--radius-md); background: var(--cv-bg); color: var(--cv-text);
    min-width: 0; overflow: hidden; box-shadow: var(--cv-shadow);
}
.cv-title {
    display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1) var(--space-3); padding: var(--space-2) var(--space-3);
    background: var(--cv-bar); border-bottom: 1px solid var(--cv-border); font-size: var(--text-read);
}
.cv-name { font-family: var(--ce-mono); font-weight: 600; overflow-wrap: anywhere; flex: 1 1 12rem; }
.cv-meta { display: inline-flex; gap: var(--space-3); color: var(--cv-muted); font-size: var(--text-read); }
.cv-lang { padding: 0 var(--space-2); border: 1px solid var(--cv-border); border-radius: var(--radius-pill); }
.cv-count { white-space: nowrap; }
.cv-notice { padding: var(--space-1) var(--space-3); font-size: var(--text-read); color: var(--cv-muted); background: var(--cv-bar); border-bottom: 1px solid var(--cv-border); }

.cv-scroll { position: relative; max-height: 70vh; overflow: auto; font-family: var(--ce-mono); font-size: var(--text-read); line-height: 1.5; tab-size: 4; }
.cv-scroll:focus-visible { outline: var(--focus-ring); outline-offset: -2px; }

.cv-row { display: flex; min-width: max-content; border-left: 3px solid transparent; }
.cv-row:hover { background: var(--cv-hover); }
.cv-row--focus { background: var(--cv-focus); border-left-color: var(--cv-focus-edge); }

.cv-no {
    position: sticky; left: 0; flex: none; min-width: 3.5em; padding: 0 0.7em; text-align: right;
    color: var(--cv-muted); background: var(--cv-gutter); border-right: 1px solid var(--cv-border); user-select: none;
}
.cv-row--focus .cv-no { color: var(--cv-text); font-weight: 600; }

.cv-code { white-space: pre; padding: 0 1em; cursor: text; }

.cv-match { background: var(--cv-match); border-radius: var(--radius-xs); }
.cv-word { background: var(--cv-word); border-radius: var(--radius-xs); box-shadow: 0 0 0 1px var(--cv-word); }

.tk-keyword { color: var(--cv-keyword); }
.tk-string { color: var(--cv-string); }
.tk-comment { color: var(--cv-comment); font-style: italic; }
.tk-number { color: var(--cv-number); }
.tk-type { color: var(--cv-type); }
.tk-tag { color: var(--cv-tag); }
.tk-attribute { color: var(--cv-attr); }
.tk-directive { color: var(--cv-directive); }
.tk-key { color: var(--cv-key); }

.cv--fill { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.cv--fill .cv-scroll { flex: 1; min-height: 0; max-height: none; }

@media (max-width: 640px) {
    .cv-scroll { font-size: var(--text-meta); max-height: 60vh; }
    .cv--fill .cv-scroll { max-height: none; }
    .cv-no { min-width: 2.8em; padding: 0 0.4em; }
}

/* Parts of the outline and the trail that the explorer itself does not draw but other pages still use. */
.co-active { background: var(--color-surface-alt); box-shadow: inset 3px 0 0 var(--color-accent); }
.co-detail { font-size: var(--text-meta); }

.cnb { display: flex; align-items: center; gap: var(--space-1); min-width: 0; margin-bottom: var(--space-1); }
.cnb-trail { display: flex; flex-wrap: wrap; align-items: center; gap: 0 var(--space-1); list-style: none; margin: 0 0 0 var(--space-1); padding: 0; min-width: 0; font-size: var(--text-read); }
.cnb-trail li { display: inline-flex; align-items: center; gap: var(--space-1); min-width: 0; }
.cnb-folder { border: 0; background: none; padding: 0; font: inherit; color: var(--color-link, var(--color-accent)); cursor: pointer; }
.cnb-folder:hover { text-decoration: underline; }
.cnb-file { font-weight: 600; overflow-wrap: anywhere; }

// The code explorer as a module: mountCodeExplorer(container, options) puts a file tree, tabs, a code viewer, search and an outline in
// `container`, fed by a snapshot (see tools/snapshot.mjs for producing one and modules/code-explorer/providers.js for the format).
//
//   const explorer = await mountCodeExplorer(el, { snapshot: 'snapshot.json', file: 'src/app.js', search: 'TODO', theme: 'light', height: '32rem' });
//
// Options: snapshot (a URL of a snapshot JSON, or the parsed object), provider (a ready provider instead of a snapshot), file (open
// this path, `line` picks the row), search (run this query), theme ('dark' | 'light'), height (any CSS length, or 'fill'; default 32rem).
// Returns { element, openFile(path, { line }), search(query), destroy() }. The document must be able to load the SDK stylesheets; any
// that are missing are added (the explorer's own stylesheet is added by the element).

import './element.js';
import { SnapshotProvider } from './providers.js';
import { ensureStyles, styleUrls, loadJson } from '../../js/mount-support.js';
import { createLogger } from '../../js/log.js';

const log = createLogger('code-explorer');

const STYLES = ['../../plainkit.css'];

export async function mountCodeExplorer(container, options = {}) {
    const { snapshot, provider, file, line, search, theme, height } = options;
    log.debug('mounted', { module: 'code-explorer', options: Object.keys(options) });
    if (!snapshot && !provider) throw new Error('mountCodeExplorer needs a snapshot (a URL or an object) or a provider');
    await ensureStyles(styleUrls(STYLES, import.meta.url), container.ownerDocument);
    const source = provider ?? new SnapshotProvider(await loadJson(snapshot));
    const element = container.ownerDocument.createElement('pk-code-explorer');
    element.setAttribute('height', height ?? '32rem');
    if (theme) element.setAttribute('theme', theme);
    if (file) element.setAttribute('initial', file);
    if (file && line) element.setAttribute('initial-line', String(line));
    if (search) element.setAttribute('search', search);
    element.provider = source;
    container.replaceChildren(element);
    return { element, openFile: (path, o) => element.openFile(path, o), search: q => element.search(q), destroy: () => element.remove() };
}

// <pk-code-explorer> custom element: a file tree, a tab strip of open files, a line-numbered code viewer and a docked
// outline / usages inspector, fed by one provider (see providers.js). Light DOM: the panes, tabs, tree, inputs, buttons and badges
// are pk-* elements (loaded on demand); code-explorer.css, loaded here, styles the viewer, outline and search results.
//
//   <pk-code-explorer source="snapshot" src="snapshot.json"></pk-code-explorer>
//   <pk-code-explorer source="api" src="./api/code" theme="light" height="40rem"></pk-code-explorer>
//   <pk-code-explorer source="feed" src="./api/code/events" base="./api/code" feed-interval="5000"></pk-code-explorer>
//
// Attributes (all optional except source/src unless a provider is assigned): source, src, base (feed only), theme
// (light|dark, sets data-theme), height (any CSS length, or "fill"; default 32rem), initial (a path to open first; initial-line focuses a row),
// search (a query to run once the files are listed), max-lines (rows drawn per file, default 2000), feed-interval (ms; polls instead of SSE). Property `provider` accepts
// a ready provider object. Events: "pk-code-explorer-open" (detail { path }), "pk-code-explorer-error" (detail { error }).
// Phone: below 640px pk-workspace shows one pane at a time (Files, Code, Inspector) with its own tab strip.

import { createProvider, wordSpans, matcherFor } from './providers.js';
import { buildSegments, tokenize, wordAt, languageOf } from './tokenize.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { createLogger } from '../../js/log.js';
const log = createLogger('code-explorer');

const CSS = ['./code-explorer.css'];
const NAV = '::nav';
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// The one place markup is written into the document: every value in it went through esc(), tokens are wrapped in fixed spans.
const fill = (el, markup) => { el.innerHTML = markup; };

// Folder tree from flat paths: { name, path, children: Map, file? }.
export function buildTree(files, filter = '') {
    const root = { name: '', path: '', children: new Map(), lines: 0, count: 0 };
    const needle = filter.trim().toLowerCase();
    for (const f of files) {
        if (needle && !f.path.toLowerCase().includes(needle)) continue;
        let node = root;
        const parts = f.path.split('/');
        parts.forEach((part, i) => {
            if (!node.children.has(part)) node.children.set(part, { name: part, path: parts.slice(0, i + 1).join('/'), children: new Map(), lines: 0, count: 0 });
            node = node.children.get(part);
            node.lines += f.lines ?? 0; node.count++;
            if (i === parts.length - 1) node.file = f;
        });
    }
    return root;
}

const Base = globalThis.HTMLElement ?? class {};

export class CodeExplorerElement extends Base {
    static get observedAttributes() { return ['theme', 'height']; }

    #provider = null;
    #files = [];
    #open = [];
    #active = NAV;
    #docs = new Map();
    #focus = null;
    #word = '';
    #filter = '';
    #search = null;
    #inspector = null;
    #folders = new Set();
    #nodes = new Map();
    #ready = Promise.resolve();
    #unsubscribe = null;

    set provider(p) { this.#provider = p; if (this.isConnected) this.#start(); }
    get provider() { return this.#provider; }

    connectedCallback() {
        this.#applyAttributes();
        ensureStyles(styleUrls(CSS, import.meta.url), this.ownerDocument);
        this.#build();
        this.#start();
    }

    disconnectedCallback() { this.#unsubscribe?.(); this.#unsubscribe = null; }

    attributeChangedCallback() { if (this.isConnected) this.#applyAttributes(); }

    #applyAttributes() {
        const theme = this.getAttribute('theme');
        if (theme) this.setAttribute('data-theme', theme === 'light' ? 'light' : 'dark');
        const h = this.getAttribute('height');
        if (h) this.style.setProperty('--pk-code-explorer-height', h === 'fill' ? '100%' : h);
    }

    // Load the modules of any pk-* element that was just written and is not defined yet (a no-op once they all are).
    #upgrade() { loadElements(this); }

    #build() {
        fill(this, `
<pk-workspace fill active-pane="nav" nav-label="Files" main-label="Code" aside-label="Inspector" data-ce-root>
  <div slot="nav" class="ce-nav">
    <pk-input type="search" label="Filter files" placeholder="Filter files by path" data-ce-filter></pk-input>
    <pk-input type="search" label="Search code" placeholder="Search code: text or /regex/" data-ce-query data-ce-searchbox></pk-input>
    <div class="ce-actions">
      <pk-button size="mini" data-ce-search hidden>Search</pk-button>
      <pk-button size="mini" variant="ghost" data-ce-clear hidden>Back to files</pk-button>
    </div>
    <div data-ce-tree></div>
  </div>
  <div class="ce-main">
    <pk-tabs scroll none-active data-ce-tabs></pk-tabs>
    <div class="ce-pane" data-ce-pane></div>
  </div>
  <div slot="aside" class="ce-aside" data-ce-inspector>
    <div class="ce-aside-head"><h2 data-ce-inspector-title>Outline</h2><pk-button size="mini" variant="ghost" icon label="Close inspector" data-ce-inspector-close>&#10005;</pk-button></div>
    <div data-ce-inspector-body></div>
  </div>
</pk-workspace>`);
        const $ = s => this.querySelector(s);
        $('[data-ce-filter]').addEventListener('input', e => { this.#filter = e.target.value; this.#renderTree(); });
        const runSearch = () => this.#runSearch($('[data-ce-query]').value);
        $('[data-ce-query]').addEventListener('keydown', e => { if (e.key === 'Enter') runSearch(); });
        $('[data-ce-search]').addEventListener('click', runSearch);
        $('[data-ce-clear]').addEventListener('click', () => { this.#search = null; this.#renderTree(); });
        $('[data-ce-inspector-close]').addEventListener('click', () => { this.#inspector = null; this.#renderInspector(); this.#showPane('main'); });
        const tree = $('[data-ce-tree]');
        tree.addEventListener('click', e => this.#onHitClick(e));
        tree.addEventListener('pk-select', e => this.#onTreeSelect(e));
        tree.addEventListener('pk-toggle', e => this.#onTreeToggle(e));
        const tabs = $('[data-ce-tabs]');
        tabs.addEventListener('pk-tab-change', e => { if (e.detail.fallback) return; this.#active = e.detail.value; this.#focus = null; this.#renderPane(); this.#syncTree(); });
        tabs.addEventListener('pk-tab-close', e => this.#closeTab(e.detail.value));
        tabs.addEventListener('keydown', e => { const tab = e.target.closest?.('pk-tab'); if (tab && e.key === 'Delete') this.#closeTab(tab.value, true); });
        $('[data-ce-pane]').addEventListener('click', e => this.#onPaneClick(e));
        $('[data-ce-inspector-body]').addEventListener('click', e => this.#onInspectorClick(e));
        this.addEventListener('keydown', e => { if (e.key === 'Escape' && this.#inspector) { this.#inspector = null; this.#renderInspector(); this.#showPane('main'); } });
        // Load every element the explorer writes before the first tree is drawn: a pk-tree that defines before its items would
        // update against items that are not upgraded yet.
        const scratch = this.ownerDocument.createElement('div');
        fill(scratch, '<pk-tree><pk-tree-item></pk-tree-item></pk-tree><pk-badge></pk-badge><pk-tab></pk-tab><pk-empty-state></pk-empty-state>');
        this.#ready = Promise.all([loadElements(scratch), loadElements(this)]);
    }

    async #start() {
        this.#unsubscribe?.(); this.#unsubscribe = null;
        try {
            await this.#ready;
            const src = this.getAttribute('src');
            const source = this.getAttribute('source');
            this.#provider ??= await createProvider({ source, src, base: this.getAttribute('base') ?? undefined, interval: Number(this.getAttribute('feed-interval')) || 0 });
            const caps = this.#provider.capabilities ?? {};
            this.querySelector('[data-ce-searchbox]').hidden = !caps.search;
            this.querySelector('[data-ce-search]').hidden = !caps.search;
            await this.#reload();
            if (this.isConnected && caps.live && this.#provider.subscribe) { this.#unsubscribe?.(); this.#unsubscribe = this.#provider.subscribe(ev => this.#onFeed(ev)); }
            const initial = this.getAttribute('initial');
            if (initial) await this.openFile(initial, { line: Number(this.getAttribute('initial-line')) || undefined });
            const query = this.getAttribute('search');
            if (query) await this.search(query);
        } catch (error) {
            log.error('the code explorer could not start', error);
            fill(this.querySelector('[data-ce-tree]'), `<p class="ce-error" role="alert">${esc(error.message)}</p>`);
            this.dispatchEvent(new CustomEvent('pk-code-explorer-error', { detail: { error } }));
        }
    }

    async #reload() {
        this.#files = await this.#provider.listFiles();
        this.#renderTree();
    }

    async #onFeed(ev) {
        if (ev?.path) this.#docs.delete(ev.path);
        await this.#reload();
        if (ev?.path && ev.path === this.#active) await this.openFile(ev.path, { line: this.#focus ?? undefined });
    }

    // The pane pk-workspace shows on a phone (on a wider screen every pane shows).
    #showPane(pane) { this.querySelector('[data-ce-root]').setAttribute('active-pane', pane); }

    // ---- nav -------------------------------------------------------------
    #renderTree() {
        const host = this.querySelector('[data-ce-tree]');
        this.querySelector('[data-ce-clear]').hidden = !this.#search;
        if (this.#search) { fill(host, this.#searchHtml()); return; }
        const root = buildTree(this.#files, this.#filter);
        this.#nodes = new Map();
        const filtering = this.#filter.trim() !== '';
        if (!root.children.size) { fill(host, '<p class="ce-muted ce-empty">No files.</p>'); return; }
        // The tree is connected empty and its items added after: a pk-tree that connects with items not yet upgraded updates against them too early.
        fill(host, `<pk-tree label="Files" value="${esc(this.#activeFile())}"></pk-tree>`);
        host.firstElementChild.append(this.#fragment(this.#treeHtml(root, filtering)));
        this.#upgrade();
    }

    // A folder's items. A folder that is not open yet holds one hidden stub item, which makes it expandable; its real children are
    // written when it opens (#onTreeToggle), so a snapshot of hundreds of files costs only the folders on screen.
    #treeHtml(node, filtering) {
        const sorted = [...node.children.values()].sort((a, b) => (!!a.file - !!b.file) || a.name.localeCompare(b.name));
        return sorted.map(n => {
            if (n.file && !n.children.size) {
                return `<pk-tree-item data-file value="${esc(n.path)}" label="${esc(n.name)}"><span slot="label" class="ce-row"><span class="ce-name">${esc(n.name)}</span>${n.file.lines != null ? `<pk-badge variant="muted" max="999999" count="${n.file.lines}"></pk-badge>` : ''}</span></pk-tree-item>`;
            }
            this.#nodes.set(n.path, n);
            const open = filtering || this.#folders.has(n.path);
            return `<pk-tree-item value="${esc(n.path)}" label="${esc(n.name)}"${open ? ' expanded' : ''}><span slot="label" class="ce-row"><span class="ce-name ce-folder">${esc(n.name)}</span><pk-badge variant="muted" max="999999" count="${n.count}"></pk-badge></span>${open ? this.#treeHtml(n, filtering) : '<pk-tree-item data-ce-stub hidden label="."></pk-tree-item>'}</pk-tree-item>`;
        }).join('');
    }

    #fragment(markup) {
        const scratch = this.ownerDocument.createElement('template');
        fill(scratch, markup);
        return scratch.content;
    }

    #activeFile() { return this.#active === NAV ? '' : this.#active; }

    // The tree shows the open file as selected.
    #syncTree() { this.querySelector('pk-tree')?.setAttribute('value', this.#activeFile()); }

    #onTreeSelect(e) {
        const item = e.target.closest?.('pk-tree-item');
        if (!item) return;
        if (item.hasAttribute('data-file')) { this.openFile(e.detail.id); return; }
        item.setExpanded(!item.expanded);
        this.#syncTree();
    }

    #onTreeToggle(e) {
        const item = e.target.closest?.('pk-tree-item');
        if (!item || item.hasAttribute('data-file')) return;
        const path = e.detail.id;
        if (e.detail.expanded) this.#folders.add(path); else this.#folders.delete(path);
        const stub = item.querySelector(':scope > [data-ce-stub]');
        const node = this.#nodes.get(path);
        if (stub && node) {
            stub.replaceWith(this.#fragment(this.#treeHtml(node, false)));
            this.querySelector('pk-tree').requestUpdate?.();
            this.#upgrade();
        }
    }

    // Run a code search as if it were typed into the box; a no-op when the provider cannot search.
    async search(query) {
        const box = this.querySelector('[data-ce-query]');
        if (box) box.value = query;
        await this.#runSearch(query);
    }

    async #runSearch(query) {
        if (!query.trim() || !this.#provider.search) return;
        try { this.#search = { query, groups: await this.#provider.search(query) }; } catch (e) { log.warn('the search failed', e); this.#search = { query, groups: [], error: e.message }; }
        this.#renderTree();
    }

    #searchHtml() {
        const s = this.#search;
        if (s.error) return `<p class="ce-error" role="alert">${esc(s.error)}</p>`;
        if (!s.groups.length) return '<p class="ce-muted">No matches.</p>';
        const match = matcherFor(s.query);
        return `<div class="csr">${s.groups.map(g => `<div class="csr-group"><div class="csr-title">${esc(g.path)} <span class="ce-muted">(${g.hits.length})</span></div>${g.hits.map(h => {
            const t = h.text.trim(); const shift = h.text.length - h.text.trimStart().length;
            const spans = (h.spans ?? match(h.text)).map(x => ({ start: x.start - shift, length: x.length }));
            return `<button type="button" class="csr-hit" data-path="${esc(g.path)}" data-line="${h.line}"><span class="csr-no">${h.line}</span><span class="csr-text">${buildSegments(t, [], spans, []).map(x => x.match ? `<mark>${esc(x.text)}</mark>` : esc(x.text)).join('')}</span></button>`;
        }).join('')}</div>`).join('')}</div>`;
    }

    // A search hit in the nav pane opens its file at that line.
    #onHitClick(e) {
        const hit = e.target.closest?.('.csr-hit');
        if (hit) this.openFile(hit.dataset.path, { line: hit.dataset.line ? Number(hit.dataset.line) : undefined });
    }

    // ---- tabs ------------------------------------------------------------
    #renderTabs() {
        const strip = this.querySelector('[data-ce-tabs]');
        fill(strip, this.#open.map(p => `<pk-tab value="${esc(p)}" closable title="${esc(p)}">${esc(p.split('/').pop())}</pk-tab>`).join(''));
        strip.toggleAttribute('none-active', !this.#open.length);
        strip.setAttribute('value', this.#activeFile());
        this.#upgrade();
    }

    #closeTab(path, refocus = false) {
        const i = this.#open.indexOf(path);
        if (i < 0) return;
        this.#open = this.#open.filter(p => p !== path);
        if (this.#active === path) this.#active = this.#open[Math.min(i, this.#open.length - 1)] ?? NAV;
        this.#renderTabs(); this.#renderPane(); this.#syncTree();
        if (this.#active === NAV) this.#showPane('nav');
        if (refocus) requestAnimationFrame(() => this.querySelector('pk-tab[selected]')?.focus());
    }

    async openFile(path, { line } = {}) {
        try {
            if (!this.#docs.has(path)) {
                const doc = await this.#provider.readFile(path);
                const language = doc.language ?? languageOf(path);
                this.#docs.set(path, { ...doc, language, tokens: tokenize(doc.lines, language) });
            }
        } catch (error) {
            log.warn(`could not open ${path}`, error);
            this.dispatchEvent(new CustomEvent('pk-code-explorer-error', { detail: { error } }));
            return;
        }
        const isNew = !this.#open.includes(path);
        if (isNew) this.#open.push(path);
        this.#active = path; this.#focus = line ?? null; this.#word = '';
        if (isNew) this.#renderTabs(); else this.querySelector('[data-ce-tabs]').setAttribute('value', path);
        this.#renderPane(); this.#syncTree(); this.#showPane('main');
        if (this.#inspector?.kind === 'outline') this.#showOutline(false);
        this.dispatchEvent(new CustomEvent('pk-code-explorer-open', { detail: { path } }));
    }

    // ---- viewer ----------------------------------------------------------
    #renderPane() {
        const pane = this.querySelector('[data-ce-pane]');
        const doc = this.#docs.get(this.#active);
        if (!doc) { fill(pane, '<pk-empty-state heading="No file open" description="Pick a file from the tree."></pk-empty-state>'); this.#upgrade(); this.#renderInspector(); return; }
        const max = Number(this.getAttribute('max-lines')) || 2000;
        const total = doc.lines.length;
        const centre = this.#focus ?? 1;
        const start = total <= max ? 1 : Math.max(1, Math.min(centre - Math.floor(max / 2), total - max + 1));
        const end = Math.min(total, start + max - 1);
        const caps = this.#provider.capabilities ?? {};
        const rows = [];
        for (let n = start; n <= end; n++) {
            const text = doc.lines[n - 1];
            const segs = buildSegments(text, doc.tokens[n - 1] ?? [], [], wordSpans(text, this.#word));
            rows.push(`<div class="cv-row${n === this.#focus ? ' cv-row--focus' : ''}" data-line="${n}"><span class="cv-no">${n}</span><span class="cv-code">${segs.map(s => {
                const cls = [s.kind !== 'plain' ? `tk-${s.kind}` : '', s.match ? 'cv-match' : '', s.word ? 'cv-word' : ''].filter(Boolean).join(' ');
                return cls ? `<span class="${cls}">${esc(s.text)}</span>` : esc(s.text);
            }).join('')}</span></div>`);
        }
        fill(pane, `<div class="cv cv--fill"><div class="cv-title"><span class="cv-name">${esc(doc.path)}</span><span class="cv-meta"><span class="cv-lang">${esc(doc.language)}</span><span class="cv-count">${total.toLocaleString()} lines</span></span>${caps.outline ? '<pk-button size="mini" variant="ghost" data-ce-outline>Outline</pk-button>' : ''}${caps.references && this.#word ? `<pk-button size="mini" variant="ghost" data-ce-usages>Usages of ${esc(this.#word)}</pk-button>` : ''}</div>${start > 1 || end < total ? `<div class="cv-notice">Showing lines ${start}-${end} of ${total}.</div>` : ''}<div class="cv-scroll" tabindex="0">${rows.join('')}</div></div>`);
        this.#upgrade();
        if (this.#focus) pane.querySelector('.cv-row--focus')?.scrollIntoView({ block: 'center' });
        this.#renderInspector();
    }

    #onPaneClick(e) {
        if (e.target.closest('[data-ce-outline]')) return this.#showOutline();
        if (e.target.closest('[data-ce-usages]')) return this.#showUsages();
        const row = e.target.closest('.cv-row'); const code = e.target.closest('.cv-code');
        const sel = this.ownerDocument.defaultView.getSelection();
        if (!row || !code || !sel?.anchorNode || !sel.isCollapsed) return;
        let col = sel.anchorOffset;
        const walker = this.ownerDocument.createTreeWalker(code, NodeFilter.SHOW_TEXT);
        for (let n = walker.nextNode(); n && n !== sel.anchorNode; n = walker.nextNode()) col += n.textContent.length;
        const line = Number(row.dataset.line);
        const word = wordAt(this.#docs.get(this.#active).lines[line - 1], col);
        this.#word = word === this.#word ? '' : word; this.#focus = line;
        this.#renderPane();
    }

    // ---- inspector -------------------------------------------------------
    async #showOutline(toPane = true) {
        try { this.#inspector = { kind: 'outline', items: await this.#provider.outline(this.#active) }; } catch (e) { log.warn('the outline could not be read', e); this.#inspector = { kind: 'outline', items: [], error: e.message }; }
        this.#renderInspector(); if (toPane) this.#showPane('aside');
    }

    async #showUsages() {
        try { this.#inspector = { kind: 'usages', word: this.#word, items: await this.#provider.references(this.#active, this.#word) }; } catch (e) { log.warn('the usages could not be read', e); this.#inspector = { kind: 'usages', word: this.#word, items: [], error: e.message }; }
        this.#renderInspector(); this.#showPane('aside');
    }

    #renderInspector() {
        const i = this.#inspector;
        const shown = Boolean(i) && Boolean(this.#docs.get(this.#active));
        this.querySelector('[data-ce-root]').toggleAttribute('aside-open', shown);
        if (!shown) return;
        this.querySelector('[data-ce-inspector-title]').textContent = i.kind === 'outline' ? 'Outline' : `Usages of ${i.word}`;
        const body = this.querySelector('[data-ce-inspector-body]');
        if (i.error) { fill(body, `<p class="ce-error" role="alert">${esc(i.error)}</p>`); return; }
        if (!i.items.length) { fill(body, `<p class="ce-muted">${i.kind === 'outline' ? 'Nothing to outline in this file.' : 'No usages found.'}</p>`); return; }
        fill(body, i.kind === 'outline'
            ? `<ul class="co">${i.items.map(x => `<li><button type="button" class="co-item co-d${Math.min(Math.max(x.depth ?? 0, 0), 3)}" data-line="${x.line}"><span class="co-kind">${esc(x.kind)}</span><span class="co-name">${esc(x.name)}</span><span class="co-line">${x.line}</span></button></li>`).join('')}</ul>`
            : `<div class="csr">${i.items.map(x => `<button type="button" class="csr-hit" data-path="${esc(x.path)}" data-line="${x.line}"><span class="csr-no">${x.line}</span><span class="csr-text">${esc(x.path)}: ${esc(x.text.trim())}</span></button>`).join('')}</div>`);
    }

    #onInspectorClick(e) {
        const b = e.target.closest('[data-line]');
        if (!b) return;
        this.openFile(b.dataset.path ?? this.#active, { line: Number(b.dataset.line) });
    }
}

export function defineCodeExplorer(registry = globalThis.customElements) {
    if (globalThis.HTMLElement && registry && !registry.get('pk-code-explorer')) registry.define('pk-code-explorer', CodeExplorerElement);
}

defineCodeExplorer();

// Code explorer data providers. One interface, three sources; the UI asks the provider what it can do and hides the rest.
//
//   provider.capabilities  { search, outline, references, live }   booleans; list and read are always available
//   provider.listFiles()   -> [{ path, lines, language? }]
//   provider.readFile(p)   -> { path, language?, lines: string[] }
//   provider.search(q)     -> [{ path, hits: [{ line, text }] }]        only when capabilities.search
//   provider.outline(p)    -> [{ kind, name, line, depth, detail? }]     only when capabilities.outline
//   provider.references(p, word) -> [{ path, line, text }]              only when capabilities.references
//   provider.subscribe(cb) -> unsubscribe()                             only when capabilities.live;
//                             cb({ type: 'changed' | 'added' | 'removed', path? }) -- omit path to mean "reload the list"
//
// Snapshot file (one JSON document): { "version": 1, "generated": "ISO date", "files": [ { "path", "language"?,
//   "content": "text", "symbols"?: [ { kind, name, line, depth } ] } ] }
//
// API contract (relative to the configured base URL; every response is JSON):
//   GET capabilities            -> { search, outline, references, live }     optional; missing means list + read only
//   GET files                   -> [{ path, lines, language? }]
//   GET file?path=P             -> { path, language?, lines: string[] }  (or { content: "text" })
//   GET search?q=Q              -> [{ path, hits: [{ line, text }] }]
//   GET outline?path=P          -> [{ kind, name, line, depth, detail? }]
//   GET references?path=P&word=W-> [{ path, line, text }]
// Feed: a Server-Sent Events URL (or, with interval, a polled JSON URL) that emits { type, path? } messages; reads still
// come from the wrapped provider.
//
// Framework-free; `fetch` and `EventSource` are injectable so the contract can be tested without a browser.

import { createLogger } from '../../js/log.js';

const log = createLogger('code-explorer');

export const NO_CAPABILITIES = Object.freeze({ search: false, outline: false, references: false, live: false });

const WORD = /[A-Za-z0-9_$]/;

// Whole-word occurrences of `word` in `text`: [{ start, length }].
export function wordSpans(text, word) {
    const spans = [];
    if (!word) return spans;
    for (let i = text.indexOf(word); i !== -1; i = text.indexOf(word, i + 1)) {
        if (!(i > 0 && WORD.test(text[i - 1])) && !(i + word.length < text.length && WORD.test(text[i + word.length]))) spans.push({ start: i, length: word.length });
    }
    return spans;
}

// A user-supplied regex source is refused when it is long or shaped to backtrack catastrophically (nested quantifiers, stacked wildcards).
export function unsafeRegex(source) {
    if (source.length > 200) return 'longer than 200 characters';
    if (/\((?:[^()\\]|\\.)*[+*](?:[^()\\]|\\.)*\)[+*{]/.test(source)) return 'nested quantifier (catastrophic backtracking risk)';
    if (/(\.\*){3,}/.test(source)) return 'repeated wildcards';
    return null;
}

const MAX_SCAN_LINE = 5000;

// A query is plain text (case-insensitive) or /regex/flags; returns a function line -> [{ start, length }] or throws on a bad regex.
export function matcherFor(query) {
    const m = /^\/(.+)\/([a-z]*)$/.exec(query);
    if (m) {
        const bad = unsafeRegex(m[1]);
        if (bad) throw new Error(`regex refused: ${bad}`);
        const rx = new RegExp(m[1], m[2].includes('g') ? m[2] : m[2] + 'g');
        return line => Array.from(line.slice(0, MAX_SCAN_LINE).matchAll(rx), x => ({ start: x.index, length: x[0].length })).filter(s => s.length > 0);
    }
    const needle = query.toLowerCase();
    return line => {
        const found = []; const hay = line.toLowerCase();
        for (let i = hay.indexOf(needle); needle && i !== -1; i = hay.indexOf(needle, i + needle.length)) found.push({ start: i, length: needle.length });
        return found;
    };
}

const toLines = text => String(text).replace(/\r\n/g, '\n').split('\n');

export class SnapshotProvider {
    constructor(snapshot) {
        this.files = new Map((snapshot.files ?? []).map(f => [f.path, { ...f, lines: f.lines ?? toLines(f.content ?? '') }]));
        this.generated = snapshot.generated;
        const anySymbols = [...this.files.values()].some(f => f.symbols?.length);
        this.capabilities = { search: true, outline: anySymbols, references: true, live: false };
    }

    static async load(url, fetchFn = globalThis.fetch) {
        const res = await fetchFn(url);
        if (!res.ok) throw new Error(`snapshot ${url}: ${res.status}`);
        return new SnapshotProvider(await res.json());
    }

    async listFiles() { return [...this.files.values()].map(f => ({ path: f.path, lines: f.lines.length, language: f.language })); }

    async readFile(path) {
        const f = this.files.get(path);
        if (!f) throw new Error(`no such file: ${path}`);
        return { path: f.path, language: f.language, lines: f.lines };
    }

    async search(query) {
        const match = matcherFor(query);
        const groups = [];
        for (const f of this.files.values()) {
            const hits = [];
            f.lines.forEach((text, i) => { const spans = match(text); if (spans.length) hits.push({ line: i + 1, text, spans }); });
            if (hits.length) groups.push({ path: f.path, hits });
        }
        return groups;
    }

    async outline(path) { return this.files.get(path)?.symbols ?? []; }

    async references(path, word) {
        const out = [];
        for (const f of this.files.values()) f.lines.forEach((text, i) => { if (wordSpans(text, word).length) out.push({ path: f.path, line: i + 1, text }); });
        return out;
    }
}

export class ApiProvider {
    constructor(base, { fetch: fetchFn = globalThis.fetch, capabilities } = {}) {
        this.base = String(base).replace(/\/+$/, '');
        this.fetch = fetchFn;
        this.capabilities = { ...NO_CAPABILITIES, ...capabilities };
    }

    static async connect(base, options = {}) {
        const p = new ApiProvider(base, options);
        try { p.capabilities = { ...NO_CAPABILITIES, ...(await p.#get('capabilities')) }; } catch (error) { log.debug('the server has no capabilities endpoint: list and read only', error); }
        return p;
    }

    async #get(path, query = {}) {
        const qs = new URLSearchParams(query).toString();
        const res = await this.fetch(`${this.base}/${path}${qs ? '?' + qs : ''}`);
        if (!res.ok) throw new Error(`${path}: ${res.status}`);
        return res.json();
    }

    listFiles() { return this.#get('files'); }

    async readFile(path) {
        const f = await this.#get('file', { path });
        return { path: f.path ?? path, language: f.language, lines: f.lines ?? toLines(f.content ?? '') };
    }

    search(q) { return this.#get('search', { q }); }
    outline(path) { return this.#get('outline', { path }); }
    references(path, word) { return this.#get('references', { path, word }); }
}

// Wraps another provider and adds live updates from a feed (SSE by default, polling when `interval` ms is given).
export class FeedProvider {
    constructor(inner, feedUrl, { EventSource: ES = globalThis.EventSource, fetch: fetchFn = globalThis.fetch, interval = 0 } = {}) {
        this.inner = inner;
        this.feedUrl = feedUrl;
        this.ES = ES;
        this.fetch = fetchFn;
        this.interval = interval;
        this.capabilities = { ...inner.capabilities, live: true };
        for (const m of ['listFiles', 'readFile', 'search', 'outline', 'references']) this[m] = (...args) => inner[m](...args);
    }

    subscribe(cb) {
        if (this.interval > 0) {
            let last = '';
            const timer = setInterval(async () => {
                try {
                    const text = JSON.stringify(await (await this.fetch(this.feedUrl)).json());
                    if (text !== last) { if (last) cb({ type: 'changed' }); last = text; }
                } catch (error) { log.debug('the change feed could not be read: trying again next tick', error); }
            }, this.interval);
            return () => clearInterval(timer);
        }
        const es = new this.ES(this.feedUrl);
        es.onmessage = e => { try { cb(JSON.parse(e.data)); } catch (error) { log.debug('a change event was not JSON: treating it as a change', error); cb({ type: 'changed' }); } };
        return () => es.close();
    }
}

// The methods a provider must have for what it claims. Returns a list of problems; empty means it honours the contract.
export function contractProblems(provider) {
    const problems = [];
    for (const m of ['listFiles', 'readFile']) if (typeof provider[m] !== 'function') problems.push(`missing ${m}()`);
    const caps = provider.capabilities ?? {};
    const needs = { search: 'search', outline: 'outline', references: 'references', live: 'subscribe' };
    for (const [cap, method] of Object.entries(needs)) if (caps[cap] && typeof provider[method] !== 'function') problems.push(`claims ${cap} but has no ${method}()`);
    return problems;
}

// source: "snapshot" | "api" | "feed"; src: the snapshot URL, the API base URL, or the feed URL (feed wraps `base`, an API base URL, via options.base).
export async function createProvider({ source, src, ...options }) {
    switch (source) {
        case 'snapshot': return SnapshotProvider.load(src, options.fetch);
        case 'api': return ApiProvider.connect(src, options);
        case 'feed': return new FeedProvider(await ApiProvider.connect(options.base ?? src, options), src, options);
        default: throw new Error(`unknown code-explorer source "${source}" (use snapshot, api or feed)`);
    }
}

// A tiny syntax colouriser for the code explorer demo and snapshots. It is not the C# tokenizer and does not try to be:
// comments, strings, numbers, keywords and (for markup) tags, per line. Returns per-line arrays of { start, length, kind }
// where kind is one of keyword, string, comment, number, type, tag, attribute, key -- the tk-* classes in code-explorer.css.

const KEYWORDS = {
    js: 'const let var function return if else for while switch case break continue new class extends import export from default async await try catch finally throw typeof instanceof of in this null true false undefined',
    cs: 'using namespace class struct interface enum public private protected internal static readonly sealed abstract virtual override async await var new return if else for foreach while switch case break continue try catch finally throw null true false this base void string int bool double decimal record get set',
    css: '',
    json: 'true false null',
};
const ALIASES = { javascript: 'js', mjs: 'js', ts: 'js', csharp: 'cs', razor: 'cs' };

export const languageOf = path => {
    const ext = String(path).split('.').pop().toLowerCase();
    return { js: 'js', mjs: 'js', ts: 'js', cs: 'cs', css: 'css', html: 'html', razor: 'html', json: 'json', md: 'plain' }[ext] ?? 'plain';
};

export function tokenize(lines, language = 'plain') {
    const lang = ALIASES[language] ?? language;
    const words = new Set((KEYWORDS[lang] ?? '').split(' ').filter(Boolean));
    let inBlock = false;
    return lines.map(text => {
        const tokens = [];
        const push = (start, length, kind) => length > 0 && tokens.push({ start, length, kind });
        let i = 0;
        if (lang === 'plain') return tokens;
        while (i < text.length) {
            if (inBlock) {
                const end = text.indexOf('*/', i);
                if (end === -1) { push(i, text.length - i, 'comment'); i = text.length; } else { push(i, end + 2 - i, 'comment'); i = end + 2; inBlock = false; }
                continue;
            }
            const c = text[i];
            if (lang === 'html') {
                const tag = /^<\/?[A-Za-z][\w:-]*/.exec(text.slice(i));
                if (tag) { push(i, tag[0].length, 'tag'); i += tag[0].length; continue; }
                const attr = /^\s[\w:@-]+(?==)/.exec(text.slice(i));
                if (attr) { push(i + 1, attr[0].length - 1, 'attribute'); i += attr[0].length; continue; }
            }
            if (c === '/' && text[i + 1] === '/' && lang !== 'html') { push(i, text.length - i, 'comment'); break; }
            if (c === '/' && text[i + 1] === '*') { inBlock = true; push(i, 2, 'comment'); i += 2; continue; }
            if (c === '"' || c === "'" || c === '`') {
                let j = i + 1;
                while (j < text.length && text[j] !== c) j += text[j] === '\\' ? 2 : 1;
                const isKey = lang === 'json' && /^\s*:/.test(text.slice(j + 1));
                push(i, Math.min(j + 1, text.length) - i, isKey ? 'key' : 'string');
                i = Math.min(j + 1, text.length);
                continue;
            }
            const num = /^\d[\d._]*/.exec(text.slice(i));
            if (num && !/[\w$]/.test(text[i - 1] ?? '')) { push(i, num[0].length, 'number'); i += num[0].length; continue; }
            const word = /^[A-Za-z_$][\w$]*/.exec(text.slice(i));
            if (word) {
                const w = word[0];
                if (words.has(w)) push(i, w.length, 'keyword');
                else if (/^[A-Z]/.test(w) && lang !== 'css') push(i, w.length, 'type');
                i += w.length;
                continue;
            }
            i++;
        }
        return tokens;
    });
}

// Cut a line at every token, match and word boundary: [{ text, kind, match, word }]. Pure; the element renders each as a span.
export function buildSegments(text, tokens = [], matches = [], wordRanges = []) {
    if (!text.length) return [];
    const cuts = new Set([0, text.length]);
    for (const r of [...tokens, ...matches, ...wordRanges]) { cuts.add(Math.max(0, r.start)); cuts.add(Math.min(text.length, r.start + r.length)); }
    const points = [...cuts].sort((a, b) => a - b);
    const inside = (ranges, at) => ranges.some(r => at >= r.start && at < r.start + r.length);
    const out = [];
    for (let i = 0; i + 1 < points.length; i++) {
        const a = points[i];
        out.push({ text: text.slice(a, points[i + 1]), kind: tokens.find(t => a >= t.start && a < t.start + t.length)?.kind ?? 'plain', match: inside(matches, a), word: inside(wordRanges, a) });
    }
    return out;
}

// The identifier at a column of a line, or "".
export function wordAt(text, column) {
    let s = column, e = column;
    while (s > 0 && /[A-Za-z0-9_$]/.test(text[s - 1])) s--;
    while (e < text.length && /[A-Za-z0-9_$]/.test(text[e])) e++;
    return text.slice(s, e);
}

// The dev console as a module: mountConsole(container, options) is a live view of what the page, the SDK and the app are doing:
// everything sent to console.*, uncaught errors and rejected promises, every pk-* event the SDK's elements fire, the network requests
// the page made, which pk-* elements are on the page (and whether each is registered), and the environment (theme, density, viewport,
// preferences, Blazor). Built only from SDK components (pk-tabs, pk-table, pk-input, pk-button, pk-button-group, pk-cluster); it draws nothing itself.
//
//   const dev = await mountConsole(el, { tab: 'console', height: '28rem', theme: 'dark' });
//   dev.log('warn', 'Something to look at');
//
// Options: capture (which feeds to record; any of 'console', 'errors', 'events', 'network'; default all), max (entries kept, default
// 500), events (pk-* event names to record; default: every event in elements/api.json, else a built-in list), tab (first tab shown),
// theme, height (any CSS length, or 'fill'). Returns { log(level, text), clear(), entries(), select(tab), destroy() }.
// There is deliberately no JavaScript prompt: running typed code needs eval, which the SDK's strict CSP (and its security scan) forbids.
// destroy() puts console.* back exactly as it was found.

import { LEVELS, formatArgs, makeEntry, pushEntry, filterEntries, countByLevel, exportEntries, elementInventory, formatArg } from '../../js/console-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { shortName, formatBytes, formatMs } from '../../js/perf-logic.js';
import { PK_VERSION } from '../../js/version.js';

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./console.css'];

export const DEFAULTS = Object.freeze({ max: 500, capture: ['console', 'errors', 'events', 'network'] });

// Used when elements/api.json cannot be read (the SDK source layout has none).
const FALLBACK_EVENTS = ['pk-change', 'pk-value-change', 'pk-dismiss', 'pk-close', 'pk-tab-change', 'pk-tab-close', 'pk-select', 'pk-sort', 'pk-filter', 'pk-toggle', 'pk-activate', 'pk-search', 'pk-row-click', 'pk-copy', 'pk-remove', 'pk-page-change'];

const TABS = [['console', 'Console'], ['events', 'Events'], ['network', 'Network'], ['elements', 'Elements'], ['environment', 'Environment']];
const CONSOLE_METHODS = { debug: 'debug', log: 'log', info: 'info', warn: 'warn', error: 'error' };

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

const clock = at => { const d = new Date(at); return `${d.toLocaleTimeString([], { hour12: false })}.${String(d.getMilliseconds()).padStart(3, '0')}`; };

async function eventNames(win, given) {
    if (given?.length) return given;
    try {
        const res = await win.fetch(new URL('../elements/api.json', import.meta.url));
        if (res.ok) return [...new Set((await res.json()).flatMap(e => (e.events ?? []).map(x => x.name)).filter(n => n.startsWith('pk-')))];
    } catch { /* no api.json next to this module */ }
    return FALLBACK_EVENTS;
}

export async function mountConsole(container, options = {}) {
    const { theme, height, tab = 'console', max = DEFAULTS.max } = options;
    const capture = new Set(options.capture ?? DEFAULTS.capture);
    const doc = container.ownerDocument;
    const win = doc.defaultView;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    let entries = [];
    let level = 'debug';
    let text = '';
    let active = TABS.some(([k]) => k === tab) ? tab : 'console';
    let inCapture = false;

    // ---- the page shell: SDK tabs, each panel one SDK table (the console panel adds its toolbar) ------------------------------
    const tables = {};
    const tabs = h(doc, 'pk-tabs', { value: active, label: 'Dev console' });
    const countTabs = {};
    for (const [key, label] of TABS) {
        countTabs[key] = h(doc, 'pk-tab', { value: key }, label);
        tabs.append(countTabs[key]);
    }
    const table = (key, label, columns) => (tables[key] = h(doc, 'pk-table', { label, density: 'compact', stickyHeader: true, maxHeight: '18rem', columns: JSON.stringify(columns) }));
    const logColumns = [{ key: 'time', label: 'Time' }, { key: 'level', label: 'Level' }, { key: 'message', label: 'Message' }];
    const search = h(doc, 'pk-input', { type: 'search', label: 'Filter the log', placeholder: 'Filter', clearable: true, debounce: 150, size: 'sm' });
    const levels = h(doc, 'pk-button-group', { label: 'Minimum level', mode: 'single' },
        ...[['debug', 'All'], ['warn', 'Warnings'], ['error', 'Errors']].map(([v, l]) => h(doc, 'pk-button', { toggle: true, variant: 'ghost', size: 'mini', value: v, pressed: v === 'debug' }, l)));
    const clear = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Clear');
    const copy = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Copy as JSON');
    const status = h(doc, 'span', { class: 'muted', role: 'status' });
    const panel = (key, ...body) => tabs.append(h(doc, 'pk-tab-panel', { value: key }, ...body));
    panel('console', h(doc, 'pk-cluster', {}, search, levels, clear, copy, status), table('console', 'Console', logColumns));
    panel('events', table('events', 'SDK events', [{ key: 'time', label: 'Time' }, { key: 'message', label: 'Event' }]));
    panel('network', table('network', 'Network', [{ key: 'time', label: 'Time' }, { key: 'message', label: 'Request' }]));
    panel('elements', table('elements', 'pk-* elements on this page', [{ key: 'tag', label: 'Element' }, { key: 'count', label: 'On page', align: 'end' }, { key: 'defined', label: 'Registered' }]));
    panel('environment', table('environment', 'Environment', [{ key: 'name', label: 'Setting' }, { key: 'value', label: 'Value' }]));

    const root = h(doc, 'section', { 'aria-label': 'Dev console', class: 'dc-module' }, tabs);
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.setProperty('height', height === 'fill' ? '100%' : height); root.style.setProperty('overflow', 'auto'); }
    container.replaceChildren(root);
    loadElements(root).catch(() => { /* loadElements logs its own failures */ });

    // ---- rendering: throttled, one panel at a time ------------------------------------------------------------------------
    const setRows = (key, rows) => { const s = JSON.stringify(rows); if (tables[key].getAttribute('rows') !== s) tables[key].setAttribute('rows', s); };
    const bySource = source => entries.filter(e => e.source === source);

    function environment() {
        const root = doc.documentElement;
        const media = q => win.matchMedia?.(q).matches;
        return [
            ['Plainkit', PK_VERSION], ['Theme', root.getAttribute('data-theme') ?? 'default'], ['Density', root.getAttribute('data-density') ?? 'default'],
            ['Viewport', `${win.innerWidth} x ${win.innerHeight} at ${win.devicePixelRatio}x`], ['Prefers', `${media('(prefers-color-scheme: dark)') ? 'dark' : 'light'} colour, ${media('(prefers-reduced-motion: reduce)') ? 'reduced' : 'full'} motion`],
            ['Language', root.lang || 'not set'], ['Online', String(win.navigator.onLine)], ['Stylesheets', String(doc.styleSheets.length)],
            ['Custom elements', String(elementInventory([...doc.getElementsByTagName('*')].map(e => e.localName), () => true).length) + ' pk-* kinds'],
            ['Blazor', win.Blazor ? 'present' : 'not on this page'], ['Address', win.location.href], ['Agent', win.navigator.userAgent],
        ].map(([name, value], id) => ({ id, name, value }));
    }

    function render() {
        const shown = filterEntries(bySource('console').concat(bySource('error'), bySource('rejection')).sort((a, b) => a.at - b.at), { minLevel: level, text });
        const counts = countByLevel(entries.filter(e => e.source !== 'event' && e.source !== 'network'));
        countTabs.console.setAttribute('count', String(counts.warn + counts.error));
        status.textContent = `${shown.length} shown, ${counts.error} errors, ${counts.warn} warnings`;
        if (active === 'console') setRows('console', shown.map((e, id) => ({ id, time: clock(e.at), level: e.level, message: e.text })));
        if (active === 'events') setRows('events', bySource('event').map((e, id) => ({ id, time: clock(e.at), message: e.text })));
        if (active === 'network') setRows('network', bySource('network').map((e, id) => ({ id, time: clock(e.at), message: e.text })));
        if (active === 'elements') setRows('elements', elementInventory([...doc.getElementsByTagName('*')].map(e => e.localName), t => win.customElements.get(t)).map(x => ({ id: x.tag, tag: x.tag, count: x.count, defined: x.defined ? 'yes' : 'not loaded' })));
        if (active === 'environment') setRows('environment', environment());
    }
    let queued = 0;
    const schedule = () => { if (!queued) queued = win.setTimeout(() => { queued = 0; render(); }, 100); };
    const record = (lvl, message, meta) => { entries = pushEntry(entries, makeEntry(lvl, message, meta), max); schedule(); };

    // ---- capture, each part undone by destroy() ---------------------------------------------------------------------------
    const undo = [];
    if (capture.has('console')) {
        for (const method of Object.values(CONSOLE_METHODS)) {
            const original = win.console[method];
            win.console[method] = (...args) => {
                original.apply(win.console, args);
                if (inCapture) return; // a log made while formatting one is not recorded again
                inCapture = true;
                try { record(method, formatArgs(args)); } finally { inCapture = false; }
            };
            undo.push(() => { win.console[method] = original; });
        }
    }
    if (capture.has('errors')) {
        const onError = e => record('error', `${e.message}${e.filename ? ` (${shortName(e.filename)}:${e.lineno})` : ''}`, { source: 'error' });
        const onReject = e => record('error', `Unhandled rejection: ${formatArg(e.reason)}`, { source: 'rejection' });
        win.addEventListener('error', onError); win.addEventListener('unhandledrejection', onReject);
        undo.push(() => { win.removeEventListener('error', onError); win.removeEventListener('unhandledrejection', onReject); });
    }
    if (capture.has('events')) {
        const names = await eventNames(win, options.events);
        const onEvent = e => { const t = e.composedPath?.()[0] ?? e.target; record('info', `${e.type} on <${t?.localName ?? '?'}${t?.id ? `#${t.id}` : ''}> ${e.detail === undefined || e.detail === null ? '' : formatArg(e.detail)}`.trim(), { source: 'event' }); };
        for (const n of names) doc.addEventListener(n, onEvent, true);
        undo.push(() => { for (const n of names) doc.removeEventListener(n, onEvent, true); });
    }
    if (capture.has('network') && typeof win.PerformanceObserver === 'function') {
        try {
            const po = new win.PerformanceObserver(list => { for (const r of list.getEntries()) record('info', `${shortName(r.name)}  ${formatMs(r.duration)}  ${formatBytes(r.transferSize)}  (${r.initiatorType})`, { source: 'network', at: Date.now() }); });
            po.observe({ type: 'resource', buffered: true });
            undo.push(() => po.disconnect());
        } catch { /* resource timing unavailable */ }
    }

    // ---- controls ---------------------------------------------------------------------------------------------------------
    tabs.addEventListener('pk-tab-change', e => { active = e.detail.value; render(); });
    search.addEventListener('pk-search', e => { text = e.detail.value ?? ''; render(); });
    levels.addEventListener('pk-toggle', e => { const b = e.target.closest('pk-button'); if (b?.getAttribute('value') && (e.detail?.pressed ?? true)) { level = b.getAttribute('value'); render(); } });
    clear.addEventListener('click', () => { entries = []; render(); });
    copy.addEventListener('click', () => win.navigator.clipboard?.writeText(exportEntries(filterEntries(entries, { minLevel: level, text }))).catch(() => { /* clipboard blocked: nothing to copy to */ }));
    const timer = win.setInterval(() => { if (active === 'elements' || active === 'environment') render(); }, 2000);

    render();
    return {
        log: (lvl, message) => record(LEVELS.includes(lvl) ? lvl : 'log', String(message)),
        clear: () => { entries = []; render(); },
        entries: () => entries.slice(),
        select: key => { if (TABS.some(([k]) => k === key)) { active = key; tabs.setAttribute('value', key); render(); } },
        destroy() { win.clearInterval(timer); win.clearTimeout(queued); for (const u of undo.reverse()) u(); root.remove(); },
    };
}

/* Dev tools chrome: the dock and its launcher. Everything inside is SDK components; this only places and themes the surface. */

.dt-surface { color: var(--color-text); background: var(--color-bg); }

.dt-surface--dock { position: fixed; inset-inline: 0; bottom: 0; z-index: var(--z-flyout); block-size: var(--dt-height, 40vh); overflow: auto; border-top: 1px solid var(--color-border); box-shadow: var(--shadow-flyout); }

.dt-surface--dock[hidden] { display: none; }

.dt-panel-body { padding: var(--space-3); }

.dt-launcher { position: fixed; inset-inline-end: var(--space-3); bottom: var(--space-3); z-index: var(--z-pop); }

// The dev tools as a module: mountDevTools(container, options) puts the SDK's live tools (console, logs, logging settings, performance, and any panel you add)
// in one tabbed surface, either docked over the page (Ctrl+` toggles it, like a browser's dev tools) or inline in a container.
// Built only from SDK components (pk-tabs, pk-button, pk-button-group) around the console, logs, log settings and performance modules, plus the Quality
// (the SDK page checks on the live page), Inspector (pk-* elements on the page) and Theme (the theme editor, live on this page) panels in panels.js.
//
//   const tools = await mountDevTools(null, { mode: 'dock' });      // a floating button and a bottom dock on any page
//   const page  = await mountDevTools(el, { mode: 'inline' });      // the same tabs, filling a container
//   tools.toggle(); tools.select('console');
//
// Options: mode ('dock' | 'inline'; default 'dock'), hotkey (dock only; default 'Ctrl+`', '' turns it off), tab (first tab), open (dock
// only; start open), size ('small' | 'medium' | 'large'; dock height, default 'medium'), theme, panels (extra tabs, below).
// A panel is { id, title, mount(element, context) } where mount returns nothing or { destroy(), activate(), deactivate() }; activate and
// deactivate are called as its tab is shown and hidden, so a panel can pause work while unseen. context is { doc, win, theme, whileHidden(fn), isTool(el) }.
// Returns { open(), close(), toggle(), isOpen(), select(id), tabs(), destroy() }.

import { mountPerformance } from '../performance/performance.js';
import { mountConsole } from '../console/console.js';
import { mountLogs } from '../logs/logs.js';
import { mountLogSettings } from '../log-settings/log-settings.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { qualityPanel, inspectorPanel, themePanel } from './panels.js';

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./devtools.css'];

export const SIZES = Object.freeze({ small: '25vh', medium: '40vh', large: '65vh' });

// The built-in panels, in the shape a panel of your own takes. Console mounts first so it records from the start.
export const BUILT_IN = Object.freeze([
    { id: 'console', title: 'Console', mount: async el => { const c = await mountConsole(el, {}); return { destroy: () => c.destroy() }; } },
    // Logs is the SDK logger's entries (js/log.js), not console output; Logging is where its level and outputs are set.
    { id: 'logs', title: 'Logs', mount: async el => { const l = await mountLogs(el, {}); return { destroy: () => l.destroy() }; } },
    { id: 'logging', title: 'Logging', mount: async el => { const s = await mountLogSettings(el, {}); return { destroy: () => s.destroy(), activate: () => s.refresh() }; } },
    {
        id: 'performance', title: 'Performance',
        mount: async el => { const p = await mountPerformance(el, { autostart: false }); return { destroy: () => p.destroy(), activate: () => p.start(), deactivate: () => p.stop() }; },
    },
    qualityPanel,
    inspectorPanel,
    themePanel,
]);

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

// Does this key event match a chord like "Ctrl+`" or "Ctrl+Shift+D"?
export function matchesHotkey(event, chord) {
    if (!chord) return false;
    const parts = chord.split('+').map(s => s.trim());
    const key = parts.pop();
    const want = new Set(parts.map(p => p.toLowerCase()));
    const has = { ctrl: Boolean(event.ctrlKey || event.metaKey), shift: Boolean(event.shiftKey), alt: Boolean(event.altKey) };
    return event.key.toLowerCase() === key.toLowerCase()
        && want.has('ctrl') === has.ctrl && want.has('shift') === has.shift && want.has('alt') === has.alt;
}

export async function mountDevTools(container, options = {}) {
    const { mode = 'dock', hotkey = 'Ctrl+`', theme, panels = [] } = options;
    const doc = container?.ownerDocument ?? globalThis.document;
    const win = doc.defaultView;
    const dock = mode === 'dock';
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    const all = [...BUILT_IN, ...panels];
    const ids = all.map(p => p.id);
    let active = ids.includes(options.tab) ? options.tab : ids[0];
    let opened = !dock || Boolean(options.open);
    const mounted = new Map();

    const tabs = h(doc, 'pk-tabs', { value: active, label: 'Dev tools' });
    const bodies = new Map();
    for (const p of all) {
        tabs.append(h(doc, 'pk-tab', { value: p.id }, p.title));
        const body = h(doc, 'div', { class: 'dt-panel-body' });
        bodies.set(p.id, body);
        tabs.append(h(doc, 'pk-tab-panel', { value: p.id }, body));
    }

    const surface = h(doc, dock ? 'aside' : 'section', { class: `dt-surface dt-surface--${mode}`, 'aria-label': 'Dev tools' }, tabs);
    let toggleButton = null;
    let sizes = null;
    if (theme) surface.setAttribute('data-theme', theme);
    if (dock) {
        surface.hidden = !opened;
        surface.style.setProperty('--dt-height', SIZES[options.size] ?? SIZES.medium);
        sizes = h(doc, 'pk-button-group', { label: 'Dock height', mode: 'single', slot: 'trailing' },
            ...Object.keys(SIZES).map(k => h(doc, 'pk-button', { toggle: true, variant: 'ghost', size: 'mini', value: k, pressed: k === (options.size ?? 'medium') }, k[0].toUpperCase() + k.slice(1))));
        const close = h(doc, 'pk-button', { size: 'mini', variant: 'ghost', label: 'Close dev tools', slot: 'trailing' }, 'Close');
        tabs.append(sizes, close);
        close.addEventListener('click', () => api.close());
        sizes.addEventListener('pk-toggle', e => { const v = e.target.closest('pk-button')?.getAttribute('value'); if (v && SIZES[v]) surface.style.setProperty('--dt-height', SIZES[v]); });
        toggleButton = h(doc, 'pk-button', { class: 'dt-launcher', size: 'mini', variant: 'secondary' }, 'Dev tools');
        toggleButton.addEventListener('click', () => api.toggle());
        doc.body.append(surface, toggleButton);
    } else {
        container.replaceChildren(surface);
    }
    loadElements(surface).catch(() => { /* loadElements logs its own failures */ });
    if (toggleButton) loadElements(toggleButton).catch(() => { /* loadElements logs its own failures */ });

    // Every panel mounts up front (the console must record from the start); activate/deactivate follow what is visible.
    // whileHidden runs a measurement with the tools out of the way (so the page is measured, not the tools); isTool says whether an element is ours.
    const whileHidden = fn => {
        const before = [surface.hidden, toggleButton?.hidden];
        surface.hidden = true; if (toggleButton) toggleButton.hidden = true;
        try { return fn(); } finally { surface.hidden = before[0]; if (toggleButton) toggleButton.hidden = before[1]; }
    };
    const context = { doc, win, theme, whileHidden, isTool: e => surface.contains(e) || e === toggleButton };
    await Promise.all(all.map(async p => { mounted.set(p.id, (await p.mount(bodies.get(p.id), context)) ?? {}); }));
    const sync = () => { for (const [id, m] of mounted) (opened && id === active ? m.activate : m.deactivate)?.(); };
    tabs.addEventListener('pk-tab-change', e => { active = e.detail.value; sync(); });

    const onKey = e => { if (dock && matchesHotkey(e, hotkey)) { e.preventDefault(); api.toggle(); } };
    if (dock) doc.addEventListener('keydown', onKey);
    sync();

    const api = {
        open() { opened = true; if (dock) { surface.hidden = false; toggleButton.setAttribute('aria-pressed', 'true'); } sync(); },
        close() { opened = false; if (dock) { surface.hidden = true; toggleButton.setAttribute('aria-pressed', 'false'); } sync(); },
        toggle() { opened ? api.close() : api.open(); },
        isOpen: () => opened,
        select(id) { if (ids.includes(id)) { active = id; tabs.setAttribute('value', id); sync(); } },
        tabs: () => ids.slice(),
        destroy() {
            doc.removeEventListener('keydown', onKey);
            for (const m of mounted.values()) { m.deactivate?.(); m.destroy?.(); }
            surface.remove(); toggleButton?.remove();
        },
    };
    return api;
}

// The dev tools' Quality, Inspector and Theme panels, in the shape mountDevTools takes: { id, title, mount(element, context) }.
// Quality runs the SDK's own page checks (js/quality.js) on the live page and shows a score and every finding. Inspector lists the pk-*
// elements on the page with the attributes that configure them and highlights one when its row is chosen. Quality and Inspector are built only from
// SDK components (pk-stat, pk-table, pk-button, pk-cluster); Theme mounts the theme editor module against the live document, so a token edit restyles
// the page at once (its overrides persist under the same key as the SDK theme editor page). context.whileHidden(fn) runs fn with the dev tools out of the way, so they are not measured.

import { describeForInspector } from '../../js/inspect-logic.js';
import { loadElements } from '../../js/loader.js';
import { mountThemeEditor } from '../theme-editor/theme-editor.js';
import { mountQuality } from '../quality/quality.js';

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

// The Quality tab is the standalone quality module (modules/quality) mounted in the dock; the dock hides itself while it measures.
export const qualityPanel = {
    id: 'quality',
    title: 'Quality',
    async mount(el, { whileHidden }) {
        const q = await mountQuality(el, { around: whileHidden });
        return { destroy: () => q.destroy() };
    },
};

export const inspectorPanel = {
    id: 'inspector',
    title: 'Inspector',
    async mount(el, { doc, win, isTool }) {
        const refresh = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Refresh');
        const status = h(doc, 'span', { class: 'muted', role: 'status' });
        const table = h(doc, 'pk-table', {
            label: 'pk-* elements on this page', density: 'compact', stickyHeader: true, clickable: true, maxHeight: '18rem',
            columns: JSON.stringify([{ key: 'tag', label: 'Element' }, { key: 'domId', label: 'Id' }, { key: 'props', label: 'Set with' }, { key: 'size', label: 'Size', align: 'end' }]),
        });
        el.append(h(doc, 'pk-cluster', {}, refresh, status), h(doc, 'div', { class: 'u-mt-3' }, table));
        loadElements(el).catch(() => { /* loadElements logs its own failures */ });

        let found = [];
        let outlined = null;
        function list() {
            found = [...doc.querySelectorAll('*')].filter(e => e.localName.startsWith('pk-') && !isTool(e));
            table.setAttribute('rows', JSON.stringify(found.map((e, id) => ({ id, ...describeForInspector(e) }))));
            status.textContent = `${found.length} elements. Choose a row to highlight it on the page.`;
        }
        function highlight(e) {
            outlined?.restore();
            const target = found[Number(e.detail?.id)];
            if (!target) return;
            const before = target.style.getPropertyValue('outline');
            const beforeOffset = target.style.getPropertyValue('outline-offset');
            target.scrollIntoView?.({ block: 'center', behavior: 'smooth' });
            target.style.setProperty('outline', '3px solid var(--color-accent)');
            target.style.setProperty('outline-offset', '2px');
            const restore = () => { target.style.setProperty('outline', before); target.style.setProperty('outline-offset', beforeOffset); if (!before) target.style.removeProperty('outline'); if (!beforeOffset) target.style.removeProperty('outline-offset'); };
            const timer = win.setTimeout(() => { restore(); outlined = null; }, 2000);
            outlined = { restore: () => { win.clearTimeout(timer); restore(); } };
        }
        refresh.addEventListener('click', list);
        table.addEventListener('pk-row-click', highlight);
        return {
            activate: list,
            destroy() { outlined?.restore(); refresh.removeEventListener('click', list); table.removeEventListener('pk-row-click', highlight); },
        };
    },
};

export const themePanel = {
    id: 'theme',
    title: 'Theme',
    async mount(el, { doc }) {
        const editor = await mountThemeEditor(el, { target: doc, preview: false, storageKey: 'pk-theme-overrides' });
        return { destroy: () => editor.destroy() };
    },
};

/* Logging settings chrome. Everything inside is SDK components; this only paints a mounted panel that carries its own theme and sizes its headings. */

.ls-module[data-theme] { color: var(--color-text); background: var(--color-bg); padding: var(--space-3); }

.ls-heading { margin: 0; font-size: var(--text-lg); }

// The logging settings as a module: mountLogSettings(container, options) edits how js/log.js behaves: the global level, a level for any
// scope (the scopes that have logged so far are listed; add one by name), and which outputs each level is sent to (console, toast,
// alert and any output registered with registerLogOutput). "Send a test" logs one entry per level under the scope settings-test, using
// the settings as edited (for this page only); Save keeps them in localStorage (configureLogging(..., { persist: true })); Reset goes
// back to the defaults (resetLogging()). ?pk-log= in the address and <html data-pk-log> still decide the level when the page loads.
// Built only from SDK components (pk-select, pk-input, pk-field, pk-table, pk-checkbox, pk-button, pk-badge, pk-alert, pk-stack,
// pk-cluster); it draws nothing itself. Every value is checked with normalizeConfig before it is applied.
//
//   const settings = await mountLogSettings(el, { onsave: config => console.log(config) });
//
// Options: theme, height (any CSS length, or 'fill'), onsave(config), onchange(draft). Returns { config(), refresh(), save(), reset(), test(), destroy() }.
// Pure logic is js/log-settings-logic.js.

import { configureLogging, getLoggingConfig, resetLogging, getLogBuffer, getLogOutputs, addLogSink, createLogger } from '../../js/log.js';
import { INHERIT, draftFrom, configFrom, scopeRows, addScope, removeScope, setScopeLevel, setGlobalLevel, setRoute, routeRows, sameDraft, levelOverride, describeOverride, outputsFor, testMessages, TEST_SCOPE } from '../../js/log-settings-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./log-settings.css'];

const LEVEL_OPTIONS = [['debug', 'Debug (everything)'], ['info', 'Info'], ['warn', 'Warn'], ['error', 'Error (errors only)'], ['silent', 'Silent (nothing)']];
const LEVEL_NAMES = { debug: 'Debug', info: 'Info', warn: 'Warn', error: 'Error' };

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}
const options = (doc, list, selected) => list.map(([value, label]) => h(doc, 'option', { value, selected: value === selected }, label));

export async function mountLogSettings(container, opts = {}) {
    const { theme, height, onsave, onchange } = opts;
    const doc = container.ownerDocument;
    const win = doc.defaultView;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    const seen = new Set(getLogBuffer().map(e => e.scope));
    const unsink = addLogSink(e => { if (!seen.has(e.scope)) { seen.add(e.scope); } });
    let saved = draftFrom(getLoggingConfig(), [...seen]);
    let draft = saved;
    let message = '';

    // ---- the shell: SDK components only ---------------------------------------------------------------------------------------
    const overrideNote = h(doc, 'pk-alert', { kind: 'info', hidden: true });
    const levelSelect = h(doc, 'pk-select', { label: 'Global level' }, ...options(doc, LEVEL_OPTIONS, draft.level));
    const levelField = h(doc, 'pk-field', { label: 'Global level', description: 'Entries below this level are kept in the logs viewer but not sent to any output. A scope below can override it.' }, levelSelect);
    const scopeTable = h(doc, 'pk-table', { label: 'Level per scope', density: 'compact', cards: true, manual: true, columns: JSON.stringify([{ key: 'scope', label: 'Scope' }, { key: 'level', label: 'Level' }, { key: 'remove', label: '' }]) },
        h(doc, 'pk-empty-state', { slot: 'empty', tone: 'compact', heading: 'No scopes yet', description: 'A scope is listed once it has logged. Add one by name to set its level ahead of time.' }));
    const newScope = h(doc, 'pk-input', { label: 'Add a scope', placeholder: 'checkout' });
    const addBtn = h(doc, 'pk-button', { variant: 'secondary' }, 'Add scope');
    const routeTable = h(doc, 'pk-table', { label: 'Where each level is sent', density: 'compact', manual: true });
    const status = h(doc, 'span', { class: 'muted', role: 'status' });
    const testBtn = h(doc, 'pk-button', { variant: 'secondary' }, 'Send a test');
    const saveBtn = h(doc, 'pk-button', { variant: 'primary' }, 'Save');
    const resetBtn = h(doc, 'pk-button', { variant: 'ghost' }, 'Reset');
    const root = h(doc, 'section', { class: 'ls-module', 'aria-label': 'Logging settings' },
        h(doc, 'pk-stack', { gap: 'md' },
            overrideNote,
            levelField,
            h(doc, 'pk-stack', { gap: 'sm' }, h(doc, 'h3', { class: 'ls-heading' }, 'Level per scope'), scopeTable, h(doc, 'pk-cluster', { align: 'end' }, newScope, addBtn)),
            h(doc, 'pk-stack', { gap: 'sm' }, h(doc, 'h3', { class: 'ls-heading' }, 'Where each level goes'), routeTable),
            h(doc, 'pk-cluster', {}, testBtn, saveBtn, resetBtn, status)));
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.setProperty('height', height === 'fill' ? '100%' : height); root.style.setProperty('overflow', 'auto'); }
    container.replaceChildren(root);
    loadElements(root).catch(() => { /* loadElements logs its own failures */ });

    // ---- drawing: rebuilt from the draft; the table cells are slotted SDK controls ---------------------------------------------
    const changed = () => !sameDraft(draft, saved);
    function drawOverride() {
        const o = levelOverride({ search: win.location?.search ?? '', attr: doc.documentElement.getAttribute('data-pk-log') });
        overrideNote.hidden = !o;
        overrideNote.textContent = o ? `The level is being set by ${describeOverride(o)} whenever this page loads, so it wins over the saved level. Scope levels and outputs below still apply.` : '';
    }

    function drawScopes() {
        const rows = scopeRows(draft);
        const cells = [];
        for (const r of rows) {
            const select = h(doc, 'pk-select', { slot: `cell-${r.id}-level`, label: `Level for ${r.scope}`, value: r.level }, ...options(doc, [[INHERIT, 'Same as global'], ...LEVEL_OPTIONS], r.level));
            select.addEventListener('pk-value-change', e => { draft = setScopeLevel(draft, r.scope, e.detail.value); touched(); });
            const remove = h(doc, 'pk-button', { slot: `cell-${r.id}-remove`, variant: 'ghost', size: 'mini', label: `Remove ${r.scope}` }, 'Remove');
            remove.addEventListener('click', () => { draft = removeScope(draft, r.scope); drawScopes(); touched(); });
            cells.push(select, remove);
        }
        scopeTable.replaceChildren(...cells, h(doc, 'pk-empty-state', { slot: 'empty', tone: 'compact', heading: 'No scopes yet', description: 'A scope is listed once it has logged. Add one by name to set its level ahead of time.' }));
        scopeTable.setAttribute('rows', JSON.stringify(rows.map(r => ({ id: r.id, scope: r.scope }))));
        loadElements(scopeTable).catch(() => { /* loadElements logs its own failures */ });
    }

    function drawRoutes() {
        const outputs = outputsFor(getLogOutputs(), draft.routes);
        const rows = routeRows(draft, outputs);
        routeTable.setAttribute('columns', JSON.stringify([{ key: 'level', label: 'Level' }, ...outputs.map(o => ({ key: o, label: o }))]));
        const cells = [];
        for (const r of rows) {
            for (const o of outputs) {
                const box = h(doc, 'pk-checkbox', { slot: `cell-${r.id}-${o}`, label: `${LEVEL_NAMES[r.level]} to ${o}`, checked: r[o] });
                box.addEventListener('pk-change', e => { draft = setRoute(draft, r.level, o, Boolean(e.detail.checked)); touched(); });
                cells.push(box);
            }
        }
        routeTable.replaceChildren(...cells);
        routeTable.setAttribute('rows', JSON.stringify(rows.map(r => ({ id: r.id, level: LEVEL_NAMES[r.level] }))));
        loadElements(routeTable).catch(() => { /* loadElements logs its own failures */ });
    }

    function touched() {
        status.textContent = message || (changed() ? 'Changes not applied yet: Save applies and keeps them' : 'Settings in use');
        saveBtn.toggleAttribute('disabled', !changed());
        onchange?.(configFrom(draft));
    }
    const say = text => { message = text; touched(); message = ''; };

    function drawAll() {
        levelSelect.setAttribute('value', draft.level);
        drawOverride(); drawScopes(); drawRoutes(); touched();
    }

    // ---- controls -------------------------------------------------------------------------------------------------------------
    levelSelect.addEventListener('pk-value-change', e => { draft = setGlobalLevel(draft, e.detail.value); touched(); });
    const add = () => {
        const r = addScope(draft, newScope.value ?? newScope.getAttribute('value'));
        if (r.error) { newScope.setAttribute('invalid', ''); say(r.error); return; }
        newScope.removeAttribute('invalid'); newScope.value = ''; newScope.setAttribute('value', '');
        draft = r.draft; drawScopes(); touched();
    };
    addBtn.addEventListener('click', add);
    newScope.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); add(); } });

    const api = {
        config: () => configFrom(draft),
        refresh() { saved = draftFrom(getLoggingConfig(), [...seen]); draft = saved; drawAll(); },
        // Applies the draft to this page only (not saved) and logs one entry per level, so a route or level can be tried out before saving.
        test() {
            configureLogging(configFrom(draft), { replace: true });
            const log = createLogger(TEST_SCOPE);
            for (const [level, text] of testMessages()) log[level](text, { sentAt: new Date().toISOString() });
            seen.add(TEST_SCOPE);
            say('Sent one message per level, using these settings for this page. Save keeps them.');
        },
        save() {
            const config = configureLogging(configFrom(draft), { persist: true, replace: true });
            saved = draftFrom(config, [...seen]); draft = saved;
            drawAll(); say('Saved');
            onsave?.(config);
            return config;
        },
        reset() {
            resetLogging();
            saved = draftFrom(getLoggingConfig(), [...seen]); draft = saved;
            drawAll(); say('Back to the defaults');
        },
        destroy() { unsink(); root.remove(); },
    };
    testBtn.addEventListener('click', () => api.test());
    saveBtn.addEventListener('click', () => api.save());
    resetBtn.addEventListener('click', () => api.reset());

    drawAll();
    return api;
}

/* Logs viewer chrome. Everything inside is SDK components; this only paints a mounted viewer that carries its own theme and keeps the message readable. */

.lg-module[data-theme] { color: var(--color-text); background: var(--color-bg); padding: var(--space-3); }

.lg-message { margin: 0; overflow-wrap: anywhere; white-space: pre-wrap; }

// The logs viewer as a module: mountLogs(container, options) is a live view of what the SDK and the app logged through js/log.js
// (createLogger('checkout').warn(...)): the entries already in the ring buffer when it mounts, then every new one as it happens, whatever
// the console level (an entry below it is in the buffer only and is marked "buffered only"). Filter by minimum level, scope and text; a
// row shows its detail (objects as JSON, an Error with its stack); copy, export and import as JSON; pause the view; clear. Built only
// from SDK components (pk-table, pk-input, pk-select, pk-button, pk-button-group, pk-badge, pk-card, pk-code-block, pk-empty-state,
// pk-cluster, pk-stack); it draws nothing itself.
//
//   const logs = await mountLogs(el, { level: 'info', height: '28rem' });
//   logs.pause(); logs.resume(); logs.select(3); logs.entries();
//
// Options: level (the minimum level shown first: debug, info, warn or error; default debug), scopes (scopes selected first), max (entries
// kept, default 1000), order ('newest' first, the default, or 'oldest'), theme, height (any CSS length, or 'fill').
// Returns { pause(), resume(), isPaused(), clear(), entries(), select(id), filter({ level, scopes, text }), destroy() }. pause() freezes what
// is drawn (entries keep arriving and show on resume()). clear() empties the view and the SDK's ring buffer. Pure logic is js/log-view-logic.js.

import { addLogSink, getLogBuffer, getLoggingConfig, clearLogBuffer } from '../../js/log.js';
import { VIEW_LEVELS, filterLogEntries, scopesOf, countLevels, rowFor, describeDetail, pushLog, serializeEntries, parseImport, mergeEntries, formatTime, routeOf } from '../../js/log-view-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./logs.css'];

export const DEFAULTS = Object.freeze({ max: 1000, level: 'debug', order: 'newest' });
const LEVEL_LABEL = { debug: 'Debug', info: 'Info', warn: 'Warn', error: 'Error' };
const LEVEL_TONE = { debug: 'muted', info: 'outline', warn: 'warn', error: 'danger' };
const COLUMNS = [{ key: 'time', label: 'Time' }, { key: 'level', label: 'Level' }, { key: 'scope', label: 'Scope' }, { key: 'message', label: 'Message' }, { key: 'output', label: 'Output', hidePhone: true }];

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

export async function mountLogs(container, options = {}) {
    const { theme, height, max = DEFAULTS.max } = options;
    const doc = container.ownerDocument;
    const win = doc.defaultView;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    let entries = [];
    let nextId = 1;
    let minLevel = VIEW_LEVELS.includes(options.level) ? options.level : DEFAULTS.level;
    let scopes = [...(options.scopes ?? [])];
    let text = '';
    let newestFirst = (options.order ?? DEFAULTS.order) !== 'oldest';
    let paused = false;
    let selected = null;
    let note = '';
    let drawnScopes = '';

    // ---- the shell: SDK components only ---------------------------------------------------------------------------------------
    const search = h(doc, 'pk-input', { type: 'search', label: 'Filter the log', placeholder: 'Filter messages', clearable: true, debounce: 150 });
    const levels = h(doc, 'pk-button-group', { label: 'Minimum level', mode: 'single' },
        ...VIEW_LEVELS.map(v => h(doc, 'pk-button', { toggle: true, variant: 'ghost', size: 'mini', value: v, pressed: v === minLevel }, LEVEL_LABEL[v])));
    const scopeSelect = h(doc, 'pk-select', { label: 'Scopes (none selected shows all)', multiple: true });
    const badges = Object.fromEntries(VIEW_LEVELS.map(v => [v, h(doc, 'pk-badge', { variant: LEVEL_TONE[v] })]));
    const status = h(doc, 'span', { class: 'muted', role: 'status' });
    const pause = h(doc, 'pk-button', { size: 'mini', variant: 'ghost', toggle: true }, 'Pause');
    const order = h(doc, 'pk-button', { size: 'mini', variant: 'ghost', toggle: true, pressed: newestFirst }, 'Newest first');
    const clear = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Clear');
    const copy = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Copy as JSON');
    const exportBtn = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Export');
    const importBtn = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' }, 'Import');
    const file = h(doc, 'input', { type: 'file', accept: '.json,application/json', hidden: true, 'aria-label': 'Import a log file' });
    const table = h(doc, 'pk-table', { label: 'Log entries', density: 'compact', stickyHeader: true, clickable: true, manual: true, cards: true, maxHeight: '18rem', columns: JSON.stringify(COLUMNS) },
        h(doc, 'pk-empty-state', { slot: 'empty', heading: 'No log entries', tone: 'compact', description: 'Entries appear here as the SDK or your code logs them.' }));
    const detail = h(doc, 'div', { class: 'lg-detail', hidden: true });

    const root = h(doc, 'section', { class: 'lg-module', 'aria-label': 'Logs' },
        h(doc, 'pk-stack', { gap: 'sm' },
            h(doc, 'pk-cluster', {}, search, levels, scopeSelect),
            h(doc, 'pk-cluster', {}, ...VIEW_LEVELS.map(v => badges[v]), status),
            h(doc, 'pk-cluster', {}, pause, order, clear, copy, exportBtn, importBtn, file),
            table, detail));
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.setProperty('height', height === 'fill' ? '100%' : height); root.style.setProperty('overflow', 'auto'); }
    container.replaceChildren(root);
    loadElements(root).catch(() => { /* loadElements logs its own failures */ });

    // ---- drawing --------------------------------------------------------------------------------------------------------------
    const setAttr = (el, k, v) => { if (el.getAttribute(k) !== v) el.setAttribute(k, v); };
    const shown = () => filterLogEntries(entries, { minLevel, scopes, text });

    function drawScopes() {
        const all = scopesOf(entries, scopes);
        const key = all.join('\n');
        if (key === drawnScopes) return;
        drawnScopes = key;
        scopeSelect.replaceChildren(...all.map(s => h(doc, 'option', { value: s, selected: scopes.includes(s) }, s)));
        if (all.length) scopeSelect.setAttribute('value', scopes.join(','));
    }

    function drawDetail() {
        const entry = entries.find(e => e.id === selected);
        if (!entry) { detail.hidden = true; detail.replaceChildren(); return; }
        const d = describeDetail(entry.detail);
        const route = routeOf(entry, getLoggingConfig());
        const close = h(doc, 'pk-button', { size: 'mini', variant: 'ghost', slot: 'actions' }, 'Close');
        close.addEventListener('click', () => api.select(null));
        const facts = `${formatTime(entry.at)}, scope ${entry.scope}${route.below ? `, below the ${route.needed} level so not sent to any output` : ''}${entry.imported ? ', imported' : ''}`;
        const card = h(doc, 'pk-card', { heading: `${LEVEL_LABEL[entry.level]}: ${entry.scope}`, level: 4 }, close,
            h(doc, 'pk-stack', { gap: 'xs' },
                h(doc, 'span', { class: 'muted' }, facts),
                h(doc, 'p', { class: 'lg-message' }, entry.message),
                d.kind === 'none' ? null : h(doc, 'pk-code-block', { label: d.kind === 'error' ? 'Error stack' : d.kind === 'text' ? 'Detail' : 'Detail (JSON)', wrap: true, maxHeight: '14rem' }, d.text)));
        detail.replaceChildren(card);
        detail.hidden = false;
        loadElements(detail).catch(() => { /* loadElements logs its own failures */ });
    }

    function render() {
        if (paused) { status.textContent = `Paused, ${entries.length} kept`; return; }
        const config = getLoggingConfig();
        const list = shown();
        const counts = countLevels(entries);
        for (const v of VIEW_LEVELS) badges[v].textContent = `${LEVEL_LABEL[v]} ${counts[v]}`;
        const ordered = newestFirst ? list.slice().reverse() : list;
        setAttr(table, 'rows', JSON.stringify(ordered.map(e => rowFor(e, config))));
        status.textContent = `${list.length} of ${entries.length} shown${note ? `. ${note}` : ''}`;
        drawScopes();
        if (selected !== null) drawDetail();
    }
    let queued = 0;
    const schedule = () => { if (!queued) queued = win.setTimeout(() => { queued = 0; render(); }, 100); };

    // ---- the feed: the buffer first, then the live sink --------------------------------------------------------------------------
    const add = entry => { entries = pushLog(entries, { ...entry, id: nextId++ }, max); schedule(); };
    for (const entry of getLogBuffer()) entries = pushLog(entries, { ...entry, id: nextId++ }, max);
    const unsink = addLogSink(add);

    // ---- controls -------------------------------------------------------------------------------------------------------------
    search.addEventListener('pk-search', e => { text = e.detail.value ?? ''; render(); });
    levels.addEventListener('pk-toggle', e => {
        const b = e.target.closest('pk-button');
        if (b?.getAttribute('value') && (e.detail?.pressed ?? true)) { minLevel = b.getAttribute('value'); render(); }
    });
    scopeSelect.addEventListener('pk-value-change', e => { scopes = String(e.detail.value ?? '').split(',').filter(Boolean); drawnScopes = ''; render(); });
    pause.addEventListener('pk-toggle', e => (e.detail?.pressed ? api.pause() : api.resume()));
    order.addEventListener('pk-toggle', e => { newestFirst = Boolean(e.detail?.pressed); render(); });
    clear.addEventListener('click', () => api.clear());
    table.addEventListener('pk-row-click', e => api.select(Number(e.detail?.id)));
    copy.addEventListener('click', async () => {
        try { await win.navigator.clipboard.writeText(serializeEntries(shown())); note = 'Copied as JSON'; } catch { note = 'Copy was blocked by the browser'; }
        render();
    });
    exportBtn.addEventListener('click', () => {
        const url = win.URL.createObjectURL(new win.Blob([serializeEntries(shown())], { type: 'application/json' }));
        const a = h(doc, 'a', { href: url, download: `plainkit-log-${new Date().toISOString().replace(/[:.]/g, '-')}.json` });
        doc.body.append(a); a.click(); a.remove();
        win.setTimeout(() => win.URL.revokeObjectURL(url), 1000);
    });
    importBtn.addEventListener('click', () => file.click());
    file.addEventListener('change', async () => {
        const chosen = file.files?.[0];
        file.value = '';
        if (!chosen) return;
        const result = parseImport(await chosen.text());
        if (result.error) note = result.error;
        else {
            const merged = mergeEntries(entries, result.entries, nextId, max);
            entries = merged.entries; nextId = merged.nextId;
            note = `Imported ${result.entries.length}${result.skipped ? `, skipped ${result.skipped}` : ''}`;
        }
        render();
    });
    // The console level can change in the Logging panel or in code: the Output column follows within a moment.
    const timer = win.setInterval(() => { if (!paused && entries.length) render(); }, 3000);

    render();
    const api = {
        pause() { paused = true; pause.setAttribute('pressed', ''); render(); },
        resume() { paused = false; pause.removeAttribute('pressed'); render(); },
        isPaused: () => paused,
        clear() { entries = []; selected = null; note = ''; drawnScopes = ''; clearLogBuffer(); detail.hidden = true; detail.replaceChildren(); if (paused) api.resume(); else render(); },
        entries: () => entries.slice(),
        select(id) { selected = Number.isFinite(id) && entries.some(e => e.id === id) ? id : null; drawDetail(); },
        filter(next = {}) {
            if (VIEW_LEVELS.includes(next.level)) { minLevel = next.level; levels.querySelectorAll('pk-button').forEach(b => (b.getAttribute('value') === minLevel ? b.setAttribute('pressed', '') : b.removeAttribute('pressed'))); }
            if (Array.isArray(next.scopes)) { scopes = [...next.scopes]; drawnScopes = ''; }
            if (typeof next.text === 'string') { text = next.text; search.setAttribute('value', text); }
            render();
        },
        destroy() { unsink(); win.clearInterval(timer); win.clearTimeout(queued); root.remove(); },
    };
    return api;
}

/* Performance monitor chrome. Everything inside is SDK components; this only paints a mounted monitor that carries its own theme. */

.pf-module[data-theme] { color: var(--color-text); background: var(--color-bg); padding: var(--space-3); }

.pf-module > * + * { margin-top: var(--space-3); }

// The performance monitor as a module: mountPerformance(container, options) shows how the page is doing right now: the Core Web Vitals
// (LCP, CLS, INP, FCP, TTFB), a live frame rate, main-thread long tasks, DOM size, JS heap and what the page loaded. It observes the
// browser's own performance APIs, adds no dependency and makes no network request. Built only from SDK components (pk-stat, pk-table,
// pk-button, pk-card, pk-cluster); nothing here draws its own widgets.
//
//   const perf = await mountPerformance(el, { interval: 1000, history: 60, theme: 'dark', height: '32rem' });
//   perf.snapshot();   // the numbers as an object
//
// Options: target (the document to watch; default the container's), interval (ms between updates, default 1000), history (samples kept
// for the sparklines, default 60), autostart (default true), theme ('dark' | 'light'), height (any CSS length, or 'fill'), onsample (called with each snapshot).
// Returns { start(), stop(), running(), snapshot(), destroy() }. Pure maths lives in js/perf-logic.js. Metrics a browser does not
// expose (INP and heap outside Chromium, for one) show a dash rather than a guess.

import { rate, rateFps, fpsFrom, pushSample, clsFrom, inpFrom, longTaskStats, summarizeResources, formatBytes, formatMs, shortName } from '../../js/perf-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { createLogger } from '../../js/log.js';
const log = createLogger('performance');

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./performance.css'];

export const DEFAULTS = Object.freeze({ interval: 1000, history: 60 });

const TONES = { good: 'positive', warn: 'warning', poor: 'critical', '': 'neutral' };

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

// Watches one performance entry type; a browser that lacks it is skipped without complaint.
function observe(win, type, onEntries, extra = {}) {
    try {
        const po = new win.PerformanceObserver(list => onEntries(list.getEntries()));
        po.observe({ type, buffered: true, ...extra });
        return po;
    } catch (error) { log.debug(`the ${type} performance entry type is not supported in this browser`, error); return null; }
}

// The data side: performance observers plus a frame counter. Nothing here touches the page's markup.
export function collect(win, doc, { history = DEFAULTS.history } = {}) {
    const s = { lcp: null, fcp: null, ttfb: null, layoutShifts: [], events: [], longTasks: [], resources: [], frames: [], fps: [], heap: [], nodes: [], raf: 0, running: false };
    const observers = [];
    const nav = win.performance.getEntriesByType?.('navigation')?.[0];
    if (nav && nav.responseStart > 0) s.ttfb = Math.round(nav.responseStart);
    observers.push(
        observe(win, 'largest-contentful-paint', es => { s.lcp = Math.round(es.at(-1).startTime); }),
        observe(win, 'paint', es => { const f = es.find(e => e.name === 'first-contentful-paint'); if (f) s.fcp = Math.round(f.startTime); }),
        observe(win, 'layout-shift', es => s.layoutShifts.push(...es.map(e => ({ startTime: e.startTime, value: e.value, hadRecentInput: e.hadRecentInput })))),
        observe(win, 'event', es => s.events.push(...es.map(e => ({ interactionId: e.interactionId, duration: e.duration }))), { durationThreshold: 40 }),
        observe(win, 'longtask', es => s.longTasks.push(...es.map(e => ({ duration: e.duration })))),
        observe(win, 'resource', es => s.resources.push(...es.map(e => ({ name: e.name, duration: e.duration, transferSize: e.transferSize, initiatorType: e.initiatorType })))),
    );

    const frame = t => {
        if (!s.running) return;
        s.frames.push(t);
        while (s.frames.length && s.frames[0] < t - 2000) s.frames.shift();
        s.raf = win.requestAnimationFrame(frame);
    };

    return {
        start() { if (s.running) return; s.running = true; s.frames = []; s.raf = win.requestAnimationFrame(frame); },
        stop() { s.running = false; win.cancelAnimationFrame(s.raf); },
        running: () => s.running,
        // Takes a sample (fps, heap and DOM size) and returns everything as one object.
        sample() {
            const now = s.frames.at(-1) ?? 0;
            const fps = s.running && !doc.hidden ? fpsFrom(s.frames, now) : null;
            const heap = win.performance.memory?.usedJSHeapSize ?? null;
            const nodes = doc.getElementsByTagName('*').length;
            if (fps !== null) s.fps = pushSample(s.fps, fps, history);
            if (heap !== null) s.heap = pushSample(s.heap, heap, history);
            s.nodes = pushSample(s.nodes, nodes, history);
            return this.snapshot(fps, heap, nodes);
        },
        snapshot(fps = s.fps.at(-1) ?? null, heap = s.heap.at(-1) ?? null, nodes = s.nodes.at(-1) ?? null) {
            return {
                lcp: s.lcp, fcp: s.fcp, ttfb: s.ttfb, cls: Math.round(clsFrom(s.layoutShifts) * 1000) / 1000, inp: inpFrom(s.events),
                fps, heap, nodes, longTasks: longTaskStats(s.longTasks), resources: summarizeResources(s.resources),
                series: { fps: s.fps, heap: s.heap, nodes: s.nodes },
            };
        },
        destroy() { this.stop(); for (const o of observers) o?.disconnect(); },
    };
}

export async function mountPerformance(container, options = {}) {
    log.debug('mounted', { module: 'performance', options: Object.keys(options) });
    const { theme, height, autostart = true, interval = DEFAULTS.interval, history = DEFAULTS.history, onsample } = options;
    const doc = container.ownerDocument;
    const win = options.target?.defaultView ?? doc.defaultView;
    const watched = options.target ?? doc;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    const stats = Object.fromEntries([['lcp', 'LCP'], ['inp', 'INP'], ['cls', 'CLS'], ['fcp', 'FCP'], ['ttfb', 'TTFB'], ['fps', 'Frame rate'], ['tasks', 'Long tasks'], ['nodes', 'DOM nodes'], ['heap', 'JS heap']]
        .map(([key, label]) => [key, h(doc, 'pk-stat', { label, tile: true })]));
    const toggle = h(doc, 'pk-button', { size: 'mini', variant: 'ghost' });
    const status = h(doc, 'span', { class: 'muted', role: 'status' });
    const kinds = h(doc, 'p', { class: 'muted' });
    const resources = h(doc, 'pk-table', { label: 'Slowest requests', density: 'compact', columns: JSON.stringify([{ key: 'name', label: 'Request' }, { key: 'time', label: 'Time', align: 'end' }, { key: 'size', label: 'Size', align: 'end' }]) });
    const root = h(doc, 'section', { 'aria-label': 'Performance monitor', class: 'pf-module' },
        h(doc, 'pk-cluster', {}, h(doc, 'h2', {}, 'Performance'), toggle, status),
        h(doc, 'pk-cluster', { align: 'stretch' }, ...Object.values(stats)),
        h(doc, 'pk-card', { heading: 'What loaded', level: 3 }, kinds, resources));
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.setProperty('height', height === 'fill' ? '100%' : height); root.style.setProperty('overflow', 'auto'); }
    container.replaceChildren(root);
    loadElements(root);

    const c = collect(win, watched, { history });
    let timer = 0;
    let last = null;
    let rowsKey = '';

    const set = (el, { value, tone = '', subtext = '', values }) => {
        el.setAttribute('value', value); el.setAttribute('tone', TONES[tone] ?? 'neutral'); el.setAttribute('subtext', subtext);
        if (values && values.length > 1) el.setAttribute('values', JSON.stringify(values)); else el.removeAttribute('values');
    };

    function draw(snap) {
        last = snap;
        const limit = win.performance.memory?.jsHeapSizeLimit;
        const heapShare = snap.heap !== null && limit ? snap.heap / limit : null;
        set(stats.lcp, { value: snap.lcp === null ? '-' : formatMs(snap.lcp), tone: rate('lcp', snap.lcp), subtext: 'Largest paint, good up to 2.5 s' });
        set(stats.inp, { value: snap.inp === null ? '-' : formatMs(snap.inp), tone: rate('inp', snap.inp), subtext: 'Slowest interaction, good up to 200 ms' });
        set(stats.cls, { value: snap.cls.toFixed(3), tone: rate('cls', snap.cls), subtext: 'Layout shift, good up to 0.1' });
        set(stats.fcp, { value: snap.fcp === null ? '-' : formatMs(snap.fcp), tone: rate('fcp', snap.fcp), subtext: 'First paint, good up to 1.8 s' });
        set(stats.ttfb, { value: snap.ttfb === null ? '-' : formatMs(snap.ttfb), tone: rate('ttfb', snap.ttfb), subtext: 'First byte, good up to 0.8 s' });
        set(stats.fps, { value: snap.fps === null ? '-' : `${snap.fps} fps`, tone: rateFps(snap.fps), subtext: c.running() ? 'Live' : 'Paused', values: snap.series.fps });
        set(stats.tasks, { value: String(snap.longTasks.count), tone: rate('longTask', snap.longTasks.worst), subtext: `${snap.longTasks.blocking} ms blocking, worst ${snap.longTasks.worst} ms` });
        set(stats.nodes, { value: String(snap.nodes ?? '-'), subtext: 'Elements in the document', values: snap.series.nodes });
        set(stats.heap, { value: snap.heap === null ? 'n/a' : formatBytes(snap.heap), tone: heapShare === null ? '' : heapShare < 0.5 ? 'good' : heapShare < 0.8 ? 'warn' : 'poor', subtext: snap.heap === null ? 'Not exposed by this browser' : 'Used (Chromium only)', values: snap.series.heap });
        const r = snap.resources;
        kinds.textContent = `${r.count} requests, ${formatBytes(r.bytes)}. ${Object.entries(r.byType).map(([t, b]) => `${t} ${b.count}`).join(', ')}`;
        const rows = r.slowest.map((x, i) => ({ id: i + 1, name: shortName(x.name), time: formatMs(x.duration), size: formatBytes(x.bytes) }));
        const key = JSON.stringify(rows);
        if (key !== rowsKey) { rowsKey = key; resources.setAttribute('rows', key); }
        onsample?.(snap);
    }

    const tick = () => draw(c.sample());
    const paintButton = () => { const on = c.running(); toggle.textContent = on ? 'Pause' : 'Resume'; status.textContent = on ? `Updating every ${interval / 1000} s` : 'Paused'; };
    function start() { c.start(); win.clearInterval(timer); timer = win.setInterval(tick, interval); paintButton(); }
    function stop() { c.stop(); win.clearInterval(timer); timer = 0; paintButton(); if (last) draw(last); }
    toggle.addEventListener('click', () => (c.running() ? stop() : start()));

    draw(c.snapshot());
    paintButton();
    if (autostart) start();
    return {
        start, stop, running: c.running, snapshot: () => c.sample(),
        destroy() { win.clearInterval(timer); c.destroy(); root.remove(); },
    };
}

// The quality checks as a module: mountQuality(container, options) runs the SDK's own page checks (js/quality.js: accessibility, layout,
// spacing, touch targets on a phone, nested scrollers, literal colours, focus indicators) on a live page and shows a score and every
// finding. It is standalone (put it anywhere) and it is the Quality tab of the dev tools. Built only from SDK components (pk-stat,
// pk-table, pk-button); it draws nothing itself.
//
//   const q = await mountQuality(el, { autorun: true });          // checks the page the container is in
//   const r = await q.run();                                      // { score, findings, width }
//
// Options: root (the element or document to check; default the container's document body), around (a function that receives a callback
// and runs it with anything that must not be measured hidden; default hides the module itself, and the dev tools pass their own so the
// dock is left out too), phone (force the phone checks on or off; default on when the window is 640px wide or less), autorun, theme,
// height (any CSS length), onresult (called with each result). Returns { run(), results(), destroy() }. Scoring and rows are in
// js/inspect-logic.js. This is a different thing from the Scorecard: the scorecard scores many targets and the framework; this checks the
// page you are on, right now.

import { collect, evaluate, focusProblems } from '../../js/quality.js';
import { pageScore, scoreTone, findingRows } from '../../js/inspect-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { createLogger } from '../../js/log.js';
const log = createLogger('quality');

const STYLES = ['../../plainkit.css'];
export const PHONE_MAX = 640;

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

// Runs the checks now on `root` and returns { score, findings, width }. Synchronous, so a hidden tool never flickers.
export function checkPage(root, { phone } = {}) {
    const doc = root.ownerDocument ?? root;
    const win = doc.defaultView;
    const target = root.querySelectorAll ? root : doc.body;
    const isPhone = phone ?? win.innerWidth <= PHONE_MAX;
    const findings = [...evaluate(collect(target), { phone: isPhone }), ...focusProblems(target)];
    return { score: pageScore(findings), findings, width: win.innerWidth };
}

export async function mountQuality(container, options = {}) {
    log.debug('mounted', { module: 'quality', options: Object.keys(options) });
    const { theme, height, autorun, onresult } = options;
    const doc = container.ownerDocument;
    const win = doc.defaultView;
    await ensureStyles(styleUrls(STYLES, import.meta.url), doc);

    const run = h(doc, 'pk-button', { size: 'mini', variant: 'primary' }, 'Check this page');
    const status = h(doc, 'span', { class: 'muted', role: 'status' }, 'Not run yet');
    const score = h(doc, 'pk-stat', { label: 'Page score', value: '-', tile: true, subtext: 'Accessibility, layout, spacing, touch targets and focus' });
    const table = h(doc, 'pk-table', {
        label: 'Findings', density: 'compact', stickyHeader: true, maxHeight: '16rem',
        columns: JSON.stringify([{ key: 'severity', label: 'Severity' }, { key: 'check', label: 'Check' }, { key: 'selector', label: 'Where' }, { key: 'message', label: 'What is wrong' }, { key: 'count', label: 'Times', align: 'end' }]),
    });
    const root = h(doc, 'section', { class: 'ql-module', 'aria-label': 'Quality checks' },
        h(doc, 'pk-cluster', {}, run, status), h(doc, 'div', { class: 'u-mt-3' }, score), h(doc, 'div', { class: 'u-mt-3' }, table));
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.setProperty('height', height); root.style.setProperty('overflow', 'auto'); }
    container.replaceChildren(root);
    loadElements(root);

    // What must not be measured: the module itself unless the host says otherwise (the dev tools hide their whole dock).
    const around = options.around ?? (fn => { const before = root.hidden; root.hidden = true; try { return fn(); } finally { root.hidden = before; } });
    let last = null;

    function check() {
        const target = options.root ?? doc.body;
        last = around(() => checkPage(target, { phone: options.phone }));
        const rows = findingRows(last.findings);
        score.setAttribute('value', String(last.score));
        score.setAttribute('tone', scoreTone(last.score));
        table.setAttribute('rows', JSON.stringify(rows));
        status.textContent = rows.length ? `${rows.length} finding${rows.length === 1 ? '' : 's'} at ${last.width}px wide` : `No findings at ${last.width}px wide`;
        onresult?.(last);
        return last;
    }
    run.addEventListener('click', check);
    if (autorun) check();
    return { run: async () => check(), results: () => last, destroy() { run.removeEventListener('click', check); root.remove(); } };
}

// What the scorecard measures in a real browser beyond the rendered frames: the page's own timings (largest paint, layout shift, long
// tasks, slowest interaction), how long a table of N rows takes to lay out, how long a theme switch takes to restyle, and the size of
// files (raw and gzip). Every read is of a file the host names on its own origin; nothing else is requested.

import { stripComments, sameOrigin } from '../../js/framework-checks.js';
import { createLogger } from '../../js/log.js';

const log = createLogger('scorecard');

// Timings collected from page load (buffered observers), so the numbers describe the page as it loaded. Returns the live object.
export function watchVitals(win) {
    const v = { lcp: null, cls: 0, longTasks: 0, inp: 0 };
    const observe = (type, fn, extra = {}) => {
        try { new win.PerformanceObserver(l => l.getEntries().forEach(fn)).observe({ type, buffered: true, ...extra }); } catch (error) { log.debug(`the ${type} entry type is not supported in this browser: the metric stays unmeasured`, error); }
    };
    observe('largest-contentful-paint', e => { v.lcp = e.startTime; });
    observe('layout-shift', e => { if (!e.hadRecentInput) v.cls += e.value; });
    observe('longtask', () => { v.longTasks++; });
    observe('event', e => { v.inp = Math.max(v.inp, e.duration); }, { durationThreshold: 16 });
    return v;
}

// Render and lay out a pk-table of n product rows off-screen, in ms. The status cell is plain text: the test times the table, not n badge elements.
export function timeRows(doc, n) {
    const host = doc.createElement('div');
    host.style.cssText = 'position:absolute;left:-10000px;top:0;width:900px';
    doc.body.append(host);
    const rows = Array.from({ length: n }, (_, i) => `<tr><td><code>SKU-${i}</code></td><td>Title of product ${i}</td><td>Active</td><td class="num">$${(i % 90) + 9}.99</td></tr>`).join('');
    const t0 = performance.now();
    host.innerHTML = `<pk-table density="compact"><table><thead><tr><th>SKU</th><th>Title</th><th>Status</th><th class="num">Price</th></tr></thead><tbody>${rows}</tbody></table></pk-table>`;
    host.offsetHeight; // force layout
    doc.defaultView.getComputedStyle(host.querySelector('tbody tr:last-child td')).color;
    const ms = performance.now() - t0;
    host.remove();
    return ms;
}

// Flip the theme and re-read every element's colour: the style recalculation cost of a theme switch, in ms. The theme is put back.
export function recalcMs(doc) {
    const root = doc.documentElement;
    const was = root.getAttribute('data-theme');
    const t0 = performance.now();
    root.setAttribute('data-theme', was === 'dark' ? 'light' : 'dark');
    doc.querySelectorAll('*').forEach(el => doc.defaultView.getComputedStyle(el).color);
    const ms = performance.now() - t0;
    if (was === null) root.removeAttribute('data-theme'); else root.setAttribute('data-theme', was);
    return ms;
}

// { name: url } becomes { name: text }. Only URLs of the page's own origin are read.
export async function readTexts(map, doc = document, fetchFn = globalThis.fetch) {
    const own = url => { if (!sameOrigin(url, doc.baseURI)) throw new Error(`${url}: not the page's own origin`); return url; };
    return Object.fromEntries(await Promise.all(Object.entries(map ?? {}).map(async ([name, url]) => {
        const res = await fetchFn(own(url));
        if (!res.ok) throw new Error(`${url}: ${res.status}`);
        return [name, await res.text()];
    })));
}

// Gzip size in bytes through the browser's own CompressionStream; null where the browser lacks it.
export async function gzipBytes(text) {
    if (typeof CompressionStream === 'undefined') return null;
    return (await new Response(new Blob([text]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer()).byteLength;
}

// Sizes for [{ name, url | urls, budget, strip }]: the files are joined in order (comments stripped when `strip`), then measured raw and gzip.
export async function measureSizes(entries, doc = document, fetchFn = globalThis.fetch) {
    return Promise.all((entries ?? []).map(async e => {
        const urls = [].concat(e.url ?? e.urls ?? []);
        const parts = await readTexts(Object.fromEntries(urls.map((u, i) => [i, u])), doc, fetchFn);
        let text = urls.map((_u, i) => parts[i]).join('');
        if (e.strip) text = stripComments(text);
        const gz = await gzipBytes(text);
        return { name: e.name, budget: e.budget, rawKb: text.length / 1024, gzKb: gz === null ? null : gz / 1024 };
    }));
}

/* Scorecard chrome. Tokens only. */

/* A mounted scorecard with its own theme paints itself, so the host page's colours do not leak in. */
.sc-module[data-theme] { color: var(--color-text); background: var(--color-bg); padding: var(--space-3); }

.sc-scores { display: grid; grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); gap: var(--space-3); margin: var(--space-3) 0; }

/* The framework sections are pk-cards; a table or tab strip inside one sits flush with the body and the sparkline tiles keep a tidy grid. */
.sc-module pk-tabs { display: block; }

.sc-module pk-table + *, .sc-module pk-cluster + * { margin-top: var(--space-3); }

.sc-tile-big { grid-column: 1 / -1; }

.sc-good { color: var(--stat-card-positive-fg); }

.sc-warn { color: var(--stat-card-warning-fg); }

.sc-bad { color: var(--stat-card-critical-fg); }

.sc-section { margin-top: var(--space-4); }

.sc-table td, .sc-table th { overflow-wrap: anywhere; }

.sc-table td:first-child { min-width: 8rem; }

.sc-table td:last-child { min-width: 14rem; }

.sc-table th.num { overflow-wrap: normal; white-space: nowrap; }

.sc-frames { position: fixed; left: -10000px; top: 0; width: 1280px; height: 700px; overflow: hidden; visibility: hidden; }

.sc-frames iframe { border: 0; }

.sc-progress { margin: var(--space-3) 0; }

// The scorecard as a module: mountScorecard(container, options) renders every target at every theme and width, runs the SDK's quality
// checks (accessibility, layout, spacing, touch targets, focus) on each, scores each target 0-100 and ranks them worst first. Optional
// sections add the framework-level checks, so one module serves a page, a set of pages or the whole framework.
//
//   const card = await mountScorecard(el, { targets: ['/', '/pricing.html', { name: 'Card', html: '<div class="card">...</div>' }], checks: ['accessibility'] });
//   await mountScorecard(el, { sections: ['security', 'api', 'size'], data: { security: '/security-report.json', apiBaseline: '/api.baseline.json', api: '/api.current.json', budgets, sizes } });
//
// Options: targets (required for the ranked and performance sections; a URL string, { name, url } for a page of the same origin,
// { name, html } for markup rendered with the SDK stylesheets, { name, srcdoc } for a whole document, or { name, samples: [...] } for
// several frames scored as one), checks (keep only findings whose check or category is listed, e.g. ['accessibility', 'touch-target'];
// default all), themes (default dark and light), widths (default 375 and 1024), historyKey (a localStorage key: keeps the runs and shows
// the change since the last), historyMax (runs kept, default 40), autorun, theme, height, link (item => href for a ranked name).
// sections: which parts to show, from ranked, performance, size, api, sweep, security, history; default ['ranked'], which is the
// scorecard as it always was.
//   ranked       the score and every target worst first (needs a run)
//   performance  scored categories (performance, scale, look, accessibility) with their metrics and stylesheets (a run; needs data.scoring)
//   size         gzip size of built files against their budgets (data.sizes, data.budgets)
//   api          the API surface against the previous release: what was removed or added (data.apiBaseline, data.api)
//   sweep        the last full size sweep (data.sweep)
//   security     security and defect findings (data.security; fileLink(file, line) makes the place a link)
//   history      the kept runs, with export, import and clear (needs historyKey)
// data: each entry is a URL of the host's own origin (a relative URL is read against the page) or the parsed object. A section whose data
// is missing says so with an empty state. security, apiBaseline, api, sweep, budgets, scoring (the scoring definitions), sizes (a list of
// { name, url | urls, budget, strip }), files ({ css: { name: url }, js: { name: url }, tokens: name, pairs, frame, unusedIn }).
// extraItems({ host }) may return more ranked items (a check the host runs itself).
// Returns { run(), results(), report(), ready, destroy() }. runTargets, openFrame and rankedTable are exported for a host page that wants
// to draw its own view. Quality checks are js/quality.js, scoring is js/scoring.js, both unchanged; the pure section logic is
// js/framework-checks.js. Nothing is requested but the module's own files and the data files named above.

import { collect, evaluate, focusProblems, unusedSelectors } from '../../js/quality.js';
import { scoreFindings, rankWorstFirst, groupFindings, scoreAll, readHistory, pushRun, deltas, exportHistory, importHistory } from '../../js/scoring.js';
import { staticMetrics } from '../../js/audit.js';
import { ensureStyles, styleUrls, loadJson } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { createLogger } from '../../js/log.js';
const log = createLogger('scorecard');
import { sameOrigin } from '../../js/framework-checks.js';
import { watchVitals, timeRows, recalcMs, readTexts, measureSizes } from './measure.js';
import { h, card, missing, scoreTile, scoreTiles, emptyState, categoryTabs, paintSize, paintApi, paintSweep, paintSecurity, paintHistory, note } from './sections.js';

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./scorecard.css'];

export const DEFAULTS = Object.freeze({ themes: ['dark', 'light'], widths: [375, 1024], penalty: { error: 25, warn: 8 }, concurrency: 8, settleMs: 120 });
export const SECTIONS = Object.freeze(['ranked', 'performance', 'size', 'api', 'sweep', 'security', 'history']);

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const slug = s => String(s).replace(/\W+/g, '-').replace(/^-|-$/g, '').toLowerCase();
export const tone = s => (s === null || s === undefined ? '' : s >= 80 ? 'sc-good' : s >= 55 ? 'sc-warn' : 'sc-bad');
export const fmtDelta = d => (d === null || d === undefined ? '' : d === 0 ? '<span class="muted">±0</span>' : `<span class="${d > 0 ? 'sc-good' : 'sc-bad'}">${d > 0 ? '+' : ''}${d}</span>`);

// Targets in any of the accepted shapes become { id, name, kind, frames: [{ url } | { html } | { srcdoc }] }; entries with nothing to render are dropped.
export function normalizeTargets(targets) {
    return (Array.isArray(targets) ? targets : []).map((t, i) => {
        const o = typeof t === 'string' ? { url: t } : (t ?? {});
        const frames = (o.samples ?? [o]).map(f => (typeof f === 'string' ? { url: f } : f)).filter(f => f && (f.url || f.html !== undefined || f.srcdoc));
        const name = o.name ?? o.url ?? `Target ${i + 1}`;
        return { id: o.id ?? (slug(name) || `target-${i + 1}`), name, kind: o.kind ?? '', frames };
    }).filter(t => t.frames.length);
}

// Findings whose check name or category is in `checks`; an empty or missing list keeps everything.
export const keepChecks = (findings, checks) => (checks?.length ? findings.filter(f => checks.includes(f.check) || checks.includes(f.category)) : findings);

const docFor = (frame, { theme, width }, base) => {
    if (frame.srcdoc) return typeof frame.srcdoc === 'function' ? frame.srcdoc({ theme, width }) : frame.srcdoc;
    const sheets = styleUrls(STYLES, base).map(h => `<link rel="stylesheet" href="${esc(h)}">`).join('');
    return `<!doctype html><html lang="en" data-theme="${theme}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">${sheets}</head><body>${frame.html}</body></html>`;
};

// A frame laid out off-screen at an exact width, resolved once loaded and settled; the caller measures it and removes it.
export function openFrame(host, frame, { theme = 'dark', width = 1280, settleMs = DEFAULTS.settleMs, base = import.meta.url } = {}) {
    return new Promise(resolve => {
        const f = host.ownerDocument.createElement('iframe');
        f.style.cssText = `position:absolute;left:0;top:0;width:${width}px;height:700px;border:0`;
        f.addEventListener('load', () => {
            if (frame.url) try { f.contentDocument.documentElement.setAttribute('data-theme', theme); } catch (error) { log.debug('could not set the theme in a frame from another origin', error); }
            setTimeout(() => resolve(f), settleMs);
        }, { once: true });
        if (frame.url) f.src = frame.url; else f.srcdoc = docFor(frame, { theme, width }, base);
        host.append(f);
    });
}

async function pool(jobs, size, onDone) {
    let next = 0; let done = 0;
    await Promise.all(Array.from({ length: size }, async () => {
        while (next < jobs.length) { const job = jobs[next++]; await job(); onDone?.(++done, jobs.length); }
    }));
}

function measure(frame, phone, focus) {
    const doc = frame.contentDocument;
    if (!doc?.body) return [{ check: 'unreadable', category: 'look', severity: 'error', selector: 'document', message: 'the page could not be read (another origin, or it failed to load)' }];
    return [...evaluate(collect(doc.body), { phone }), ...(focus ? focusProblems(doc.body) : [])];
}

// Score every target: [{ id, name, kind, findings (grouped), score }] in the order given.
export async function runTargets(targets, { host, themes = DEFAULTS.themes, widths = DEFAULTS.widths, checks, penalty = DEFAULTS.penalty, concurrency = DEFAULTS.concurrency, onProgress, base } = {}) {
    const list = normalizeTargets(targets);
    const results = new Map(list.map(t => [t.id, { target: t, findings: [] }]));
    const widest = Math.max(...widths);
    const jobs = [];
    for (const t of list) for (const frame of t.frames) for (const theme of themes) for (const width of widths) jobs.push(async () => {
        const f = await openFrame(host, frame, { theme, width, base });
        try { for (const x of measure(f, width <= 640, theme === themes[0] && width === widest)) results.get(t.id).findings.push({ ...x, context: `${theme} ${width}px` }); } finally { f.remove(); }
    });
    await pool(jobs, concurrency, onProgress);
    return list.map(t => {
        const findings = groupFindings(keepChecks(results.get(t.id).findings, checks));
        return { id: t.id, name: t.name, kind: t.kind, findings, score: scoreFindings(findings, penalty) };
    });
}

const chips = findings => (findings.length
    ? findings.slice(0, 6).map(f => `<pk-badge variant="${f.severity === 'error' ? 'danger' : 'warn'}" title="${esc(f.selector)}: ${esc(f.message)} (${esc(f.contexts.join(', '))})">${esc(f.check)}${f.count > 1 ? ` x${f.count}` : ''}</pk-badge>`).join(' ') + (findings.length > 6 ? ` <span class="muted">+${findings.length - 6} more</span>` : '')
    : '<span class="muted">none</span>');

// The ranked table, worst first. changes: [{ name, delta }] from scoring.deltas; link(item) gives the name a link target (or nothing).
export function rankedTable(items, { changes = [], link, label = 'Target' } = {}) {
    const rows = rankWorstFirst(items).map(i => {
        const href = link?.(i);
        const name = href ? `<a href="${esc(href)}">${esc(i.name)}</a>` : esc(i.name);
        return `<tr><td>${name}${i.kind ? ` <span class="muted u-text-xs">${esc(i.kind)}</span>` : ''}</td><td class="num ${tone(i.score)}">${i.score}</td><td class="num">${fmtDelta(changes.find(x => x.name === i.name)?.delta)}</td><td>${chips(i.findings)}</td></tr>`;
    });
    return `<pk-table label="${esc(label)} ranking" density="compact"><table class="sc-table"><thead><tr><th>${esc(label)}</th><th class="num">Score</th><th class="num">Change</th><th>Failing items</th></tr></thead><tbody>${rows.join('')}</tbody></table></pk-table>`;
}

const storage = { getItem: k => { try { return localStorage.getItem(k); } catch (error) { log.debug('storage blocked: no run history is read', error); return null; } }, setItem: (k, v) => { try { localStorage.setItem(k, v); } catch (error) { log.debug('storage blocked: the run is shown but not saved', error); } } };

// Markup the module writes itself (fixed strings and the ranked table, every dynamic value escaped) becomes nodes here, the one sink.
const fromHtml = (doc, markup) => { const t = doc.createElement('template'); t.innerHTML = markup; return t.content; };

const NOT_YET = ['No run yet', 'Press Run scorecard: every target is rendered at each width and theme and checked.'];
const meanScore = items => Math.round(items.reduce((n, i) => n + i.score, 0) / items.length);

export async function mountScorecard(container, options = {}) {
    log.debug('mounted', { module: 'scorecard', options: Object.keys(options) });
    const { targets, theme, height, historyKey, historyMax, autorun, link, fileLink, extraItems } = options;
    const data = options.data ?? {};
    const sections = new Set(options.sections ?? ['ranked']);
    for (const s of sections) if (!SECTIONS.includes(s)) throw new Error(`mountScorecard: unknown section "${s}" (one of ${SECTIONS.join(', ')})`);
    const runs = sections.has('ranked') || sections.has('performance');
    if (runs && !normalizeTargets(targets).length) throw new Error('mountScorecard needs targets: URLs, { name, url }, { name, html } or { name, srcdoc }');
    const doc = container.ownerDocument;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);
    const root = doc.createElement('div');
    root.className = 'sc-module';
    if (theme) root.setAttribute('data-theme', theme);
    if (height) { root.style.height = height; root.style.overflow = 'auto'; }
    root.replaceChildren(...(runs ? [
        h(doc, 'pk-cluster', {}, h(doc, 'pk-button', { 'data-sc-run': true }, 'Run scorecard')),
        h(doc, 'div', { class: 'sc-progress muted', role: 'status', 'aria-live': 'polite', 'data-sc-progress': true }),
        h(doc, 'div', { 'data-sc-result': true }, emptyState(doc, ...NOT_YET))] : []),
        h(doc, 'div', { class: 'sc-frames', 'aria-hidden': 'true', 'data-sc-frames': true }));
    container.replaceChildren(root);
    const $ = s => root.querySelector(s);
    let items = [];
    let last = null;

    // Own-origin data: a URL string is read from the host's origin only; anything else is the value itself.
    const load = async value => {
        if (typeof value === 'string' && !sameOrigin(value, doc.baseURI)) throw new Error(`${value}: data files must be on the page's own origin`);
        return loadJson(value);
    };

    // ---- the sections that need no run: each is a card that fills when its data has loaded --------------------------------
    const hosts = {};
    const heading = { size: 'Size and budgets', api: 'API surface', sweep: 'Size sweep', security: 'Security and defects', history: 'History' };
    for (const name of ['size', 'api', 'sweep', 'security', 'history']) {
        if (!sections.has(name)) continue;
        const body = h(doc, 'div', {}, note(doc, 'Loading…'));
        hosts[name] = body;
        root.insertBefore(card(doc, heading[name], body), $('[data-sc-frames]'));
    }
    const fill = (name, get, paint, hint) => (hosts[name] ? Promise.resolve().then(get).then(v => paint(v)).catch(err => { log.warn(`the ${name} section could not be filled`, err); missing(doc, hosts[name], hint, `${err.message}`); }) : null);
    const paintHist = () => {
        const history = historyKey ? readHistory(storage, historyKey) : [];
        if (!historyKey) return missing(doc, hosts.history, 'history key', 'Pass historyKey: the runs are kept in this browser under it.');
        return load(data.scoring).then(scoring => scoring, () => undefined).then(scoring => paintHistory(doc, hosts.history, {
            history, scoring,
            actions: {
                onExport: () => { const a = doc.createElement('a'); a.href = URL.createObjectURL(new Blob([exportHistory(readHistory(storage, historyKey))], { type: 'application/json' })); a.download = `${historyKey}.json`; a.click(); URL.revokeObjectURL(a.href); },
                onImport: async file => { try { const imported = importHistory(await file.text()); storage.setItem(historyKey, JSON.stringify(imported.slice(-(historyMax ?? 40)))); setProgress(`Imported ${imported.length} runs.`); } catch (err) { log.warn('importing the run history failed', err); setProgress(`The import failed: ${err.message}`); } paintHist(); },
                onClear: () => { storage.setItem(historyKey, '[]'); paintHist(); },
            },
        }));
    };
    const setProgress = text => { const p = $('[data-sc-progress]'); if (p) p.textContent = text; };

    const ready = Promise.all([
        fill('size', async () => ({ sizes: await measureSizes(data.sizes, doc), budgets: await load(data.budgets) }), v => paintSize(doc, hosts.size, v), 'sizes'),
        fill('api', async () => ({ baseline: await load(data.apiBaseline), current: await load(data.api) }), v => paintApi(doc, hosts.api, v), 'API surface'),
        fill('sweep', () => load(data.sweep), v => paintSweep(doc, hosts.sweep, v), 'sweep report'),
        fill('security', () => load(data.security), v => paintSecurity(doc, hosts.security, v, { fileLink }), 'security report'),
        hosts.history ? paintHist() : null,
    ].filter(Boolean)).then(() => loadElements(root));

    // ---- a run: frames, then (performance) the measurements that need a real browser ---------------------------------------
    async function measured(scoring, ranked) {
        const files = data.files ?? {};
        const host = $('[data-sc-frames]');
        setProgress('Reading stylesheets and scripts…');
        const cssFiles = await readTexts(files.css, doc);
        const jsFiles = await readTexts(files.js, doc);
        const stat = staticMetrics({ cssFiles, jsFiles, tokensCss: cssFiles[files.tokens] ?? '', pairs: files.pairs ?? [] });
        let total = 0; let unused = 0;
        if (files.frame) {
            setProgress('Estimating unused selectors…');
            const all = await openFrame(host, files.frame, { theme: 'dark', width: 1280, base: options.base });
            for (const [n, css] of Object.entries(cssFiles)) {
                if (!(files.unusedIn ?? ['base/']).some(p => n.startsWith(p))) continue;
                const u = unusedSelectors(css, [all.contentDocument]); total += u.total; unused += u.unused.length;
            }
            all.remove();
        }
        setProgress('Timing the scale tests…');
        const scale = Object.fromEntries((scoring.scaleRows ?? []).map(n => [`rows${n}Ms`, Math.round(timeRows(doc, n))]));
        const extra = extraItems ? await extraItems({ host }) : [];
        ranked.push(...(extra ?? []));
        const flat = ranked.flatMap(i => i.findings);
        const a11y = flat.filter(f => f.category === 'accessibility');
        const vitals = vitalsOf();
        const m = {
            cssKb: stat.cssKb, jsKb: stat.jsKb, unusedRatio: total ? Math.round(unused / total * 100) / 100 : 0,
            lcpMs: vitals.lcp === null ? null : Math.round(vitals.lcp), cls: Math.round(vitals.cls * 1000) / 1000, longTasks: vitals.longTasks, inpMs: vitals.inp ? Math.round(vitals.inp) : null,
            domNodes: doc.querySelectorAll('*').length, recalcMs: Math.round(recalcMs(doc)),
            ...scale,
            contrastFail: stat.contrastFail, literalColours: stat.literalColours, literalSizes: stat.literalSizes,
            controlScore: meanScore(ranked),
            spacingFindings: flat.filter(f => ['zero-gap', 'tight-controls', 'text-at-edge', 'inconsistent-gaps'].includes(f.check)).length,
            a11yErrors: a11y.filter(f => f.severity === 'error').length, a11yWarnings: a11y.filter(f => f.severity === 'warn').length,
        };
        return { measured: m, scores: scoreAll(scoring, m), perFile: stat.perFile };
    }
    let vitals = null;
    const vitalsOf = () => (vitals ??= watchVitals(doc.defaultView));
    if (sections.has('performance')) vitalsOf();

    async function run() {
        const button = $('[data-sc-run]');
        if (!button) return items;
        button.setAttribute('disabled', '');
        try {
            const perf = sections.has('performance');
            const scoring = perf ? await load(data.scoring) : null;
            if (perf && !scoring) throw new Error('the performance section needs data.scoring');
            setProgress('Rendering every target at every width and theme…');
            items = await runTargets(targets, {
                host: $('[data-sc-frames]'), themes: options.themes ?? scoring?.themes, widths: options.widths ?? scoring?.widths, penalty: options.penalty ?? scoring?.findingPenalty,
                checks: options.checks, concurrency: options.concurrency, base: options.base, onProgress: (d, n) => setProgress(`Checking ${d}/${n}…`),
            });
            const report = perf ? await measured(scoring, items) : null;
            const overall = report ? report.scores.overall : meanScore(items);
            let changes = []; let d = { overall: null, categories: {}, items: [] }; let history = [];
            if (historyKey) {
                history = pushRun(storage, historyKey, {
                    at: new Date().toISOString(), overall,
                    categories: report ? Object.fromEntries(Object.entries(report.scores.categories).map(([k, c]) => [k, c.score])) : {},
                    items: Object.fromEntries(items.map(i => [i.name, i.score])),
                }, historyMax);
                d = deltas(history.at(-2) ?? null, history.at(-1));
                changes = d.items;
                if (hosts.history) paintHist();
            }
            last = { items, overall, ...(report ?? {}) };
            const result = $('[data-sc-result]');
            if (!perf) {
                result.replaceChildren(h(doc, 'div', { class: 'sc-scores' }, scoreTile(doc, 'Overall', overall, d.overall, history.map(r => r.overall))), card(doc, 'Ranked: worst first', fromHtml(doc, rankedTable(items, { changes, link }))));
                loadElements(result);
            } else {
                const parts = [scoreTiles(doc, report.scores, { deltas: d, history })];
                if (sections.has('ranked')) {
                    const table = fromHtml(doc, rankedTable(items, { changes, link, label: options.rankedLabel ?? 'Target' }));
                    parts.push(card(doc, 'Ranked: worst first', note(doc, `Each target is rendered in ${scoring.themes.join(' and ')} at ${scoring.widths.join(', ')}px. A finding costs points (${Object.entries(scoring.findingPenalty).map(([k, v]) => `${k} ${v}`).join(', ')}); repeats across widths count once.`), table));
                }
                parts.push(card(doc, 'Scores in detail', categoryTabs(doc, scoring, report.scores, report.perFile)));
                result.replaceChildren(...parts);
                loadElements(result);
            }
            setProgress(`Done. Overall ${overall}.`);
        } catch (err) { log.error('the scorecard run failed', err); setProgress(`The run failed: ${err.message}`); } finally { button.removeAttribute('disabled'); }
        return items;
    }

    $('[data-sc-run]')?.addEventListener('click', run);
    loadElements(root);
    if (autorun && runs) await run();
    return { run, results: () => items, report: () => last, ready, destroy: () => root.remove() };
}

// The scorecard's framework sections, drawn from the pure rows of js/framework-checks.js with SDK components only (pk-card, pk-stat,
// pk-table, pk-tabs, pk-badge, pk-button, pk-cluster, pk-empty-state). No markup strings: every node is built with the DOM, every text is set as text.

import { band, metricRows, budgetRows, budgetSummary, apiDiff, securitySummary, sweepSummary, historyCategories, historyRows, severityVariant, kb, signed } from '../../js/framework-checks.js';

const STAT_TONE = { ok: 'positive', warn: 'warning', danger: 'critical', '': 'neutral' };

export function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

export const card = (doc, heading, ...children) => h(doc, 'pk-card', { heading, class: 'sc-section' }, ...children);
export const note = (doc, text) => h(doc, 'p', { class: 'muted' }, text);
export const badge = (doc, variant, text) => h(doc, 'pk-badge', { variant }, text);
export const emptyState = (doc, heading, description) => h(doc, 'pk-empty-state', { heading, description, tone: 'compact' });
const row = (doc, ...children) => h(doc, 'pk-cluster', {}, ...children);

// A data-driven pk-table. columns: [{ key, label, align?, sortable? }]; rows need an id; cells: { key: row => Node } fills a cell with a
// component (a badge, a link) through the table's cell slots.
export function table(doc, { label, columns, rows, cells = {}, filterable = false, maxHeight = '' }) {
    const t = h(doc, 'pk-table', { label, density: 'compact', hover: true, filterable, 'max-height': maxHeight || false, columns: JSON.stringify(columns), rows: JSON.stringify(rows) });
    for (const r of rows) for (const [key, make] of Object.entries(cells)) {
        const node = make(r);
        if (node) t.append(h(doc, 'span', { slot: `cell-${r.id}-${key}` }, node));
    }
    return t;
}

const num = (key, label) => ({ key, label, align: 'end', sortable: true });
const text = (key, label) => ({ key, label, sortable: true });

// ---- a section that has no data -------------------------------------------------------------------------------------------

export const missing = (doc, host, what, hint) => host.replaceChildren(emptyState(doc, `No ${what} yet`, hint));

// ---- scored categories (after a run) --------------------------------------------------------------------------------------

// Overall plus one tile per category, each with its score, its change since the last run and (with two runs or more) a sparkline.
export function scoreTile(doc, label, score, delta, series = []) {
    const values = series.filter(v => typeof v === 'number');
    return h(doc, 'pk-stat', { label, value: score === null || score === undefined ? 'n/a' : String(score), tone: STAT_TONE[band(score)], tile: true, subtext: delta === null || delta === undefined ? '' : `${signed(delta)} since the last run`, values: values.length > 1 ? JSON.stringify(values) : false });
}

export function scoreTiles(doc, scores, { deltas = { overall: null, categories: {} }, history = [] } = {}) {
    const overall = scoreTile(doc, 'Overall', scores.overall, deltas.overall, history.map(r => r.overall));
    overall.classList.add('sc-tile-big');
    return h(doc, 'div', { class: 'sc-scores' }, overall, ...Object.entries(scores.categories).map(([k, c]) => scoreTile(doc, c.label, c.score, deltas.categories?.[k], history.map(r => r.categories?.[k]))));
}

// One tab per scored category (its metrics against good and poor), plus one for the stylesheets.
export function categoryTabs(doc, scoring, scores, perFile) {
    const entries = Object.entries(scores.categories);
    const tabs = []; const panels = [];
    const add = (value, label, score, body) => {
        tabs.push(h(doc, 'pk-tab', { value }, score === undefined ? label : `${label} ${score ?? 'n/a'}`));
        panels.push(h(doc, 'pk-tab-panel', { value }, body));
    };
    for (const [key, c] of entries) {
        const rows = metricRows(scoring, key, c).map((r, i) => ({ id: i + 1, ...r }));
        add(key, c.label, c.score, table(doc, {
            label: `${c.label} metrics`,
            columns: [text('metric', 'Metric'), num('value', 'Value'), num('good', 'Good'), num('poor', 'Poor'), num('score', 'Score')],
            rows,
            cells: { score: r => (r.score === 'n/a' ? null : badge(doc, r.tone, String(r.score))) },
        }));
    }
    add('stylesheets', 'Stylesheets', undefined, table(doc, {
        label: 'Stylesheets',
        columns: [text('name', 'File'), num('bytes', 'Bytes'), num('rules', 'Rules'), num('selectors', 'Selectors'), num('literalColours', 'Literal colours'), num('literalSizes', 'Literal sizes')],
        rows: perFile.map((f, i) => ({ id: i + 1, name: f.name, bytes: f.bytes, rules: f.rules, selectors: f.selectors, literalColours: f.literalColours, literalSizes: f.literalSizes })),
        filterable: true,
        maxHeight: '28rem',
    }));
    return h(doc, 'pk-tabs', { value: entries[0]?.[0] ?? 'stylesheets', scroll: true }, ...tabs, ...panels);
}

// ---- size and budgets -----------------------------------------------------------------------------------------------------

export function paintSize(doc, host, { sizes, budgets }) {
    if (!sizes?.length) return missing(doc, host, 'sizes measured', 'Pass data.sizes: the files to weigh, each with the budget it belongs to.');
    if (!budgets) return missing(doc, host, 'budgets', 'Pass data.budgets: the limits each file is held to.');
    const rows = budgetRows(budgets, sizes).map((r, i) => ({ id: i + 1, ...r }));
    const s = budgetSummary(rows);
    host.replaceChildren(
        row(doc, badge(doc, s.over ? 'danger' : 'ok', s.over ? `${s.over} over budget` : 'All inside budget'), badge(doc, 'muted', `${s.total} measured`), s.unbudgeted ? badge(doc, 'muted', `${s.unbudgeted} with no budget`) : null),
        note(doc, 'Gzip size measured in this browser from the built files, against the limits in the budget definitions. A limit only ever comes down. Headroom is the limit minus the size.'),
        table(doc, {
            label: 'Size against budget',
            columns: [text('name', 'File'), num('raw', 'Raw KB'), num('gz', 'Gzip KB'), num('target', 'Target KB'), num('limit', 'Limit KB'), num('headroom', 'Headroom KB'), text('status', 'Status')],
            rows: rows.map(r => ({ id: r.id, name: r.name, raw: kb(r.rawKb), gz: r.gzKb === null ? 'n/a' : (Math.round(r.gzKb * 100) / 100).toString(), target: r.target ?? '-', limit: r.limit ?? '-', headroom: r.headroom ?? '-', status: r.status })),
            cells: { status: r => badge(doc, r.status === 'ok' ? 'ok' : r.status === 'over' ? 'danger' : 'muted', r.status === 'ok' ? 'inside' : r.status === 'over' ? 'over budget' : 'no budget') },
            filterable: true,
            maxHeight: '28rem',
        }),
    );
}

// ---- API surface ----------------------------------------------------------------------------------------------------------

export function paintApi(doc, host, { baseline, current }) {
    if (!baseline) return missing(doc, host, 'API baseline', 'Pass data.apiBaseline: the surface of the previous release (node tools/api-surface.mjs --write).');
    const d = apiDiff(baseline, current);
    const tiles = h(doc, 'div', { class: 'sc-scores' }, ...Object.entries(d.counts).map(([k, c]) => h(doc, 'pk-stat', {
        label: k, tile: true, value: String(c.current ?? c.baseline), tone: c.removed ? 'critical' : 'neutral',
        subtext: c.current === null ? 'in the baseline' : `baseline ${c.baseline}, ${c.removed} removed, ${c.added} added`,
    })));
    const parts = [tiles];
    if (!d.available) {
        parts.push(note(doc, 'No current surface was given (data.api), so only the baseline is counted. Removals and additions show once it is.'));
    } else {
        parts.push(row(doc, badge(doc, d.removed.length ? 'danger' : 'ok', d.removed.length ? `${d.removed.length} removed from the baseline` : 'Nothing removed from the baseline'), badge(doc, 'muted', `${d.added.length} added`)));
        const list = (label, items) => table(doc, { label, columns: [text('kind', 'Kind'), text('name', 'Name')], rows: items.map((x, i) => ({ id: i + 1, ...x })), filterable: true, maxHeight: '20rem' });
        if (d.removed.length) parts.push(list('Removed from the baseline (breaking)', d.removed));
        if (d.added.length) parts.push(list('Added since the baseline', d.added));
    }
    host.replaceChildren(...parts);
}

// ---- size sweep -----------------------------------------------------------------------------------------------------------

export function paintSweep(doc, host, report) {
    if (!report) return missing(doc, host, 'sweep report', 'Pass data.sweep: the last size sweep report.');
    const s = sweepSummary(report);
    const parts = [
        row(doc, badge(doc, s.failing ? 'warn' : 'ok', `${s.failing} failing`), badge(doc, 'muted', `${s.checked} cells checked`), badge(doc, 'muted', `${s.widths.join(', ')}px`), badge(doc, 'muted', s.themes.join(' + ')), s.partial ? badge(doc, 'danger', 'partial') : null),
        note(doc, 'Every view, template and control sample at each width and theme: overflow, targets under 44px on a phone, reading text under 14px, secondary text under 12px, nested scrollers.'),
    ];
    if (s.rows.length) parts.push(table(doc, {
        label: 'Failing cells',
        columns: [text('item', 'Item'), num('width', 'Width'), text('theme', 'Theme'), num('overflow', 'Overflow'), num('targets', 'Targets'), num('reading', 'Reading'), num('meta', 'Meta'), num('nested', 'Nested')],
        rows: s.rows, filterable: true, maxHeight: '24rem',
    }));
    if (s.total > s.rows.length) parts.push(note(doc, `Showing ${s.rows.length} of ${s.total}.`));
    for (const n of s.notes) parts.push(note(doc, `${n.item}: ${n.note}`));
    host.replaceChildren(...parts);
}

// ---- security and defects -------------------------------------------------------------------------------------------------

// fileLink(file, line) gives the Where column a link target; without it the place is plain text.
export function paintSecurity(doc, host, report, { fileLink } = {}) {
    if (!report) return missing(doc, host, 'security report', 'Pass data.security: the report tools/security.mjs writes (node tools/security.mjs --write).');
    const s = securitySummary(report);
    const parts = [row(doc, ...s.counts.map(c => badge(doc, c.count ? severityVariant(c.severity) : 'muted', `${c.severity} ${c.count}`)))];
    if (s.clean) parts.push(emptyState(doc, 'No findings', 'The scan found nothing to report.'));
    else parts.push(table(doc, {
        label: 'Security and defect findings',
        columns: [text('severity', 'Severity'), text('rule', 'Rule'), text('where', 'Where'), text('message', 'Detail')],
        rows: s.rows,
        cells: {
            severity: r => badge(doc, severityVariant(r.severity), r.severity),
            where: r => (fileLink ? h(doc, 'a', { href: fileLink(r.file, r.line) }, r.where) : null),
        },
        filterable: true, maxHeight: '28rem',
    }));
    if (s.total > s.shown) parts.push(note(doc, `Showing ${s.shown} of ${s.total}.`));
    host.replaceChildren(...parts);
}

// ---- history --------------------------------------------------------------------------------------------------------------

// actions: { onExport, onImport(file), onClear } add the toolbar; history is the runs kept under the mount's historyKey.
export function paintHistory(doc, host, { history, scoring, actions }) {
    const parts = [];
    if (actions) {
        const file = h(doc, 'input', { type: 'file', accept: 'application/json', hidden: true, 'aria-label': 'Import history file' });
        file.addEventListener('change', () => { const f = file.files?.[0]; if (f) actions.onImport(f); file.value = ''; });
        const button = (label, variant, fn) => { const b = h(doc, 'pk-button', { variant, size: 'mini' }, label); b.addEventListener('click', fn); return b; };
        parts.push(row(doc, button('Export history', 'ghost', actions.onExport), button('Import history', 'ghost', () => file.click()), button('Clear history', 'warn', actions.onClear), file));
    }
    if (!history.length) {
        parts.push(emptyState(doc, 'No runs yet', 'Each run is kept in this browser so the next one shows what changed.'));
    } else {
        const keys = historyCategories(history, scoring);
        const label = k => scoring?.categories?.[k]?.label ?? k;
        parts.push(table(doc, {
            label: 'Runs, newest first',
            columns: [text('when', 'Run'), num('overall', 'Overall'), ...keys.map(k => num(k, label(k))), num('change', 'Change')],
            rows: historyRows(history, keys).map(r => ({ ...r, change: signed(r.change) })),
            cells: { overall: r => (typeof r.overall === 'number' ? badge(doc, band(r.overall), String(r.overall)) : null) },
            maxHeight: '24rem',
        }));
    }
    host.replaceChildren(...parts);
}

/* Theme editor chrome (modules/theme-editor). Tokens only. */

.te { display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; }

/* Room under the last row so the dev tools launcher (fixed, bottom end) never covers a control when the editor is a dock tab. */
.te:not(.te--fixed) { padding-block-end: calc(var(--touch-target) + var(--space-4)); }

.te--fixed { min-height: 0; }

.te--fixed pk-tabs { flex: 1 1 auto; min-height: 0; overflow: auto; }

.te-toolbar { display: grid; grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr)); gap: var(--space-3); align-items: end; }

.te-list { display: flex; flex-direction: column; }

.te-row { display: grid; grid-template-columns: minmax(9rem, 16rem) minmax(0, 1fr) auto auto; align-items: center; gap: var(--space-2) var(--space-3); padding: var(--space-2) var(--space-2) var(--space-2) var(--space-3); border-bottom: 1px solid var(--color-border); }

.te-name { overflow-wrap: anywhere; background: none; padding: 0; }

.te-row > pk-input, .te-row > pk-colour-input { min-width: 0; }

.te-row > [data-pair] { grid-column: 3; }

.te-row > pk-button { grid-column: 4; }

.te-caption { margin: var(--space-3) 0 var(--space-1); color: var(--color-muted); font-size: var(--text-sm); }

.te-changed { box-shadow: inset 3px 0 0 var(--color-accent); }

.te-preview { width: 100%; height: 34rem; border: 1px solid var(--color-border); background: var(--color-bg); }

.te-preview-body { padding: var(--space-4); }

@media (max-width: 640px) {
    .te-row { grid-template-columns: minmax(0, 1fr) auto auto; padding-inline: var(--space-2); }
    .te-name { grid-column: 1 / -1; font-size: var(--text-base); }
    .te-row > pk-input, .te-row > pk-colour-input { grid-column: 1; }
    .te-row > [data-pair] { grid-column: 2; }
    .te-row > pk-button { grid-column: 3; }
    .te-row > pk-button { min-height: var(--touch-target); }
}

// The theme editor as a module: mountThemeEditor(container, options) lists every token the SDK's token stylesheet declares with an input
// for each, applies edits live, grades the text pairs for contrast, and exports or imports the override block (the format the
// server-side PkThemeOverrides helper takes: same names, same rules).
//
//   const editor = await mountThemeEditor(el, { storageKey: 'my-theme', onchange: ({ css }) => save(css) });   // edits the whole page
//   const scoped = await mountThemeEditor(el, { target: previewElement });                                    // edits only that subtree
//   editor.export(); editor.overrides(); editor.setTheme('light'); editor.reset(); editor.destroy();
//
// Options: target (a Document, the default: one adopted stylesheet of override CSS; or an Element: the current theme's overrides as
// inline custom properties, so only that subtree changes), theme ('dark' | 'light', initial), onchange({ css, overrides }), tokens (URL
// of the stylesheet whose token blocks are edited; default the SDK's own), pairs ([foreground, background] token names to grade;
// default DEFAULT_PAIRS), storageKey (localStorage key that keeps the overrides; default none), height (a CSS length: the token list
// scrolls inside it), preview (show a Preview tab with sample controls in a frame; default true).
// Returns { export(), overrides(), setTheme(name), reset(), destroy() }. The pure logic is js/theme-editor-logic.js and js/theme.js.
// Built only from SDK components (pk-tabs, pk-input, pk-select, pk-colour-input, pk-textarea, pk-button, pk-cluster, pk-alert, pk-badge, pk-stat, pk-table).

import { sanitizeOverrides, parseTokenBlocks, currentTheme, setTheme as setThemeAttr, buildOverrides, nameProblem, valueProblem, colourToHex, tokenKind } from '../../js/theme.js';
import { KINDS, DEFAULT_PAIRS, emptyOverrides, allTokenNames, baseValue, isChanged, effectiveValue, visibleTokens, withEdit, withoutToken, overrideCount, evaluatePairs, inlineEntries, readImport } from '../../js/theme-editor-logic.js';
import { ensureStyles, styleUrls } from '../../js/mount-support.js';
import { loadElements } from '../../js/loader.js';
import { createLogger } from '../../js/log.js';
const log = createLogger('theme-editor');

const STYLES = ['../../plainkit.css'];
const OWN_STYLES = ['./theme-editor.css'];
const TOKENS = '../../tokens/tokens.css';
const MAX_STORED = 100000;

export { DEFAULT_PAIRS };

// What the Preview tab shows: SDK elements that read tokens only.
const PREVIEW = `
<pk-toolbar heading="Preview" note="every control reads tokens only"><pk-button slot="actions" size="mini" variant="ghost">Ghost</pk-button><pk-button slot="actions" size="mini">Primary</pk-button></pk-toolbar>
<pk-card heading="Card title"><span slot="actions" class="muted">muted text</span><p>Body text with <a href="#">a link</a> and <code>code</code>.</p>
<pk-input label="Field" value="Input value"></pk-input>
<pk-cluster class="u-mt-3"><pk-badge variant="muted">Default</pk-badge><pk-badge variant="ok">Registered</pk-badge><pk-badge variant="warn">Warn</pk-badge><pk-badge variant="danger">Danger</pk-badge></pk-cluster></pk-card>
<pk-alert kind="warning">A warning notice.</pk-alert><pk-alert kind="success">A success notice.</pk-alert>
<pk-table density="compact"><table><thead><tr><th>SKU</th><th class="num">Price</th></tr></thead><tbody><tr><td><code>AC-001</code></td><td class="num">$4.99</td></tr></tbody></table></pk-table>`;

function h(doc, tag, props = {}, ...children) {
    const el = doc.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children.filter(c => c !== null && c !== undefined));
    return el;
}

const cap = s => s[0].toUpperCase() + s.slice(1);

function readStored(key, win) {
    if (!key) return emptyOverrides();
    try {
        const raw = win.localStorage.getItem(key) ?? '{}';
        return raw.length > MAX_STORED ? emptyOverrides() : sanitizeOverrides(JSON.parse(raw));
    } catch (error) { log.warn(`the saved theme edits under "${key}" could not be read: starting with none`, error); return emptyOverrides(); }
}

export async function mountThemeEditor(container, options = {}) {
    log.debug('mounted', { module: 'theme-editor', options: Object.keys(options) });
    const doc = container.ownerDocument;
    const win = doc.defaultView;
    const target = options.target ?? doc;
    const isDoc = target.nodeType === 9;
    const targetDoc = isDoc ? target : target.ownerDocument;
    const pairs = options.pairs ?? DEFAULT_PAIRS;
    const { onchange, storageKey, height } = options;
    const showPreview = options.preview !== false;
    await ensureStyles([...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)], doc);

    const tokensUrl = new URL(options.tokens ?? TOKENS, import.meta.url).href;
    const res = await fetch(tokensUrl);
    if (!res.ok) throw new Error(`${tokensUrl}: ${res.status}`);
    const tokens = parseTokenBlocks(await res.text());

    const state = { overrides: readStored(storageKey, win), scope: 'theme', kind: 'all', filter: '' };
    const themeHost = isDoc ? target.documentElement : target;
    const styleRoot = isDoc ? target.documentElement : target;
    if (options.theme) setThemeAttr(themeHost, options.theme);
    const theme = () => currentTheme(isDoc ? target.documentElement : (themeHost.closest('[data-theme]') ?? targetDoc.documentElement));

    // ---- output: one adopted stylesheet on a Document target; inline custom properties on an Element target
    const sheet = isDoc ? new targetDoc.defaultView.CSSStyleSheet() : null;
    if (sheet) targetDoc.adoptedStyleSheets = [...targetDoc.adoptedStyleSheets, sheet];
    let setInline = new Set();
    let previewFrame = null;
    let previewSheet = null;

    function applyToTarget(css) {
        if (sheet) { sheet.replaceSync(css); return; }
        const next = inlineEntries(state.overrides, theme());
        for (const n of setInline) if (!(n in next)) themeHost.style.removeProperty(n);
        for (const [n, v] of Object.entries(next)) themeHost.style.setProperty(n, v);
        setInline = new Set(Object.keys(next));
    }

    function applyToPreview(css) {
        const fdoc = previewFrame?.contentDocument;
        if (!fdoc?.head) return;
        if (!previewSheet || previewSheet.doc !== fdoc) { previewSheet = new fdoc.defaultView.CSSStyleSheet(); previewSheet.doc = fdoc; fdoc.adoptedStyleSheets = [...fdoc.adoptedStyleSheets, previewSheet]; }
        previewSheet.replaceSync(css);
        fdoc.documentElement.setAttribute('data-theme', theme());
    }

    // ---- interface
    const ui = {};
    const kindSelect = h(doc, 'pk-select', { label: 'Kind', value: 'all' }, ...KINDS.map(k => h(doc, 'option', { value: k }, cap(k))));
    const themeSelect = h(doc, 'pk-select', { label: 'Theme', value: theme() }, h(doc, 'option', { value: 'dark' }, 'Dark'), h(doc, 'option', { value: 'light' }, 'Light'));
    const scopeSelect = h(doc, 'pk-select', { label: 'Edits apply to', value: 'theme' }, h(doc, 'option', { value: 'theme' }, 'The current theme'), h(doc, 'option', { value: 'both' }, 'Both themes'));
    const find = h(doc, 'pk-input', { type: 'search', label: 'Find token', placeholder: 'e.g. accent, radius', clearable: true });
    const resetAll = h(doc, 'pk-button', { variant: 'warn', size: 'mini' }, 'Reset all');
    const shown = h(doc, 'span', { class: 'muted', role: 'status' });
    const count = h(doc, 'pk-stat', { label: 'Overrides', value: '0', tile: true });
    const warn = h(doc, 'pk-alert', { kind: 'warning' });
    warn.hidden = true;
    const list = h(doc, 'div', { class: 'te-list' });
    const pairTable = h(doc, 'pk-table', {
        label: 'Contrast', density: 'compact',
        columns: JSON.stringify([{ key: 'pair', label: 'Text on background' }, { key: 'ratio', label: 'Ratio', align: 'end' }, { key: 'grade', label: 'WCAG' }]),
    });
    const cssBox = h(doc, 'pk-textarea', { label: 'CSS block', rows: 10, readonly: true });
    const jsonBox = h(doc, 'pk-textarea', { label: 'JSON overrides', rows: 10 });
    const importBtn = h(doc, 'pk-button', { variant: 'primary' }, 'Import JSON or CSS');
    const copyBtn = h(doc, 'pk-button', { variant: 'ghost' }, 'Copy CSS');
    const downloadBtn = h(doc, 'pk-button', { variant: 'ghost' }, 'Download JSON');
    const rejectedBox = h(doc, 'div');
    const message = h(doc, 'div');

    const tabs = h(doc, 'pk-tabs', { value: 'tokens', label: 'Theme editor' },
        h(doc, 'pk-tab', { value: 'tokens' }, 'Tokens'), h(doc, 'pk-tab-panel', { value: 'tokens' }, list),
        h(doc, 'pk-tab', { value: 'contrast' }, 'Contrast'), h(doc, 'pk-tab-panel', { value: 'contrast' }, warn, pairTable),
        ...(showPreview ? [h(doc, 'pk-tab', { value: 'preview' }, 'Preview'), h(doc, 'pk-tab-panel', { value: 'preview' }, (ui.previewHost = h(doc, 'div', { class: 'te-preview-host' })))] : []),
        h(doc, 'pk-tab', { value: 'export' }, 'Export / import'),
        h(doc, 'pk-tab-panel', { value: 'export' },
            h(doc, 'p', { class: 'muted' }, 'Names are lowercase custom properties; values use only letters, digits and # % . , ( ) - + / and spaces, at most 200 characters.'),
            rejectedBox, h(doc, 'p', { class: 'te-caption' }, 'CSS block (paste into a style element after the SDK stylesheets)'), cssBox, h(doc, 'p', { class: 'te-caption' }, 'JSON { shared, dark, light } of token to value: the C# helper input (editable, then Import)'), jsonBox, h(doc, 'pk-cluster', { class: 'u-mt-3' }, importBtn, copyBtn, downloadBtn), message));

    const root = h(doc, 'section', { class: 'te', 'aria-label': 'Theme editor' },
        h(doc, 'div', { class: 'te-toolbar' }, find, kindSelect, themeSelect, scopeSelect),
        h(doc, 'pk-cluster', { justify: 'between' }, count, shown, resetAll),
        tabs);
    if (height) { root.classList.add('te--fixed'); root.style.height = height; }
    container.replaceChildren(root);
    loadElements(root);

    if (showPreview) {
        previewFrame = h(doc, 'iframe', { class: 'te-preview', title: 'Theme preview' });
        const links = [...styleUrls(STYLES, import.meta.url), ...styleUrls(OWN_STYLES, import.meta.url)].map(u => `<link rel="stylesheet" href="${encodeURI(u)}">`).join('');
        previewFrame.srcdoc = `<!doctype html><html lang="en" data-theme="${theme()}" data-te-preview><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">${links}</head><body class="te-preview-body">${PREVIEW}<script type="module" src="${encodeURI(import.meta.url)}"></script></body></html>`;
        previewFrame.addEventListener('load', () => applyToPreview(buildOverrides(state.overrides).css));
        ui.previewHost.append(previewFrame);
    }

    // ---- painting
    const rowsByName = new Map();
    const chipFor = (fg, bg) => {
        const [r] = evaluatePairs([[fg, bg]], readComputed);
        return r;
    };
    function readComputed(name) { return win.getComputedStyle(styleRoot).getPropertyValue(name).trim(); }

    function paintRow(name) {
        const row = rowsByName.get(name);
        if (!row) return;
        const changed = isChanged(state.overrides, theme(), name);
        row.classList.toggle('te-changed', changed);
        const reset = row.querySelector('pk-button');
        if (changed) reset.removeAttribute('disabled'); else reset.setAttribute('disabled', '');
        const chip = row.querySelector('[data-pair]');
        if (chip) {
            const r = chipFor(name, '--color-panel');
            chip.textContent = r.ratio === null ? '' : `${r.ratio.toFixed(1)}:1`;
            chip.setAttribute('variant', r.bad ? 'danger' : 'ok');
        }
    }

    function makeRow(name) {
        const value = effectiveValue(state.overrides, tokens, theme(), name);
        const hex = tokenKind(name, value) === 'colour' ? colourToHex(value) : null;
        const control = hex
            ? h(doc, 'pk-colour-input', { label: name, value: hex })
            : h(doc, 'pk-input', { label: name, value });
        const reset = h(doc, 'pk-button', { variant: 'ghost', size: 'mini', label: `Reset ${name}` }, 'Reset');
        const chip = /^--color-(text|muted|link|accent)$/.test(name) ? h(doc, 'pk-badge', { 'data-pair': name }) : null;
        const row = h(doc, 'div', { class: 'te-row', 'data-token': name }, h(doc, 'code', { class: 'te-name' }, name), control, ...(chip ? [chip] : []), reset);
        rowsByName.set(name, row);
        return row;
    }

    function paintList() {
        rowsByName.clear();
        const names = visibleTokens(tokens, theme(), state);
        list.replaceChildren(...names.map(makeRow));
        if (!names.length) list.append(h(doc, 'p', { class: 'muted' }, 'No tokens match.'));
        for (const n of names) paintRow(n);
        shown.textContent = `${names.length} of ${allTokenNames(tokens).length} tokens`;
        if (themeSelect.value !== theme()) themeSelect.value = theme();
    }

    function paintPairs() {
        const results = evaluatePairs(pairs, readComputed);
        pairTable.setAttribute('rows', JSON.stringify(results.map((r, id) => ({ id, pair: `${r.fg} on ${r.bg}`, ratio: r.ratio === null ? 'n/a' : `${r.ratio.toFixed(2)}:1`, grade: r.grade }))));
        const bad = results.filter(r => r.bad).length;
        warn.hidden = bad === 0;
        warn.textContent = `${bad} text pair${bad === 1 ? '' : 's'} below 4.5:1 in the ${theme()} theme.`;
        for (const n of rowsByName.keys()) paintRow(n);
    }

    function paintExport(css, rejected) {
        cssBox.value = css;
        jsonBox.value = JSON.stringify(state.overrides, null, 2);
        const n = overrideCount(state.overrides);
        count.setAttribute('value', String(n));
        rejectedBox.replaceChildren(...(rejected.length ? [h(doc, 'pk-alert', { kind: 'warning' }, ...rejected.flatMap((r, i) => (i ? [h(doc, 'br'), r] : [r])))] : []));
    }

    function apply() {
        const { css, rejected } = buildOverrides(state.overrides);
        applyToTarget(css);
        applyToPreview(css);
        if (storageKey) try { win.localStorage.setItem(storageKey, JSON.stringify(state.overrides)); } catch (error) { log.debug('storage blocked: the edit applies but is not saved', error); }
        paintPairs();
        paintExport(css, rejected);
        onchange?.({ css, overrides: api.overrides() });
    }

    function edit(name, value) {
        state.overrides = withEdit(state.overrides, { theme: theme(), scope: state.scope, name, value, base: baseValue(tokens, theme(), name) });
        apply();
    }

    function note(kind, text) {
        message.replaceChildren(h(doc, 'pk-alert', { kind: kind === 'error' ? 'danger' : kind }, text));
    }

    function importText(text) {
        const read = readImport(text);
        if (read.error) { log.warn(`import refused, the overrides are unchanged: ${read.error}`); note('error', read.error); return; }
        const parsed = read.overrides;
        state.overrides = { shared: parsed.shared, dark: parsed.dark, light: parsed.light };
        note('success', 'Imported.');
        apply(); paintList(); paintPairs();
    }

    // ---- events
    const listeners = [];
    const on = (el, type, fn) => { el.addEventListener(type, fn); listeners.push(() => el.removeEventListener(type, fn)); };
    const tokenOf = e => e.target.closest?.('[data-token]')?.dataset.token;

    on(find, 'input', e => { state.filter = e.target.value ?? ''; paintList(); });
    on(kindSelect, 'change', e => { state.kind = e.target.value; paintList(); });
    on(scopeSelect, 'change', e => { state.scope = e.target.value; });
    on(themeSelect, 'change', e => { if (e.target.value !== theme()) api.setTheme(e.target.value); });
    on(resetAll, 'click', () => api.reset());
    on(list, 'pk-colour', e => { const n = tokenOf(e); if (n) edit(n, e.detail.value); });
    on(list, 'input', e => {
        if (e.target.localName !== 'pk-input') return;
        const n = tokenOf(e);
        if (!n) return;
        const v = String(e.target.value ?? '').trim();
        const problem = v === '' ? null : nameProblem(n) ?? valueProblem(v);
        if (problem) { e.target.setAttribute('invalid', ''); e.target.setAttribute('title', problem); return; }
        e.target.removeAttribute('invalid'); e.target.removeAttribute('title');
        edit(n, v);
    });
    on(list, 'click', e => {
        const b = e.target.closest?.('pk-button');
        const n = tokenOf(e);
        if (!b || !n || b.hasAttribute('disabled')) return;
        state.overrides = withoutToken(state.overrides, n);
        apply();
        const fresh = makeRow(n);
        const old = list.querySelector(`[data-token="${CSS.escape(n)}"]`);
        old.replaceWith(fresh);
        paintRow(n);
    });
    on(importBtn, 'click', () => importText(jsonBox.value));
    on(copyBtn, 'click', () => win.navigator.clipboard?.writeText(cssBox.value));
    on(downloadBtn, 'click', () => {
        const a = doc.createElement('a');
        a.href = win.URL.createObjectURL(new win.Blob([jsonBox.value], { type: 'application/json' }));
        a.download = 'pk-theme-overrides.json';
        a.click();
        win.URL.revokeObjectURL(a.href);
    });

    // The theme can change from outside (the page's own toggle): follow it.
    const observer = new win.MutationObserver(() => { apply(); paintList(); });
    observer.observe(targetDoc.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    if (!isDoc) observer.observe(themeHost, { attributes: true, attributeFilter: ['data-theme'] });

    const api = {
        export: () => buildOverrides(state.overrides).css,
        overrides: () => ({ shared: { ...state.overrides.shared }, dark: { ...state.overrides.dark }, light: { ...state.overrides.light } }),
        setTheme(name) { setThemeAttr(isDoc ? target.documentElement : themeHost, name); apply(); paintList(); },
        reset() { state.overrides = emptyOverrides(); apply(); paintList(); },
        destroy() {
            observer.disconnect();
            for (const off of listeners) off();
            if (sheet) targetDoc.adoptedStyleSheets = targetDoc.adoptedStyleSheets.filter(s => s !== sheet);
            else for (const n of setInline) themeHost.style.removeProperty(n);
            root.remove();
        },
    };
    apply(); paintList();
    return api;
}

// The Preview frame loads this same module as its script: inside it, the only job is to define the pk-* elements the frame shows.
if (globalThis.document?.documentElement?.hasAttribute('data-te-preview')) loadElements(document);

/* GENERATED by tools/build.mjs: do not edit. Entry point for a non-Blazor page. base/a11y.css is last on purpose. */
@import url("tokens/tokens.css");
@import url("base/base.css");
@import url("base/spacing.css");
@import url("base/typography.css");
@import url("base/table-content.css");
@import url("base/utilities.css");
@import url("elements/elements.css");
@import url("base/a11y.css");

// The filter-table pattern, made live: the toolbar's search and status controls filter the table, the applied filters show as removable tags
// (removing one, or "Clear all", resets its control), and a filter typed into the table's own header row shows up in the toolbar too.
// mount(root) works on this sample's own DOM and returns { destroy() }.
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:filter-table');

// A filter and how its tag reads; the status control's "Any" means no filter.
const LABELS = { name: 'Search', status: 'Status' };
const NONE = { status: 'Any' };

export default function mount(root) {
    const ac = new AbortController();
    const table = root.querySelector('[data-table]');
    const applied = root.querySelector('[data-applied]');
    const clear = root.querySelector('[data-clear]');
    const controls = new Map([...root.querySelectorAll('[data-field]')].map(c => [c.dataset.field, c]));
    if (!table || !applied || !clear || !controls.size) { log.warn('the filter-table sample needs [data-table], [data-applied], [data-clear] and [data-field] controls', { root }); return { destroy() {} }; }

    // Show a set of filters: the controls, the tags and the (hidden when empty) "Applied" row.
    const show = filters => {
        for (const [key, c] of controls) {
            const v = String(filters[key] ?? '');
            const shown = v === '' ? (NONE[key] ?? '') : v;
            if (c.value !== shown) c.value = shown;
        }
        for (const t of applied.querySelectorAll('pk-tag')) t.remove();
        const active = Object.entries(filters).filter(([key, v]) => String(v ?? '').trim() !== '' && v !== NONE[key]);
        for (const [key, v] of active) {
            const tag = document.createElement('pk-tag');
            tag.setAttribute('removable', ''); tag.dataset.key = key;
            tag.textContent = `${LABELS[key] ?? key}: ${v}`;
            clear.before(tag);
        }
        applied.hidden = active.length === 0;
    };
    const apply = filters => { table.filters = filters; show(filters); };
    // Before the table is defined its prop is not there yet: read the attribute the sample was written with.
    const current = () => {
        if (table.filters && typeof table.filters === 'object') return { ...table.filters };
        try { return JSON.parse(table.getAttribute('filters') || '{}'); } catch (error) { log.warn('the table filters attribute is not JSON: starting with none', error); return {}; }
    };

    const fromControl = e => {
        const c = e.target.closest?.('[data-field]'), key = c?.dataset.field;
        if (!key) return;
        const v = c.value;
        apply({ ...current(), [key]: v === NONE[key] ? '' : v });
    };
    root.addEventListener('input', fromControl, { signal: ac.signal });
    // The table raises pk-filter before it applies the change; its detail is the new set.
    table.addEventListener('pk-filter', e => { if (e.target === table) show(e.detail.filters); }, { signal: ac.signal });
    applied.addEventListener('pk-remove', e => { const key = e.target.dataset.key; if (key) apply({ ...current(), [key]: '' }); }, { signal: ac.signal });
    clear.addEventListener('click', () => apply({}), { signal: ac.signal });

    show(current());
    customElements.whenDefined('pk-table').then(() => { if (!ac.signal.aborted) show(current()); });
    return { destroy() { ac.abort(); } };
}

// The master-detail pattern, made live: choosing an item marks it and fills the detail card (heading, name, status badge, history) from the
// data-* attributes on its link, back on the Overview tab. When the two columns are stacked (a phone) the detail is scrolled into view.
// mount(root) works on this sample's own DOM and returns { destroy() }.
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:master-detail');

export default function mount(root) {
    const ac = new AbortController();
    const list = root.querySelector('[data-list]');
    const detail = root.querySelector('[data-detail]');
    const parts = detail && { name: detail.querySelector('[data-name]'), status: detail.querySelector('[data-status]'), history: detail.querySelector('[data-history]'), tabs: detail.querySelector('[data-tabs]') };
    if (!list || !parts || Object.values(parts).some(p => !p)) { log.warn('the master-detail sample needs [data-list], [data-detail] and the [data-name|status|history|tabs] hooks', { root }); return { destroy() {} }; }

    const links = [...list.querySelectorAll('a[data-id]')];
    const label = new Map(links.map(a => [a, a.textContent]));
    const entry = (heading) => { const t = document.createElement('pk-timeline-item'); t.setAttribute('heading', heading); t.setAttribute('status', 'done'); return t; };

    const select = link => {
        for (const a of links) {
            const on = a === link;
            if (on) a.setAttribute('aria-current', 'true'); else a.removeAttribute('aria-current');
            if (on) { const s = document.createElement('strong'); s.textContent = label.get(a); a.replaceChildren(s); } else a.textContent = label.get(a);
        }
        const name = label.get(link);
        detail.setAttribute('heading', name);
        parts.name.textContent = name;
        parts.status.textContent = link.dataset.status ?? '';
        parts.status.setAttribute('variant', link.dataset.variant ?? 'muted');
        parts.history.replaceChildren(...(link.dataset.history ?? '').split('|').filter(Boolean).map(entry));
        parts.tabs.setAttribute('value', 'overview');
        // Stacked columns: the detail sits below the list, so bring it into view.
        if (detail.getBoundingClientRect().top >= list.getBoundingClientRect().bottom) detail.scrollIntoView({ block: 'start' });
    };

    list.addEventListener('click', e => {
        const a = e.target.closest?.('a[data-id]');
        if (!a) return;
        e.preventDefault();
        select(a);
    }, { signal: ac.signal });

    return { destroy() { ac.abort(); } };
}

// The notifications pattern, made live: each button raises a toast, the bell counts what was raised and clears when it is pressed.
// mount(root) works on this sample's own DOM (root) and returns { destroy() }; the toasts it raised are removed by destroy().
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:notifications');

export default function mount(root) {
    const ac = new AbortController();
    const raised = new Set();
    const badge = root.querySelector('[data-unread]');
    let unread = Number(badge?.getAttribute('count')) || 0;
    if (!badge || !root.querySelector('[data-bell]')) log.warn('the notifications sample needs [data-bell] and [data-unread]', { root });

    const paint = () => { if (!badge) return; badge.hidden = unread === 0; badge.setAttribute('count', String(unread)); };
    // PkToast is defined by the toast stack in the sample: nothing can be shown before it has loaded.
    const toast = (message, options) => {
        const PkToast = globalThis.PkToast;
        if (!PkToast) { log.warn('PkToast is not defined yet: the toast stack has not loaded', { message }); return; }
        const t = PkToast.show(message, options);
        raised.add(t);
        t.addEventListener('pk-dismiss', () => raised.delete(t), { once: true, signal: ac.signal });
        unread += 1; paint();
    };
    const say = {
        saved: () => toast('Item saved.', { kind: 'success' }),
        archived: () => toast('Item archived.', { action: { label: 'Undo', onClick: () => toast('Archive undone.') } }),
        failed: () => toast('The export failed.', { kind: 'danger', action: { label: 'Retry', onClick: () => toast('Export ready.', { kind: 'success' }) } }),
    };

    root.addEventListener('click', e => {
        const b = e.target.closest?.('[data-toast]');
        if (b) { const run = say[b.dataset.toast]; if (run) run(); else log.warn(`data-toast="${b.dataset.toast}" is not one of ${Object.keys(say).join(', ')}`, { button: b }); return; }
        if (e.target.closest?.('[data-bell]')) { unread = 0; paint(); }
    }, { signal: ac.signal });

    return { destroy() { ac.abort(); for (const t of raised) t.remove(); raised.clear(); } };
}

// The onboarding pattern, made live: Start completes the current step, the stepper moves on, and the progress bar, the "n of m done" text
// and the list of next steps follow it. After the last step the list says the setup is finished.
// mount(root) works on this sample's own DOM and returns { destroy() }.
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:onboarding');

export default function mount(root) {
    const ac = new AbortController();
    const stepper = root.querySelector('[data-stepper]');
    const progress = root.querySelector('[data-progress]');
    const count = root.querySelector('[data-done]');
    const list = root.querySelector('[data-next]');
    if (!stepper || !progress || !list) { log.warn('the onboarding sample needs [data-stepper], [data-progress] and [data-next]', { root }); return { destroy() {} }; }

    const titles = [...stepper.querySelectorAll('pk-step')].map(s => s.getAttribute('heading') ?? '');
    let done = Number(stepper.getAttribute('current')) || 0; // steps completed: the stepper's current step is the first one not done
    const row = (text, { start = false, muted = false } = {}) => {
        const d = document.createElement('div');
        if (muted) d.className = 'muted';
        d.append(text);
        if (start) {
            const b = document.createElement('pk-button');
            b.setAttribute('size', 'mini'); b.setAttribute('data-start', ''); b.textContent = 'Start';
            d.append(' ', b);
        }
        return d;
    };
    const paint = () => {
        progress.setAttribute('value', String(Math.round((done / titles.length) * 100)));
        if (count) count.textContent = `${done} of ${titles.length} done`;
        list.replaceChildren(...(done >= titles.length ? [row('All steps are done.')] : [row(titles[done], { start: true }), ...titles.slice(done + 1).map(t => row(t, { muted: true }))]));
    };

    root.addEventListener('click', e => {
        if (!e.target.closest?.('[data-start]') || done >= titles.length) return;
        done += 1;
        // The stepper has no step after the last one, so it stays on it; the rest of the sample shows that everything is done.
        // The stepper is linear (its next() will not skip ahead) and this sample is the host, so it sets the step it now shows.
        if (done < titles.length) stepper.current = done;
        paint();
    }, { signal: ac.signal });
    // A step the reader picks in the stepper (when it is made clickable) moves the checklist with it.
    stepper.addEventListener('pk-step-change', e => { done = e.detail.index; paint(); }, { signal: ac.signal });

    paint();
    return { destroy() { ac.abort(); } };
}

// The search-results pattern, made live: typing filters the rows of every group, marks the match, renumbers the rows, hides a group with no
// match and shows an empty state when nothing is left. Ctrl+K (Cmd+K) focuses the field; ArrowDown moves into the results.
// mount(root) works on this sample's own DOM and returns { destroy() }; the one listener outside it (the shortcut on the document) is removed there.
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:search-results');

export default function mount(root) {
    const ac = new AbortController();
    const query = root.querySelector('[data-query]');
    const groups = [...root.querySelectorAll('[data-group]')];
    const empty = root.querySelector('[data-empty]');
    if (!query || !groups.length) { log.warn('the search-results sample needs a [data-query] and [data-group] blocks', { root }); return { destroy() {} }; }

    // Each row's plain text, taken once: the marks are drawn from it, so a new query never reads text a previous one changed.
    const rows = groups.map(g => [...g.querySelectorAll('pk-list-group > button')].map(row => {
        const label = row.querySelector('[data-label]');
        if (!label) log.warn('a result row has no [data-label]', { row });
        return { row, label, n: row.querySelector('[data-n]'), text: label?.textContent ?? '' };
    }));

    const draw = (label, text, needle) => {
        const at = needle ? text.toLowerCase().indexOf(needle) : -1;
        if (at < 0) { label.textContent = text; return; }
        const mark = document.createElement('mark');
        mark.textContent = text.slice(at, at + needle.length);
        label.replaceChildren(text.slice(0, at), mark, text.slice(at + needle.length));
    };
    const filter = value => {
        const needle = String(value ?? '').trim().toLowerCase();
        let total = 0;
        groups.forEach((g, gi) => {
            let shown = 0;
            for (const r of rows[gi]) {
                const hit = r.label && (needle === '' || r.text.toLowerCase().includes(needle));
                r.row.hidden = !hit;
                if (!hit) continue;
                shown += 1;
                draw(r.label, r.text, needle);
                if (r.n) r.n.textContent = String(shown);
            }
            g.hidden = shown === 0;
            const count = g.querySelector('[data-count]');
            if (count) count.textContent = `(${shown})`;
            total += shown;
        });
        if (empty) empty.hidden = total > 0;
    };

    filter(query.getAttribute('value'));
    query.addEventListener('input', () => filter(query.value), { signal: ac.signal });
    query.addEventListener('keydown', e => {
        if (e.key !== 'ArrowDown') return;
        const first = root.querySelector('[data-group]:not([hidden]) pk-list-group > button:not([hidden])');
        if (first) { e.preventDefault(); first.focus(); }
    }, { signal: ac.signal });
    document.addEventListener('keydown', e => {
        if (e.key.toLowerCase() === 'k' && (e.ctrlKey || e.metaKey) && !e.altKey) { e.preventDefault(); query.focus(); }
    }, { signal: ac.signal });

    return { destroy() { ac.abort(); } };
}

// The unsaved-settings pattern, made live: the save bar appears when a field differs from what was last saved, Save keeps the values
// and hides it, Discard puts the saved values back. mount(root) works on this sample's own DOM and returns { destroy() }.
import { createLogger } from '../../../js/log.js';

const log = createLogger('pattern:unsaved-settings');

const FIELDS = 'pk-input, pk-select, pk-switch, pk-range';
// The value a field holds, in the shape its element commits it.
const read = f => (f.localName === 'pk-switch' ? f.checked : f.value);
const write = (f, v) => { if (f.localName === 'pk-switch') f.checked = v; else f.value = v; };

export default function mount(root) {
    const ac = new AbortController();
    const form = root.querySelector('form');
    const bar = root.querySelector('[data-bar]');
    const saved = root.querySelector('[data-saved]');
    if (!form || !bar) { log.warn('the unsaved-settings sample needs a form and a [data-bar]', { root }); return { destroy() {} }; }

    const fields = [...form.querySelectorAll(FIELDS)];
    let base = new Map();
    const snapshot = () => { base = new Map(fields.map(f => [f, read(f)])); };
    const dirty = () => fields.some(f => read(f) !== base.get(f));
    const paint = () => { bar.hidden = !dirty(); };

    // Elements upgrade on load: take the saved values once every field element is defined.
    Promise.all([...new Set(fields.map(f => f.localName))].map(t => customElements.whenDefined(t))).then(() => {
        if (ac.signal.aborted) return;
        snapshot(); paint();
    });
    bar.hidden = true;

    const onChange = () => { if (saved) saved.hidden = true; paint(); };
    for (const type of ['input', 'change', 'pk-change', 'pk-range']) form.addEventListener(type, onChange, { signal: ac.signal });
    root.addEventListener('click', e => {
        if (e.target.closest?.('[data-save]')) { snapshot(); paint(); if (saved) saved.hidden = false; }
        else if (e.target.closest?.('[data-discard]')) { for (const [f, v] of base) write(f, v); paint(); }
    }, { signal: ac.signal });

    return { destroy() { ac.abort(); } };
}

