// The SDK's public surface: every class a stylesheet defines, every token, every JS export, and every element's API (tag, props with their
// type, default and enum values, slots, events, parts, CSS properties, methods). node core/tools/api-surface.mjs [--write [--release <version>]]
// site/scorecard/api.baseline.json is the previous RELEASE: what a release must not break without the version saying so (tools/versioning.mjs
// computes the bump the differences need). --write refreshes it from the current sources; a release pull request does that with --release.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const walk = d => fs.readdirSync(d, { withFileTypes: true }).flatMap(e => (['dist', 'node_modules', 'tests'].includes(e.name) ? [] : e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));

// The element API as flat items, so a removed prop, event or enum value (or a changed type or default) shows as a missing item.
export function elementSurface(dir = path.join(root, 'elements')) {
    const items = [];
    for (const d of fs.readdirSync(dir, { withFileTypes: true }).filter(e => e.isDirectory())) {
        const file = path.join(dir, d.name, `${d.name}.meta.json`);
        if (!fs.existsSync(file)) continue;
        const m = JSON.parse(fs.readFileSync(file, 'utf8'));
        const tag = m.tag;
        items.push(tag);
        for (const p of m.props ?? []) {
            items.push(`${tag}:prop:${p.name}`, `${tag}:prop:${p.name}:type=${p.type}`);
            if (p.default !== undefined && p.default !== null && p.default !== '') items.push(`${tag}:prop:${p.name}:default=${JSON.stringify(p.default)}`);
            for (const v of p.values ?? []) items.push(`${tag}:prop:${p.name}:value=${v}`);
        }
        for (const s of m.slots ?? []) items.push(`${tag}:slot:${s.name || '(default)'}`);
        for (const e of m.events ?? []) items.push(`${tag}:event:${e.name}`);
        for (const x of m.parts ?? []) items.push(`${tag}:part:${x.name}`);
        for (const c of m.cssProperties ?? []) items.push(`${tag}:css:${c.name}`);
        for (const x of m.methods ?? []) items.push(`${tag}:method:${x.name}`);
    }
    return [...new Set(items)].sort();
}

export function surface() {
    const files = walk(root);
    const cssDirs = f => /(^|[\\/])(modules[\\/][^\\/]+[\\/][^\\/]+|tokens[\\/]tokens|base[\\/][^\\/]+)\.css$/.test(path.relative(root, f));
    const css = files.filter(f => f.endsWith('.css') && cssDirs(f)).map(f => fs.readFileSync(f, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '')).join('\n');
    const classes = [...new Set([...css.matchAll(/\.(-?[A-Za-z_][\w-]*)/g)].map(m => m[1]))].sort();
    const tokens = [...new Set([...fs.readFileSync(path.join(root, 'tokens', 'tokens.css'), 'utf8').matchAll(/(--[a-z0-9-]+)\s*:/g)].map(m => m[1]))].sort();
    const exports = [];
    for (const f of files.filter(f => /\.js$/.test(f) && /[\\/]js[\\/]/.test(f))) {
        const rel = path.relative(root, f).split(path.sep).join('/');
        for (const m of fs.readFileSync(f, 'utf8').matchAll(/^export (?:async )?(?:function|const|class)\s+([A-Za-z_$][\w$]*)/gm)) exports.push(`${rel}:${m[1]}`);
    }
    return { classes, tokens, exports: exports.sort(), elements: elementSurface() };
}

export function removed(baseline, current) {
    const out = [];
    for (const k of ['classes', 'tokens', 'exports', 'elements']) for (const x of baseline[k] ?? []) if (!(current[k] ?? []).includes(x)) out.push(`${k}: ${x}`);
    return out;
}

// --current writes site/scorecard/api.current.json: the surface as it is now, for the scorecard's API section to diff against the baseline.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url) && process.argv.includes('--current')) {
    fs.writeFileSync(path.join(root, 'site', 'scorecard', 'api.current.json'), JSON.stringify(surface(), null, 1) + '\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url) && process.argv.includes('--write')) {
    const file = path.join(root, 'site', 'scorecard', 'api.baseline.json');
    const at = process.argv.indexOf('--release');
    const previous = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')).release ?? null : null;
    const s = { release: at >= 0 ? process.argv[at + 1] : previous, ...surface() };
    fs.writeFileSync(file, (JSON.stringify(s, null, 1) + '\n').replace(/\n/g, '\r\n'));
    console.log(Object.fromEntries(Object.entries(s).map(([k, v]) => [k, Array.isArray(v) ? v.length : v])));
}

// SDK build: node core/tools/build.mjs   (dependency-free, deterministic; run it after editing any source folder)
//
// The page layer is tokens/ and base/ (base.css, spacing, typography, table-content, utilities, a11y); everything else is a custom element in
// elements/<name>/: <name>.html (template), <name>.css, <name>.js (behaviour, optional), <name>.meta.json (the API). This script generates,
// and you never hand-edit:
//   plainkit.css                     @imports the page layer in cascade order, then the element FOUC guard, then a11y
//   site/gallery/gallery.data.js     the gallery's data: the sample folders and the element API assembled (+ gallery.static.js)
//   site/files/snapshot.json         the Files page's snapshot of core/ (no timestamp; it holds every file above, never itself)
//   dist/<tool>/                     the tool modules (code-explorer, ...) from modules/, paths resolved for the dist layout
//   dist/plainkit.css, dist/plainkit.min.css, dist/plainkit.js, dist/js/, dist/elements/   what a non-Blazor project consumes

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { validateApi, propsObject } from './element-api.mjs';
import { allManifests } from './element-manifests.mjs';
import { galleryDist } from './gallery-dist.mjs';
import { modulesDist } from './modules-dist.mjs';
import { surface } from './api-surface.mjs';
import { collectSnapshot } from './snapshot.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
// Every generated file goes through w(): kept in `out` (path -> exact text) and written to disk only when build({ write: true }) (the
// default). A test builds with write: false and compares `out` to the files on disk, so it never rewrites files other tests read.
let out = new Map();
let writing = true;
const w = (rel, text) => { const crlf = text.replace(/\r?\n/g, '\r\n'); out.set(rel, crlf); if (!writing) return; const f = path.join(root, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, crlf); };
const read = f => fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n');

// Samples live in their own folders, each with a meta file: samples/templates/<id>/, samples/patterns/<id>/ and layouts/<id>/.
// The meta lists the elements the sample uses (a test keeps that list equal to what its markup carries).
export const SAMPLE_GROUPS = [['templates', 'samples/templates'], ['patterns', 'samples/patterns'], ['layouts', 'layouts']];
export function loadSamples(rootDir = root) {
    const groups = {};
    for (const [group, dir] of SAMPLE_GROUPS) {
        const base = path.join(rootDir, dir);
        const list = [];
        for (const e of fs.readdirSync(base, { withFileTypes: true }).filter(d => d.isDirectory()).sort((a, b) => a.name.localeCompare(b.name))) {
            const metaFile = path.join(base, e.name, `${e.name}.meta.json`); const htmlFile = path.join(base, e.name, `${e.name}.html`);
            if (!fs.existsSync(metaFile) || !fs.existsSync(htmlFile)) throw new Error(`${dir}/${e.name} needs ${e.name}.html and ${e.name}.meta.json`);
            const meta = JSON.parse(read(metaFile));
            // A pattern may ship a script beside its markup (<id>.js: export default mount(root) -> { destroy() }); the data names it relative to the patterns folder.
            const script = group === 'patterns' && fs.existsSync(path.join(base, e.name, `${e.name}.js`)) ? { script: `${e.name}/${e.name}.js` } : {};
            list.push({ ...meta, ...(group === 'templates' ? {} : { html: read(htmlFile).trim() }), ...script, file: `${dir}/${e.name}/${e.name}.html` });
        }
        groups[group] = list.sort((a, b) => a.order - b.order);
    }
    return groups;
}

// Custom elements: elements/<name>/ holds <name>.html (the template), <name>.css, <name>.meta.json (the API), and <name>.js when the element
// has behaviour (export default Base => class extends Base { ... }). The build validates the API against the template and css and generates
// one module per element with the template and styles inlined, so nothing is fetched at runtime.
export function loadElementSources(rootDir = root) {
    const dir = path.join(rootDir, 'elements');
    if (!fs.existsSync(dir)) return [];
    const problems = []; const list = [];
    for (const e of fs.readdirSync(dir, { withFileTypes: true }).filter(d => d.isDirectory()).sort((a, b) => a.name.localeCompare(b.name))) {
        const f = ext => path.join(dir, e.name, `${e.name}.${ext}`);
        for (const need of ['html', 'css', 'meta.json']) if (!fs.existsSync(f(need))) problems.push(`elements/${e.name} is missing ${e.name}.${need}`);
        if (problems.length) continue;
        const meta = JSON.parse(read(f('meta.json'))); const template = read(f('html')).trim(); const css = read(f('css'));
        const behaviour = fs.existsSync(f('js')) ? read(f('js')) : null;
        problems.push(...validateApi(meta, { template, css, name: `elements/${e.name}` }));
        if (meta.tag !== `pk-${e.name}`) problems.push(`elements/${e.name}: tag must be pk-${e.name}`);
        list.push({ name: e.name, meta, template, css, behaviour });
    }
    if (problems.length) throw new Error(problems.join('\n'));
    return list;
}

export function elementModule(el, { coreImport, minifyCss = false }) {
    // A behaviour file imports shared modules as '../../js/x.js' (its source location; a static import or a lazy import('../../js/x.js')); the generated module lives elsewhere in dist.
    const jsBase = coreImport.replace(/element\.js$/, '');
    const beh = el.behaviour ? el.behaviour.replace(/^[ \t]*\/\/.*\r?\n/gm, '').replace(/(from '|import\(')\.\.\/\.\.\/js\//g, `$1${jsBase}`).replace(/^export default /m, 'const behaviour = ').trimEnd().replace(/;?$/, ';') : 'const behaviour = Base => Base;';
    const m = el.meta;
    return `// GENERATED by tools/build.mjs from elements/${el.name}/: do not edit.
import { PkElement, define } from '${coreImport}';
${beh}
export default define(class extends behaviour(PkElement) {
    static tag = ${JSON.stringify(m.tag)};
    static props = ${JSON.stringify(propsObject(m))};
    static delegatesFocus = ${Boolean(m.delegatesFocus)};
    static formAssociated = ${Boolean(m.formAssociated)};
    static template = ${JSON.stringify(el.template)};
    static css = ${JSON.stringify(minifyCss ? minify(el.css) : el.css)};
});
`;
}

const minify = css => css.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').replace(/\s*([{};,>])\s*/g, '$1').replace(/;}/g, '}').trim();

// Files under dist/js that no source in js/ (or a module's own js) produces any more: a rename or a removal leaves the old copy behind, and
// nothing else would ever notice it. Paths are relative to rootDir, with forward slashes; `out` is the build's path -> text map.
export function staleDistJs(out, rootDir = root) {
    const dir = path.join(rootDir, 'dist', 'js');
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir, { recursive: true, withFileTypes: true }).filter(e => e.isFile())
        .map(e => path.relative(rootDir, path.join(e.parentPath, e.name)).replace(/\\/g, '/'))
        .filter(f => !out.has(f)).sort();
}

// The files under dist/skills on disk, as paths relative to core with forward slashes (the build does not produce them; see the manifest below).
function skillFiles() {
    const dir = path.join(root, 'dist', 'skills');
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir, { recursive: true, withFileTypes: true }).filter(e => e.isFile()).map(e => path.relative(root, path.join(e.parentPath, e.name)).replace(/\\/g, '/'));
}

export function build({ write = true } = {}) {
    writing = write; out = new Map();
    const samples = loadSamples();
    const elements = loadElementSources();
    const foucRule = elements.length ? `${elements.map(e => `${e.meta.tag}:not(:defined)`).join(',')}{visibility:hidden}` : '';
    // The page layer, in cascade order: tokens, base, then spacing, typography, table-content and utilities, the element FOUC guard, a11y last.
    const layer = ['spacing', 'typography', 'table-content', 'utilities'];
    w('plainkit.css', `/* GENERATED by tools/build.mjs: do not edit. Entry point for a non-Blazor page. base/a11y.css is last on purpose. */\n@import url("tokens/tokens.css");\n@import url("base/base.css");\n${layer.map(n => `@import url("base/${n}.css");`).join('\n')}\n@import url("elements/elements.css");\n@import url("base/a11y.css");\n`);
    w('elements/elements.css', `/* GENERATED by tools/build.mjs: hides an pk-* element until its module has defined it, so there is no flash of unstyled content. */\n${foucRule}\n`);
    for (const el of elements) w(`elements/${el.name}/${el.name}.element.js`, elementModule(el, { coreImport: '../../js/element.js' }));
    w('elements/registry.js', `// GENERATED by tools/build.mjs: tag -> module, relative to this file. js/loader.js imports only the modules a page uses.\nexport default ${JSON.stringify(Object.fromEntries(elements.map(e => [e.meta.tag, `./${e.name}/${e.name}.element.js`])), null, 4)};\n`);
    w('site/gallery/gallery.data.js', `// GENERATED by tools/build.mjs from the sample folders and the element meta files: do not edit. Edit the source folder and run the build.\n// Static, hand-maintained parts (breakpoints, text pairs, responsive rules) are in gallery.static.js; samples come from their folders.\nexport * from './gallery.static.js';\n\nexport const TEMPLATES = ${JSON.stringify(samples.templates, null, 4)};\n\nexport const PATTERNS = ${JSON.stringify(samples.patterns, null, 4)};\n\nexport const LAYOUTS = ${JSON.stringify(samples.layouts, null, 4)};\n\nexport const ELEMENTS = ${JSON.stringify(elements.map(e => e.meta), null, 4)};\n`);

    // dist
    const tokens = read(path.join(root, 'tokens', 'tokens.css')); const base = read(path.join(root, 'base', 'base.css')); const a11y = read(path.join(root, 'base', 'a11y.css'));
    const page = [tokens, base, ...layer.map(n => read(path.join(root, 'base', `${n}.css`))), foucRule, a11y].join('\n');
    w('dist/plainkit.css', `/* GENERATED by tools/build.mjs: tokens, page-level base and utilities for the light DOM. Components are custom elements, loaded on demand by plainkit.js. */\n${page}`);
    w('dist/plainkit.min.css', minify(page) + '\n');
    for (const el of elements) w(`dist/elements/${el.name}.js`, elementModule(el, { coreImport: '../js/element.js', minifyCss: true }));
    w('dist/elements/registry.js', `// GENERATED by tools/build.mjs: tag -> module, relative to this file.\nexport default ${JSON.stringify(Object.fromEntries(elements.map(e => [e.meta.tag, `./${e.name}.js`])), null, 4)};\n`);
    for (const [name, text] of Object.entries(allManifests(elements.map(e => e.meta)))) w(`dist/${name}`, text);
    w('dist/elements/api.json', JSON.stringify(elements.map(e => e.meta), null, 2) + '\n');
    // The version (core/VERSION) is stamped into js/version.js (and its dist copy) and dist/manifest.json, so a file from a CDN, a zip or the
    // NuGet package can say which release it is. tools/versioning.mjs checks every place agrees.
    const version = read(path.join(root, 'VERSION')).trim();
    const versionModule = `// GENERATED by tools/build.mjs from VERSION: do not edit. The Plainkit release this file belongs to.
export const PK_VERSION = '${version}';
`;
    w('js/version.js', versionModule);
    w('dist/js/version.js', versionModule);
    for (const f of fs.readdirSync(path.join(root, 'js'), { recursive: true })) {
        const src = path.join(root, 'js', f);
        if (fs.statSync(src).isFile() && f.endsWith('.js')) w(`dist/js/${f.replace(/\\/g, '/')}`, read(src).replace("'../site/gallery/embed.html'", "'../gallery/embed.html'").replace("'../../modules/", "'../../")); // in dist the gallery sits next to js/, not under site/
    }
    w('dist/icons.svg', read(path.join(root, 'icons.svg')));
    // The API surface as it is now, for the scorecard's API section to diff against the baseline (kept current by the build, checked by a test).
    w('site/scorecard/api.current.json', JSON.stringify(surface(), null, 1) + '\n');
    for (const [f, text] of galleryDist(read, root, out.get('site/gallery/gallery.data.js'))) w(`dist/gallery/${f}`, text);
    for (const [f, text] of modulesDist(read, root)) w(`dist/${f}`, text);
    w('dist/plainkit.js', '// GENERATED by tools/build.mjs: one import wires every behaviour.\nexport * from \'./js/plainkit.js\';\n');
    // Supply-chain manifest: every dist file with its size and SRI hash. Deterministic (sorted, no timestamps) so a rebuild of the same
    // sources is byte-identical; consumers pin integrity="sha384-..." from here. The SDK has no runtime dependencies.
    // dist/skills (the agent skills bundle) is written by scripts/build-skills.mjs, which needs the API this build produces, so the build does not
    // produce it; the manifest lists whatever is on disk there (and that script rebuilds the manifest after writing it).
    const bytesOf = f => (out.has(f) ? Buffer.from(out.get(f)) : fs.readFileSync(path.join(root, f)));
    const files = [...new Set([...out.keys(), ...skillFiles()])].filter(f => f.startsWith('dist/')).sort().map(f => { const data = bytesOf(f); return { path: f.slice(5), bytes: data.length, integrity: 'sha384-' + crypto.createHash('sha384').update(data).digest('base64') }; });
    // The build owns dist/js: whatever it did not just produce is a leftover, and is removed so the folder is exactly the sources.
    if (write) for (const f of staleDistJs(out)) fs.rmSync(path.join(root, f));
    w('dist/manifest.json', JSON.stringify({ name: 'plainkit', version, dependencies: [], runtimeRequests: 'none (same-origin only)', licence: 'MIT', provenance: 'Generated by sdk/tools/build.mjs from the sources; reproducible.', files }, null, 2) + '\n');
    // The Files page's snapshot of core/ itself. Written last, from the files on disk with everything generated above laid over them (so a stale
    // generated file never leaks in), no timestamp (deterministic). It skips its own file and dist/, so it never includes itself.
    w('site/files/snapshot.json', JSON.stringify(collectSnapshot(root, { generated: null, overlay: new Map([...out].filter(([f]) => !f.startsWith('dist/'))) })));
    return { out, elements: elements.length, samples: Object.values(samples).reduce((n, g) => n + g.length, 0), pageCssKb: Math.round(Buffer.byteLength(page) / 102.4) / 10 };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) { const { out: _o, ...summary } = build(); console.log(summary); }

// The API a custom element declares in its meta file, and the checks that keep it true. Pure (no file access): the build and the guard
// tests pass in the parsed meta, the template and the css.
//
// elements/<name>/<name>.meta.json:
//   tag, title, summary, group          identity (tag is pk-<name>)
//   delegatesFocus, formAssociated      optional booleans
//   props[]         { name, type: string|boolean|number|enum|json (object or array: a JSON attribute or a property), default, values?, reflect, commit?, description }
//                   commit: the event (or events) that announce a change the user made to a two-way prop (value, open, checked...); each must be in events[]
//   slots[]         { name ('' = default), description, dynamic? }   dynamic: the name is a pattern such as cell-<rowId>-<key> that the element builds per row, so the template has no fixed slot of that name
//   events[]        { name, detail, description }
//   parts[]         { name, description }      ::part(name) is the styling hook
//   cssProperties[] { name (--pk-...), description, default? }
//   methods[]       { name, description }
//   a11y            keyboard and ARIA notes
//   examples[]      { title, html }   usage snippets shown in the gallery: <pk-*> markup, never a style attribute

export const PROP_TYPES = ['string', 'boolean', 'number', 'enum', 'json'];
const NAME = /^[a-z][a-zA-Z0-9]*$/;
const CSS_PROP = /^--pk-[a-z0-9-]+$/;

const isText = v => typeof v === 'string' && v.trim().length > 0;

export function validateApi(meta, { template = '', css = '', name = meta?.tag ?? '?' } = {}) {
    const p = [];
    const need = (ok, msg) => { if (!ok) p.push(`${name}: ${msg}`); };
    need(meta && typeof meta === 'object', 'meta is not an object');
    if (!meta || typeof meta !== 'object') return p;
    need(/^pk-[a-z][a-z0-9-]*$/.test(meta.tag ?? ''), 'tag must look like pk-name');
    for (const k of ['title', 'summary', 'group', 'a11y']) need(isText(meta[k]), `${k} is required`);
    for (const k of ['props', 'slots', 'events', 'parts', 'cssProperties', 'methods', 'examples']) need(Array.isArray(meta[k]), `${k} must be an array (empty when there is none)`);
    if (p.length) return p;

    const names = new Set();
    for (const d of meta.props) {
        need(NAME.test(d.name ?? ''), `prop "${d.name}" needs a camelCase name`);
        need(!names.has(d.name), `prop "${d.name}" is declared twice`); names.add(d.name);
        need(PROP_TYPES.includes(d.type), `prop "${d.name}" has type ${d.type}`);
        need('default' in d, `prop "${d.name}" needs a default`);
        need(typeof d.reflect === 'boolean', `prop "${d.name}" needs reflect true or false`);
        need(isText(d.description), `prop "${d.name}" needs a description`);
        if (d.type === 'enum') { need(Array.isArray(d.values) && d.values.length > 1, `enum prop "${d.name}" needs values`); need(d.values?.includes(d.default), `enum prop "${d.name}" default is not one of its values`); }
        if (d.type === 'boolean') need(d.default === false, `boolean prop "${d.name}" must default to false (an attribute is presence)`);
        if (d.type === 'number') need(typeof d.default === 'number', `number prop "${d.name}" needs a numeric default`);
        if (d.type === 'json') need(typeof d.default === 'object', `json prop "${d.name}" needs an object, array or null default`);
        if (d.type === 'string') need(typeof d.default === 'string', `string prop "${d.name}" needs a string default`);
    }
    for (const [k, list, key] of [['slot', meta.slots, 'name'], ['event', meta.events, 'name'], ['part', meta.parts, 'name'], ['cssProperty', meta.cssProperties, 'name'], ['method', meta.methods, 'name']]) {
        const seen = new Set();
        for (const x of list) {
            need(typeof x[key] === 'string' && (k === 'slot' || x[key] !== ''), `${k} needs a ${key}`);
            if (k === 'slot' && x.dynamic) need(/<[^>]+>/.test(x.name), `dynamic slot "${x.name}" must be a pattern with a <placeholder>`);
            need(isText(x.description), `${k} "${x[key]}" needs a description`);
            need(!seen.has(x[key]), `${k} "${x[key]}" is declared twice`); seen.add(x[key]);
        }
    }
    for (const d of meta.props) if ('commit' in d) { const named = [].concat(d.commit); need(named.length > 0 && named.every(n => typeof n === 'string' && meta.events.some(e => e.name === n)), `prop "${d.name}" commit must name events declared in events[] (${JSON.stringify(d.commit)})`); }
    for (const e of meta.events) need('detail' in e, `event "${e.name}" needs a detail (null when there is none)`);
    for (const c of meta.cssProperties) need(CSS_PROP.test(c.name), `css property "${c.name}" must start with --pk-`);

    // The template and the css are held to the API.
    const bound = new Set([...template.matchAll(/\{\{\s*([\w.]+)/g)].map(m => m[1]).concat([...template.matchAll(/data-if(?:-not)?="([\w.]+)"/g)].map(m => m[1])));
    for (const b of bound) need(names.has(b), `template binds {{${b}}} but no prop has that name`);
    const tplSlots = new Set([...template.matchAll(/<slot(?:\s+name="([^"]*)")?/g)].map(m => m[1] ?? ''));
    for (const s of tplSlots) need(meta.slots.some(x => x.name === s), `template has a slot "${s}" that meta.slots does not describe`);
    for (const s of meta.slots.filter(x => !x.dynamic)) need(tplSlots.has(s.name), `meta.slots describes "${s.name}" but the template has no such slot`);
    const tplParts = new Set([...template.matchAll(/\spart="([^"]+)"/g)].flatMap(m => m[1].split(/\s+/)));
    for (const s of tplParts) need(meta.parts.some(x => x.name === s), `template part "${s}" is not in meta.parts`);
    for (const s of meta.parts) need(tplParts.has(s.name), `meta.parts describes "${s.name}" but the template has no such part`);
    const cssUsed = new Set([...css.matchAll(/var\(\s*(--pk-[a-z0-9-]+)/g)].map(m => m[1]));
    for (const c of meta.cssProperties) need(cssUsed.has(c.name), `css property ${c.name} is declared but the css never reads it`);
    for (const u of cssUsed) need(meta.cssProperties.some(c => c.name === u), `css reads ${u} but meta.cssProperties does not declare it`);
    need(!/<style[\s>]|\sstyle\s*=/.test(template), 'the template must not carry a style element or attribute');
    need(!/\sstyle\s*=|<style[\s>]/.test(meta.examples.map(e => e.html).join('\n')), 'examples must not carry a style attribute');
    for (const e of meta.examples) need(isText(e.title) && isText(e.html), 'each example needs a title and html');
    need(meta.examples.length > 0, 'at least one example is required');
    return p;
}

// The same props as the runtime wants them: { name: { type, default, values, reflect } }.
export const propsObject = meta => Object.fromEntries(meta.props.map(({ name, type, default: d, values, reflect }) => [name, { type, default: d, ...(values ? { values } : {}), reflect }]));

// Editor and tooling artefacts generated from the element meta files (the API data is the single source):
//   custom-elements.json           Custom Elements Manifest (docs tools, Storybook, IDEs)
//   vscode.html-custom-data.json   VS Code HTML tag/attribute completion
//   web-types.json                 JetBrains IDEs and Vue tooling
//   elements.d.ts                  TypeScript: HTMLElementTagNameMap, event map, JSX intrinsic elements
//   elements.vue.d.ts              Vue 3 GlobalComponents typings (include it only in a Vue project)
// Pure: takes the parsed metas, returns { path: text }.

// Native event names keep their built-in typing (a custom detail would clash with the DOM lib).
const NATIVE_EVENTS = new Set(['change', 'input', 'click', 'submit', 'reset']);
const kebab = n => n.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`);
const pascal = tag => tag.split('-').map(p => p[0].toUpperCase() + p.slice(1)).join('');
const tsType = p => (p.type === 'enum' ? p.values.map(v => JSON.stringify(v)).join(' | ') : p.type);
const defText = p => (p.type === 'string' || p.type === 'enum' ? JSON.stringify(p.default) : String(p.default));

export function customElementsManifest(metas) {
    return {
        schemaVersion: '1.0.0',
        readme: 'GENERATED by tools/build.mjs from elements/*/*.meta.json',
        modules: metas.map(m => ({
            kind: 'javascript-module',
            path: `elements/${m.tag.slice(3)}.js`,
            declarations: [{
                kind: 'class', name: `${pascal(m.tag)}Element`, tagName: m.tag, customElement: true, description: m.summary,
                superclass: { name: 'PkElement', module: 'js/element.js' },
                attributes: m.props.filter(p => p.reflect || true).map(p => ({ name: kebab(p.name), fieldName: p.name, type: { text: tsType(p) }, default: defText(p), description: p.description })),
                members: [
                    ...m.props.map(p => ({ kind: 'field', name: p.name, type: { text: tsType(p) }, default: defText(p), description: p.description, attribute: kebab(p.name), reflects: p.reflect })),
                    ...m.methods.map(x => ({ kind: 'method', name: x.name, description: x.description })),
                ],
                events: m.events.map(e => ({ name: e.name, type: { text: 'CustomEvent' }, description: `${e.description} detail: ${e.detail}` })),
                slots: m.slots.map(s => ({ name: s.name, description: s.description })),
                cssParts: m.parts.map(p => ({ name: p.name, description: p.description })),
                cssProperties: m.cssProperties.map(c => ({ name: c.name, default: c.default, description: c.description })),
            }],
            exports: [{ kind: 'custom-element-definition', name: m.tag, declaration: { name: `${pascal(m.tag)}Element`, module: `elements/${m.tag.slice(3)}.js` } }],
        })),
    };
}

export function vscodeCustomData(metas) {
    return {
        version: 1.1,
        tags: metas.map(m => ({
            name: m.tag, description: `${m.summary}\n\nSlots: ${m.slots.map(s => s.name || '(default)').join(', ') || 'none'}.`,
            attributes: m.props.map(p => ({ name: kebab(p.name), description: p.description, ...(p.type === 'enum' ? { values: p.values.map(v => ({ name: v })) } : p.type === 'boolean' ? { valueSet: 'v' } : {}) })),
        })),
        valueSets: [{ name: 'v', values: [] }],
    };
}

export function webTypes(metas) {
    return {
        $schema: 'https://json.schemastore.org/web-types',
        name: 'plainkit', version: '1.0.0', 'js-types-syntax': 'typescript', 'description-markup': 'markdown',
        contributions: {
            html: {
                elements: metas.map(m => ({
                    name: m.tag, description: m.summary,
                    attributes: m.props.map(p => ({ name: kebab(p.name), description: p.description, value: { type: p.type === 'boolean' ? 'boolean' : p.type === 'number' ? 'number' : 'string', default: defText(p) }, ...(p.type === 'enum' ? { values: p.values } : {}) })),
                    slots: m.slots.map(s => ({ name: s.name || 'default', description: s.description })),
                    events: m.events.map(e => ({ name: e.name, description: e.description })),
                })),
            },
        },
    };
}

export function typings(metas) {
    const out = ['// GENERATED by tools/build.mjs from elements/*/*.meta.json: do not edit.', '// Include in tsconfig ("include" or a /// <reference>) for tag, property, event and JSX autocomplete.', ''];
    for (const m of metas) {
        const iface = `${pascal(m.tag)}Element`;
        out.push(`export interface ${iface} extends HTMLElement {`);
        for (const p of m.props) out.push(`    /** ${p.description} */`, `    ${p.name}: ${tsType(p)};`);
        for (const x of m.methods) out.push(`    /** ${x.description} */`, `    ${x.name}(...args: unknown[]): unknown;`);
        out.push('}', '');
    }
    out.push('declare global {', '    interface HTMLElementTagNameMap {');
    for (const m of metas) out.push(`        '${m.tag}': ${pascal(m.tag)}Element;`);
    out.push('    }', '    interface HTMLElementEventMap {');
    const events = new Map();
    for (const m of metas) for (const e of m.events) if (!events.has(e.name) && !NATIVE_EVENTS.has(e.name)) events.set(e.name, e.detail);
    for (const [n, d] of events) out.push(`        '${n}': CustomEvent<${/^\{/.test(d) && d !== 'null' ? d.replace(/[{}]/g, '').split(',').map(s => s.trim()).filter(Boolean).length ? `{ ${d.replace(/[{}]/g, '').split(',').map(s => `${s.trim()}: unknown`).join('; ')} }` : 'unknown' : 'unknown'}>;`);
    out.push('    }', '    namespace JSX {', '        interface IntrinsicElements {');
    for (const m of metas) out.push(`            '${m.tag}': PkJsx<${pascal(m.tag)}Element, ${m.props.length ? m.props.map(p => JSON.stringify(p.name)).join(' | ') : 'never'}>;`);
    out.push('        }', '    }', '}', '', '/** Props (as attributes or properties), slot, class and children of an pk-* element in JSX. */',
        'export type PkJsx<T, K extends keyof T> = Partial<Pick<T, K>> & { slot?: string; class?: string; className?: string; id?: string; children?: unknown; ref?: unknown; [event: `on${string}`]: unknown };', '');
    return out.join('\n');
}

export function vueTypings(metas) {
    const out = ['// GENERATED by tools/build.mjs from elements/*/*.meta.json: do not edit. Include only in a Vue 3 project.', "import type { DefineComponent } from 'vue';", "import type * as E from './elements';", '', "declare module 'vue' {", '    interface GlobalComponents {'];
    for (const m of metas) out.push(`        '${m.tag}': DefineComponent<Partial<Pick<E.${pascal(m.tag)}Element, ${m.props.length ? m.props.map(p => JSON.stringify(p.name)).join(' | ') : 'never'}>>>;`);
    out.push('    }', '}', '', 'export {};', '');
    return out.join('\n');
}

export function allManifests(metas) {
    return {
        'custom-elements.json': JSON.stringify(customElementsManifest(metas), null, 2) + '\n',
        'vscode.html-custom-data.json': JSON.stringify(vscodeCustomData(metas), null, 2) + '\n',
        'web-types.json': JSON.stringify(webTypes(metas), null, 2) + '\n',
        'elements.d.ts': typings(metas),
        'elements.vue.d.ts': vueTypings(metas),
    };
}

// The gallery as it ships in dist/gallery: the source files from site/gallery with their paths resolved for the dist layout, so the
// folder works wherever dist/ is copied or served from. Pure: the build passes in a reader and the generated data file's text.
import fs from 'node:fs';
import path from 'node:path';

// Files copied as they are, plus the rewritten ones. standalone.js and index.html are the SDK site's own host page and stay out.
const COPY = ['gallery.js', 'settings.js', 'frame.js', 'frame-boot.js', 'frame.css', 'gallery.css', 'gallery.static.js', 'elements-view.js', 'sample-tree.js', 'embed.js', 'preview.js'];

// The dist layout puts js/, plainkit.css and icons.svg one level above the gallery folder, not two: drop one "../" from a specifier that
// climbs out of the folder. depth is how many folders deep the file sits inside the gallery folder.
export const relocate = (text, depth = 0) => text.replace(new RegExp(String.raw`(['"\`])((?:\.\./){${depth + 2},})`, 'g'), (_m, q, ups) => q + ups.slice(3));

const paths = `// GENERATED by tools/build.mjs: where the gallery finds the SDK's files, relative to this folder (the dist layout).

export const ROOT = new URL('../', import.meta.url).href;

// Stylesheets a sample frame loads, in order.
export const PAGE_CSS = ['../plainkit.css'];

export const TOKENS_CSS = 'tokens.css';
export const UTILITIES_CSS = 'utilities.css';
export const SPACING_CSS = 'spacing.css';
export const ICONS = '../icons.svg';

// The SDK site pages (theme editor, scorecard, files) are not part of dist.
export const HAS_SITE = false;

// Where the full-page templates live, relative to this folder.
export const TEMPLATES_DIR = 'templates/';

// Where a pattern's optional script lives, relative to this folder.
export const PATTERNS_DIR = 'patterns/';

// The page that hosts a pattern or layout fragment as a whole page.
export const PREVIEW = 'preview.html';
`;

export function galleryDist(read, root, dataText) {
    const dir = path.join(root, 'site', 'gallery');
    const files = new Map();
    for (const f of COPY) files.set(f, relocate(read(path.join(dir, f))));
    files.set('gallery.data.js', dataText);
    files.set('paths.js', paths);
    files.set('boots/code-explorer.js', relocate(read(path.join(dir, 'boots', 'code-explorer.js')), 1).replaceAll('/modules/code-explorer/', '/code-explorer/'));
    // The gallery's own chrome and pages are pk-* elements, so the embed page needs only the page layer.
    files.set('embed.html', read(path.join(dir, 'embed.html')).replace('href="../../plainkit.css">', 'href="../plainkit.css">').replace('href="../site.css"', 'href="site.css"'));
    // The preview host (patterns and layouts as a whole page) loads the same stylesheet as the embed page.
    files.set('preview.html', read(path.join(dir, 'preview.html')).replace('href="../../plainkit.css">', 'href="../plainkit.css">'));
    // The full-page templates sit at the same depth under dist/gallery/templates as under samples/templates, so their relative paths hold;
    // they only need the toast module's dist name.
    const tdir = path.join(root, 'samples', 'templates');
    for (const f of fs.readdirSync(tdir, { recursive: true }).map(x => x.replaceAll('\\', '/')).filter(x => /\.(html|js|css)$/.test(x)).sort()) {
        files.set(`templates/${f}`, read(path.join(tdir, f))
            .replace('../../../elements/toast-stack/toast-stack.element.js', '../../../elements/toast-stack.js')
            .replace('../../site/gallery/preview.html', '../preview.html'));
    }
    // A pattern's optional script (samples/patterns/<id>/<id>.js) is loaded by preview.js from patterns/<id>/<id>.js, at the same depth as the source.
    const pdir = path.join(root, 'samples', 'patterns');
    for (const f of fs.readdirSync(pdir, { recursive: true }).map(x => x.replaceAll('\\', '/')).filter(x => /\.js$/.test(x)).sort()) files.set(`patterns/${f}`, read(path.join(pdir, f)));
    files.set('site.css', read(path.join(root, 'site', 'site.css')));
    files.set('tokens.css', read(path.join(root, 'tokens', 'tokens.css')));
    // The Foundations pages list the utility and spacing classes from their source files.
    for (const n of ['utilities', 'spacing']) files.set(`${n}.css`, read(path.join(root, 'base', `${n}.css`)));
    return files;
}

// The tool modules as they ship in dist/<name>/: the source in modules/<name>/ with its paths resolved for the dist layout, so each
