// SDK security and defect scanner: node core/tools/security.mjs [--write]   (dependency-free)
// Scans the SDK's own source (not dist/, not the generated snapshot) and returns findings { severity, rule, file, line, message }.
// Severity: critical, high, medium, low. `--write` refreshes site/scorecard/security-report.json and security.baseline.json (the ratchet:
// counts per severity may only go down). Rules that need a decision list their allowed uses in tools/security.allow.json.

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

export const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SKIP_DIRS = new Set(['dist', 'node_modules']);
const SKIP_FILES = new Set(['snapshot.json', 'security-report.json', 'report.json', 'sweep-report.json']);

export function walk(dir = root) {
    return fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => (e.isDirectory() ? (SKIP_DIRS.has(e.name) ? [] : walk(path.join(dir, e.name))) : [path.join(dir, e.name)]));
}

const rel = f => path.relative(root, f).split(path.sep).join('/');
const isTest = f => /\.test\.mjs$|(^|\/)tests\//.test(f);

// Each rule: { id, severity, files: regex, pattern: regex, message, skipTests? }
export const RULES = [
    { id: 'no-eval', severity: 'critical', files: /\.(js|mjs|html)$/, pattern: /\beval\s*\(/, message: 'eval() runs arbitrary code', skipTests: true },
    { id: 'no-new-function', severity: 'critical', files: /\.(js|mjs|html)$/, pattern: /\bnew\s+Function\s*\(/, message: 'new Function() runs arbitrary code' },
    { id: 'no-document-write', severity: 'high', files: /\.(js|mjs|html)$/, pattern: /\bdocument\.write(ln)?\s*\(/, message: 'document.write injects unparsed markup' },
    { id: 'no-javascript-url', severity: 'high', files: /\.(js|mjs|html)$/, pattern: /['"`(]\s*javascript:/i, message: 'javascript: URL' },
    { id: 'no-inline-handler', severity: 'high', files: /\.html$/, pattern: /\s(onclick|onload|onerror|oninput|onchange|onsubmit|onmouseover|onfocus)\s*=/i, message: 'inline event handler attribute (blocked by a strict CSP)' },
    { id: 'no-inline-style-attr', severity: 'high', files: /\.html$/, pattern: /\sstyle\s*=\s*["']/, message: 'inline style attribute (blocked by a strict style-src): use a token, a utility or component class, or set the value through the CSSOM', skipTests: true },
    { id: 'no-inline-style-attr-js', severity: 'high', files: /\.(js|mjs|json)$/, pattern: /\sstyle=\\?["'`]|setAttribute\(\s*['"]style['"]|createElement\(\s*['"]style['"]/, message: 'markup built with an inline style attribute or a style element: use the CSSOM (el.style.setProperty) or data-dyn (js/dynamic.js)', skipTests: true },
    { id: 'blank-needs-noopener', severity: 'medium', files: /\.(js|mjs|html)$/, pattern: /target=(\\?["'])_blank\1(?![^>]*noopener)/, message: 'target=_blank without rel=noopener' },
    { id: 'secret-private-key', severity: 'critical', files: /.*/, pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----/, message: 'private key material' },
    { id: 'secret-token', severity: 'critical', files: /.*/, pattern: /\b(AKIA[0-9A-Z]{16}|ghp_[A-Za-z0-9]{30,}|sk-[A-Za-z0-9]{32,}|xox[baprs]-[A-Za-z0-9-]{10,})\b/, message: 'looks like an API key or token' },
    { id: 'secret-assignment', severity: 'high', files: /\.(js|mjs|json|html)$/, pattern: /\b(password|passwd|secret|api[_-]?key|access[_-]?token)\b["']?\s*[:=]\s*["'][^"'\s]{8,}["']/i, message: 'credential-like literal', skipTests: true },
    { id: 'secret-email', severity: 'low', files: /\.(js|mjs|json|html|md|css)$/, pattern: /\b[A-Za-z0-9._%+-]+@(?!example\.(com|org)|localhost)[A-Za-z0-9.-]+\.[a-z]{2,}\b/, message: 'email address in the repository' },
    { id: 'no-external-request', severity: 'high', files: /\.(js|mjs|html|css)$/, pattern: /(?:src|href|url\(|import\s*\(|from\s+|fetch\s*\()\s*=?\s*["'(]?\s*https?:\/\/(?!localhost|www\.w3\.org)/, message: 'third-party or CDN request at runtime', skipTests: true },
];

// innerHTML-style sinks: allowed per file up to the count in security.allow.json, each documented there with its source of markup.
const SINK = /\b(innerHTML|outerHTML|insertAdjacentHTML)\b/g;

function lines(text) { return text.split('\n'); }

// A let/var is fine when the file assigns to it on another line: name = ..., name += ..., name++, ++name.
export function isReassigned(ls, name, declLine) {
    const re = new RegExp(`(?:\\b${name}\\s*(?:[-+*/%&|^]|\\*\\*|<<|>>>?|&&|\\|\\||\\?\\?)?=(?!=)|\\b${name}\\s*(?:\\+\\+|--)|(?:\\+\\+|--)${name}\\b)`);
    return ls.some((l, i) => i !== declLine && re.test(l));
}

export function scan(opts = {}) {
    const findings = [];
    const files = walk().filter(f => !SKIP_FILES.has(path.basename(f)) && /\.(js|mjs|html|css|json|md)$/.test(f));
    const allow = JSON.parse(fs.readFileSync(path.join(root, 'tools', 'security.allow.json'), 'utf8'));
    for (const f of files) {
        const r = rel(f); const text = fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n'); const ls = lines(text);
        for (const rule of RULES) {
            if (!rule.files.test(r) || (rule.skipTests && isTest(r)) || r.startsWith('tools/security.') || r === 'tests/security.test.mjs') continue;
            ls.forEach((l, i) => { if (rule.pattern.test(l)) findings.push({ severity: rule.severity, rule: rule.id, file: r, line: i + 1, message: rule.message }); });
        }
        if (/\.(js|mjs)$/.test(r) && !isTest(r) && !r.startsWith('tools/security.')) {
            const hits = []; ls.forEach((l, i) => { for (const m of l.matchAll(SINK)) hits.push(i + 1); });
            const allowed = allow.htmlSinks[r]?.count ?? 0;
            if (hits.length > allowed) hits.slice(allowed).forEach(line => findings.push({ severity: 'medium', rule: 'html-sink-not-allow-listed', file: r, line, message: `innerHTML-style sink ${hits.length} > allowed ${allowed}; document its source in tools/security.allow.json or use textContent/DOM APIs` }));
            ls.forEach((l, i) => { if (/\bcreateElement\(\s*['"]script['"]\s*\)|\.src\s*=\s*['"`]?http/.test(l) && !allow.dynamicScript.includes(r)) findings.push({ severity: 'high', rule: 'dynamic-script-injection', file: r, line: i + 1, message: 'creates a script element dynamically' }); });
        }
        if (/\.html$/.test(r) && !r.startsWith('dist/')) {
            const inline = [...text.matchAll(/<script(?![^>]*\ssrc=)[^>]*>/g)];
            for (const m of inline) findings.push({ severity: 'low', rule: 'csp-inline-script', file: r, line: text.slice(0, m.index).split('\n').length, message: 'inline script: needs script-src \'unsafe-inline\' or a nonce; move it to a .js file for a strict CSP' });
            for (const m of text.matchAll(/<style[\s>]/g)) findings.push({ severity: 'high', rule: 'csp-inline-style', file: r, line: text.slice(0, m.index).split('\n').length, message: 'inline <style> block' });
        }
        if (/\.html$/.test(r) && !r.startsWith('dist/')) {
            const ids = [...text.matchAll(/\sid="([^"]+)"/g)].map(m => m[1]); const seen = new Set();
            for (const id of ids) { if (seen.has(id)) findings.push({ severity: 'medium', rule: 'duplicate-id', file: r, line: 1, message: `duplicate id "${id}"` }); seen.add(id); }
            for (const m of text.matchAll(/aria-(?:labelledby|controls|describedby)="([^"]+)"/g)) for (const ref of m[1].split(/\s+/)) if (!seen.has(ref) && !/\$\{/.test(ref)) findings.push({ severity: 'low', rule: 'aria-reference-unresolved', file: r, line: text.slice(0, m.index).split('\n').length, message: `aria reference "${ref}" has no matching id in this file` });
        }
        if (/\.css$/.test(r) && !r.startsWith('dist/')) {
            const important = (text.match(/!important/g) ?? []).length;
            if (important) findings.push({ severity: 'low', rule: 'css-important', file: r, line: 1, message: `${important} !important`, count: important });
        }
        if (/\.(js|mjs)$/.test(r) && !isTest(r) && !r.startsWith('tools/')) {
            if (/\bstorage\.setItem|localStorage\.setItem/.test(text) && !/try\s*\{[^}]*(localStorage|storage)\./.test(text) && !/=> \{ try \{/.test(text)) findings.push({ severity: 'low', rule: 'storage-unguarded', file: r, line: 1, message: 'localStorage write with no try/catch nearby' });
            ls.forEach((l, i) => { if (/addEventListener\(\s*['"]message['"]/.test(l) && !/\.origin/.test(text)) findings.push({ severity: 'high', rule: 'postmessage-origin', file: r, line: i + 1, message: 'message listener without an origin check' }); });
            ls.forEach((l, i) => { const d = /^\s*(let|var)\s+(\w+)/.exec(l); if (d && !allow.legacyVar.includes(r) && !isReassigned(ls, d[2], i)) findings.push({ severity: 'low', rule: 'prefer-const', file: r, line: i + 1, message: 'let/var that is never reassigned: use const' }); });
        }
    }
    // supply chain: zero runtime dependencies
    for (const f of ['package-lock.json', 'yarn.lock', 'pnpm-lock.yaml']) if (fs.existsSync(path.join(root, f))) findings.push({ severity: 'high', rule: 'dependency-present', file: f, line: 1, message: 'the SDK must have zero runtime dependencies; audit any dev dependency (npm audit) before adding one' });
    // a package.json is allowed for publishing, but declares no dependencies
    if (fs.existsSync(path.join(root, 'package.json'))) { const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')); for (const k of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) if (pkg[k]) findings.push({ severity: 'high', rule: 'dependency-present', file: 'package.json', line: 1, message: `package.json declares ${k}` }); }
    return findings;
}

const ORDER = { critical: 0, high: 1, medium: 2, low: 3 };
export const bySeverity = f => f.reduce((o, x) => ({ ...o, [x.severity]: (o[x.severity] ?? 0) + 1 }), { critical: 0, high: 0, medium: 0, low: 0 });
export const worstFirst = f => [...f].sort((a, b) => ORDER[a.severity] - ORDER[b.severity] || a.file.localeCompare(b.file) || a.line - b.line);

export { unsafeRegex } from '../modules/code-explorer/providers.js';

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    const findings = worstFirst(scan());
    const counts = bySeverity(findings);
    console.log(counts);
    for (const f of findings.filter(x => x.severity === 'critical' || x.severity === 'high')) console.log(`${f.severity} ${f.rule} ${f.file}:${f.line} ${f.message}`);
    if (process.argv.includes('--write')) {
        fs.writeFileSync(path.join(root, 'site', 'scorecard', 'security-report.json'), JSON.stringify({ generated: 'see baseline', counts, findings }, null, 2) + '\n');
        fs.writeFileSync(path.join(root, 'site', 'scorecard', 'security.baseline.json'), JSON.stringify({ note: 'Counts per severity may only go down. Refresh with node tools/security.mjs --write after a fix.', counts }, null, 2) + '\n');
    }
}

// A dependency-free static file server for the SDK folder: node core/tools/serve.mjs [port]  (default 5310).
// Any static server works; this exists so the gallery can be opened with one command and nothing installed.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const port = Number(process.argv.find(a => /^\d+$/.test(a))) || 5310;
// --csp (alias --csp=strict) serves script-src 'self' and style-src 'self': no inline scripts, no inline styles, no style elements. The scanner
// (tools/security.mjs) and tests/security.test.mjs enforce it in source, and the carve-out test serves the whole site under it.
const csp = process.argv.some(a => a === '--csp' || a === '--csp=strict') ? "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; frame-ancestors 'self'" : null;
const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml' };

// --base=/sdk/1.0.0/ serves the folder under a prefix, as a CDN or a subfolder would: the site uses only relative paths, so it works.
const baseArg = process.argv.find(a => a.startsWith('--base='));
const base = baseArg ? '/' + baseArg.slice(7).replace(/^\/+|\/+$/g, '') : '';
const writeReports = process.argv.includes('--write-reports');

http.createServer((req, res) => {
    // Dev only: --write-reports lets the scorecard page store its sweep results next to the other reports.
    if (writeReports && req.method === 'POST' && req.url.startsWith('/__report')) {
        let body = '';
        req.on('data', c => { body += c; if (body.length > 5_000_000) req.destroy(); });
        req.on('end', () => {
            try {
                const data = JSON.parse(body); const q = new URL(req.url, 'http://x').searchParams; const dir = path.join(root, 'site', 'scorecard');
                if (q.get('kind') === 'browser') { fs.writeFileSync(path.join(root, 'tests', 'browser', 'report.json'), JSON.stringify(data, null, 1) + '\n'); res.writeHead(204).end(); return; }
                const parts = path.join(dir, '.sweep-parts'); fs.mkdirSync(parts, { recursive: true });
                if (q.get('part')) fs.writeFileSync(path.join(parts, q.get('part').replace(/[^\w-]/g, '_') + '.json'), body);
                if (q.get('final') === '1' || !q.get('part')) {
                    // A finished run: parts are merged into one report (the whole sweep, in stages).
                    const list = fs.existsSync(parts) ? fs.readdirSync(parts).map(f => JSON.parse(fs.readFileSync(path.join(parts, f), 'utf8'))) : [data];
                    const merged = { partial: false, checked: list.reduce((n, p) => n + p.checked, 0), failures: list.flatMap(p => p.failures), widths: data.widths ?? [320, 375, 640, 1024, 1280, 1920], themes: data.themes ?? ['dark', 'light'] };
                    fs.writeFileSync(path.join(dir, 'sweep-report.json'), JSON.stringify(merged, null, 1));
                    if (fs.existsSync(parts)) fs.rmSync(parts, { recursive: true });
                }
                res.writeHead(204).end();
            } catch { res.writeHead(400).end(); }
        });
        return;
    }
    let pathname = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (base) {
        if (pathname !== base && !pathname.startsWith(base + '/')) { res.writeHead(404).end('not found'); return; }
        pathname = pathname.slice(base.length) || '/';
    }
    let file = path.join(root, pathname);
    if (!file.startsWith(root)) { res.writeHead(403).end(); return; }
    if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, 'index.html');
    fs.readFile(file, (err, data) => {
        if (err) { res.writeHead(404).end('not found'); return; }
        res.writeHead(200, { 'content-type': types[path.extname(file)] ?? 'application/octet-stream', 'cache-control': 'no-store', ...(csp ? { 'content-security-policy': csp } : {}) }).end(data);
    });
}).listen(port, () => console.log(`SDK site on http://localhost:${port}/`));

// Emits a static snapshot of a folder for the code explorer: node core/tools/snapshot.mjs [folder] [output.json]
// With no arguments it runs the SDK build, which writes the SDK's own snapshot (site/files/snapshot.json, the Files page) together with everything
// else it generates; that one is deterministic (no timestamp), so it stays current with the sources. A folder argument snapshots that folder with
// a timestamp. The format is documented in modules/code-explorer/providers.js: { version, generated, files: [ { path, language, content, symbols } ] }.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const TEXT = new Set(['.css', '.js', '.mjs', '.ts', '.tsx', '.jsx', '.html', '.svg', '.json', '.md', '.cs', '.razor', '.py', '.java', '.go', '.rs', '.sql', '.yml', '.yaml']);
// report.json (the browser attestation) is rewritten by every run, so a snapshot that held it would be stale after each attestation.
const SKIP_FILES = new Set(['snapshot.json', 'sweep-report.json', 'package-lock.json', 'report.json']);
const SKIP_DIRS = new Set(['dist', 'node_modules', '.git', 'bin', 'obj']);
const MAX_BYTES = 512 * 1024;

function walk(dir, skipDirs) {
    return fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => {
        const p = path.join(dir, e.name);
        return e.isDirectory() ? (skipDirs.has(e.name) ? [] : walk(p, skipDirs)) : [p];
    });
}

// Declarations worth listing in the outline: JS/TS functions, classes and consts at the top level, CSS rules with a class selector.
export function symbolsOf(content, ext) {
    const symbols = [];
    const lines = content.split('\n');
    if (['js', 'mjs', 'ts', 'tsx', 'jsx'].includes(ext)) lines.forEach((line, i) => {
        const m = /^(export )?(async )?(function|class|const)\s+([A-Za-z_$][\w$]*)/.exec(line);
        if (m) symbols.push({ kind: m[3], name: m[4], line: i + 1, depth: 0 });
    });
    if (ext === 'css') lines.forEach((line, i) => {
        const m = /^(\.[\w-]+)[^{]*\{/.exec(line);
        if (m) symbols.push({ kind: 'rule', name: m[1], line: i + 1, depth: 0 });
    });
    return symbols;
}

// The snapshot document for `folder`: text files only, oversize files skipped, paths relative to the folder with forward slashes, sorted by
// that path (not by the platform's separator, so every OS produces the same bytes). `overlay` (relative path -> text) replaces what is on disk
// and adds files that are not written yet: the build passes what it is about to generate, so the snapshot never reads a stale generated file.
export function collectSnapshot(folder, { skipDirs = SKIP_DIRS, generated = new Date().toISOString(), overlay = new Map() } = {}) {
    const entries = new Map();
    for (const p of walk(folder, skipDirs)) entries.set(path.relative(folder, p).split(path.sep).join('/'), p);
    for (const rel of overlay.keys()) if (!rel.split('/').some(d => skipDirs.has(d))) entries.set(rel, null);
    const files = [...entries].filter(([rel, p]) => TEXT.has(path.extname(rel)) && !SKIP_FILES.has(path.basename(rel)) && (p === null ? Buffer.byteLength(overlay.get(rel)) : fs.statSync(p).size) <= MAX_BYTES)
        .sort(([x], [y]) => (x < y ? -1 : x > y ? 1 : 0))
        .map(([rel, p]) => {
            const content = (overlay.has(rel) ? overlay.get(rel) : fs.readFileSync(p, 'utf8')).replace(/\r\n/g, '\n');
            const ext = path.extname(rel).slice(1);
            return { path: rel, language: ext === 'mjs' ? 'js' : ext, content, symbols: symbolsOf(content, ext) };
        });
    return { version: 1, generated, files };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    const [folder, out] = process.argv.slice(2);
    if (!folder) {
        const { build } = await import('./build.mjs');
        build();
        console.log('site/files/snapshot.json written by the build');
    } else {
        const snapshot = collectSnapshot(path.resolve(folder));
        const target = path.resolve(out ?? 'snapshot.json');
        fs.writeFileSync(target, JSON.stringify(snapshot));
        console.log(`${snapshot.files.length} files snapshotted to ${target}`);
    }
}

// Which elements a piece of markup uses, worked out from the <pk-name> tags it carries. Shared by the samples test (each sample's meta
// "used" list is checked against it) and tools/samples-sync.mjs. The names are the element folder names, without the pk- prefix.

import fs from 'node:fs';
import path from 'node:path';

// The elements used by markup or by a script that builds it: [name] for every <pk-name> tag that is a real element.
export function usedElements(text, elementNames = new Set()) {
    return [...new Set([...text.matchAll(/<pk-([a-z][a-z0-9-]*)/g)].map(m => m[1]).filter(n => elementNames.has(n)))].sort();
}

export function elementFolders(root) {
    const dir = path.join(root, 'elements');
    return new Set(fs.existsSync(dir) ? fs.readdirSync(dir, { withFileTypes: true }).filter(e => e.isDirectory()).map(e => e.name) : []);
}

// Versioning: one version for the SDK and PlainKit.Blazor, kept in core/VERSION (SemVer). Everything else is stamped from it or checked
// against it. Dependency-free. See CONTRIBUTING.md (release pull request) and issue #23.
//
//   node core/tools/versioning.mjs check                 every place the version appears agrees with core/VERSION
//   node core/tools/versioning.mjs check --release       ...and the API baseline was refreshed for this version (a release PR)
//   node core/tools/versioning.mjs check --tag v0.1.0    ...and the tag names exactly that version (the release workflow)
//   node core/tools/versioning.mjs set 0.2.0             write core/VERSION and core/package.json, then run the build to stamp the rest
//   node core/tools/versioning.mjs bump [--baseline f]   what the API changes since the last release need, and whether core/VERSION covers them
//                                                        (--baseline: the baseline file of the base branch, for a release PR; --require exits 1 when not covered)
//
// Rules: a breaking change (anything in the previous release's API baseline that is gone or changed) needs a major bump, or a minor bump
// while the major is 0; a new public item needs at least a minor bump; anything else at least a patch (or a pre-release step).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repo = path.resolve(root, '..');

export const SEMVER = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

// { major, minor, patch, pre: [identifiers] } or null when the text is not a SemVer 2.0 version.
export function parseVersion(text) {
    const m = SEMVER.exec(String(text ?? '').trim());
    return m ? { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), pre: m[4] ? m[4].split('.') : [] } : null;
}

export const isPrerelease = v => (parseVersion(v)?.pre.length ?? 0) > 0;

// SemVer precedence: -1, 0 or 1. A pre-release sorts before its release; identifiers compare numerically when both are numbers, else as text,
// and a shorter list sorts first when the rest is equal.
export function compareVersions(a, b) {
    const x = parseVersion(a), y = parseVersion(b);
    if (!x || !y) throw new Error(`not a version: ${!x ? a : b}`);
    for (const k of ['major', 'minor', 'patch']) if (x[k] !== y[k]) return x[k] < y[k] ? -1 : 1;
    if (!x.pre.length && !y.pre.length) return 0;
    if (!x.pre.length) return 1;
    if (!y.pre.length) return -1;
    for (let i = 0; i < Math.max(x.pre.length, y.pre.length); i++) {
        const p = x.pre[i], q = y.pre[i];
        if (p === undefined) return -1;
        if (q === undefined) return 1;
        if (p === q) continue;
        const pn = /^\d+$/.test(p), qn = /^\d+$/.test(q);
        if (pn && qn) return Number(p) < Number(q) ? -1 : 1;
        if (pn !== qn) return pn ? -1 : 1;
        return p < q ? -1 : 1;
    }
    return 0;
}

const LEVELS = ['none', 'prerelease', 'patch', 'minor', 'major'];
const rank = l => LEVELS.indexOf(l);

// How far `to` is from `from`: 'major', 'minor', 'patch', 'prerelease' (same numbers, a later pre-release or the release of one), 'none' (equal)
// or 'downgrade'.
export function changeLevel(from, to) {
    const c = compareVersions(from, to);
    if (c === 0) return 'none';
    if (c > 0) return 'downgrade';
    const x = parseVersion(from), y = parseVersion(to);
    if (x.major !== y.major) return 'major';
    if (x.minor !== y.minor) return 'minor';
    if (x.patch !== y.patch) return 'patch';
    return 'prerelease';
}

// What an API diff needs, from two surfaces { classes, tokens, exports, elements } (see api-surface.mjs): the items in `before` that are
// missing from `after` are breaking (a changed default, type or enum value shows up as one removed and one added item), items only in `after`
// are new. Returns { required: 'breaking' | 'feature' | 'fix', removed: [...], added: [...] }.
export function requiredBump(before, after, keys = ['classes', 'tokens', 'exports', 'elements']) {
    const removed = [], added = [];
    for (const k of keys) {
        const b = new Set(before[k] ?? []), a = new Set(after[k] ?? []);
        for (const x of b) if (!a.has(x)) removed.push(`${k}: ${x}`);
        for (const x of a) if (!b.has(x)) added.push(`${k}: ${x}`);
    }
    return { required: removed.length ? 'breaking' : added.length ? 'feature' : 'fix', removed, added };
}

// The least change level a bump of the given kind must be, for a release whose previous version is `previous`.
export function minimumLevel(required, previous) {
    const major = parseVersion(previous)?.major ?? 0;
    if (required === 'breaking') return major === 0 ? 'minor' : 'major';
    if (required === 'feature') return 'minor';
    return 'prerelease';
}

// Does `next` cover what the API changes need over `previous`? { ok, level, minimum, reason }.
export function coversBump(previous, next, required) {
    const level = changeLevel(previous, next);
    const minimum = minimumLevel(required, previous);
    if (level === 'downgrade' || level === 'none') return { ok: false, level, minimum, reason: `${next} is not newer than the previous release ${previous}` };
    const ok = rank(level) >= rank(minimum);
    return { ok, level, minimum, reason: ok ? '' : `${required === 'breaking' ? 'breaking changes' : 'new public items'} since ${previous} need at least a ${minimum} bump; ${previous} to ${next} is a ${level} bump` };
}

// ---- the files the version appears in --------------------------------------------------------------------------------------------------
const readText = f => fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n');
export const readVersion = (dir = root) => readText(path.join(dir, 'VERSION')).trim();

// Every place that must agree with core/VERSION: [{ file, found }] for the ones that do not. Missing files are skipped (a fresh checkout before
// the first build has no dist).
export function versionMismatches(dir = root, repoDir = path.resolve(dir, '..')) {
    const expected = readVersion(dir);
    const found = [];
    const at = (rel, base, extract) => {
        const f = path.join(base, rel);
        if (!fs.existsSync(f)) return;
        const got = extract(readText(f));
        if (got !== expected) found.push({ file: path.relative(repoDir, f).split(path.sep).join('/'), found: got ?? '(not found)' });
    };
    at('package.json', dir, t => JSON.parse(t).version);
    at('js/version.js', dir, t => /PK_VERSION = '([^']+)'/.exec(t)?.[1]);
    at('dist/js/version.js', dir, t => /PK_VERSION = '([^']+)'/.exec(t)?.[1]);
    at('dist/manifest.json', dir, t => JSON.parse(t).version);
    return found;
}

// A release tag names exactly the version: v0.1.0-alpha.1 for core/VERSION 0.1.0-alpha.1.
export const tagMatches = (tag, version) => tag === `v${version}`;

// ---- command line ----------------------------------------------------------------------------------------------------------------------
async function main(argv) {
    const [cmd, arg] = argv;
    if (cmd === 'check') {
        const version = readVersion();
        const problems = [];
        if (!parseVersion(version)) problems.push(`core/VERSION is not a SemVer version: "${version}"`);
        for (const m of versionMismatches()) problems.push(`${m.file} says ${m.found}, core/VERSION says ${version}`);
        const props = readText(path.join(repo, 'Directory.Build.props'));
        if (!/ReadAllText\(.*core\/VERSION/.test(props)) problems.push('Directory.Build.props does not read the version from core/VERSION');
        if (argv.includes('--release')) {
            // A release pull request refreshes the API baseline last: it must describe exactly the version being released.
            const baseline = JSON.parse(readText(path.join(root, 'site', 'scorecard', 'api.baseline.json')));
            if (baseline.release !== version) problems.push(`site/scorecard/api.baseline.json is for ${baseline.release ?? 'no release'}, not ${version}: run node core/tools/api-surface.mjs --write --release ${version}`);
        }
        const tagAt = argv.indexOf('--tag');
        if (tagAt >= 0 && !tagMatches(argv[tagAt + 1], version)) problems.push(`the tag ${argv[tagAt + 1]} is not v${version}`);
        if (problems.length) { console.error(problems.join('\n')); process.exit(1); }
        console.log(`version ${version}: consistent${isPrerelease(version) ? ' (pre-release)' : ''}`);
    } else if (cmd === 'set') {
        if (!parseVersion(arg)) { console.error(`not a SemVer version: ${arg}`); process.exit(2); }
        fs.writeFileSync(path.join(root, 'VERSION'), `${arg}\r\n`);
        const pkgFile = path.join(root, 'package.json');
        const raw = readText(pkgFile);
        const eol = fs.readFileSync(pkgFile, 'utf8').includes('\r\n') ? '\r\n' : '\n';
        fs.writeFileSync(pkgFile, raw.replace(/("version"\s*:\s*")[^"]+(")/, `$1${arg}$2`).replace(/\n/g, eol));
        console.log(`core/VERSION and core/package.json are ${arg}. Run node core/tools/build.mjs to stamp dist, then node scripts/publish-dist.mjs.`);
    } else if (cmd === 'bump') {
        const { surface } = await import('./api-surface.mjs');
        const from = argv.indexOf('--baseline');
        const baseline = JSON.parse(readText(from >= 0 ? path.resolve(argv[from + 1]) : path.join(root, 'site', 'scorecard', 'api.baseline.json')));
        const version = readVersion();
        const r = requiredBump(baseline, surface());
        console.log(`API changes since the last release${baseline.release ? ` (${baseline.release})` : ''}: ${r.required} (${r.removed.length} removed or changed, ${r.added.length} added)`);
        if (baseline.release) {
            const c = coversBump(baseline.release, version, r.required);
            console.log(c.ok ? `${version} covers it (${c.level} bump, needs at least ${c.minimum})` : `NOT COVERED: ${c.reason}`);
            if (!c.ok && argv.includes('--require')) process.exit(1);
        } else console.log('No previous release: nothing to compare against yet.');
    } else {
        console.error('usage: versioning.mjs check [--tag vX.Y.Z] | set <version> | bump [--require]');
        process.exit(2);
    }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main(process.argv.slice(2));
